// The Italian of What's new, what each version changed (lib/whats-new.ts, app/whats-new.tsx) (i18n/it/index.ts).
export const whatsNew: Record<string, string> = {
  "**The day stands out in every chat**: over the first message of each day, groups and Chat with myself too, the day shows in bold between two lines: **Today**, **Yesterday**, the weekday within the last week, and before that the weekday and date. See [Chat through a relay](#relay).":
    "**Il giorno si vede bene in ogni chat**: sopra il primo messaggio di ogni giorno, anche nei gruppi e in Chat con me stesso, il giorno compare in grassetto tra due linee: **Oggi**, **Ieri**, il giorno della settimana nell’ultima settimana, e prima il giorno con la data. Vedi [Chat tramite un relay](#relay).",
  "**The microphone writes, if you like**: tap the microphone beside the message field and choose **Speak to write**, and from then on holding it writes what you say into the field, until you choose **Voice message** again. The choice stays for every chat. See [Chat through a relay](#relay).": "**Il microfono scrive, se vuoi**: tocca il microfono accanto al campo del messaggio e scegli **Parla per scrivere**, e da allora, tenuto premuto, scrive nel campo quello che dici, finché non scegli di nuovo **Messaggio vocale**. La scelta vale per ogni chat. Vedi [Chat tramite un relay](#relay).",
  "**Ways on home**: once a relay is set, the line under the top bar of home is **Ways**, with a dot for each way your messages go out by and how many of them wait; a tap opens **Ways**. See [How Erevos picks the path](#paths).": "**Vie nella schermata principale**: una volta impostato un relay, la riga sotto la barra in alto della schermata principale è **Vie**, con un punto per ogni via da cui partono i tuoi messaggi e quanti di loro aspettano; un tocco apre **Vie**. Vedi [Come Erevos sceglie la via](#paths).",
  "**LoRa makes up for lost pieces, and long texts go shorter**: a text sent by LoRa in several pieces now goes with spare pieces, one for each four, so it comes whole even when a piece or two are lost on the air; older Erevos reads it as before. And long texts are packed, with nothing lost, before they are encrypted, when that makes them go in fewer bytes, to contacts whose Erevos unpacks them. See [Over a LoRa radio](#lora).": "**LoRa rimpiazza i pezzi persi, e i testi lunghi partono più corti**: un testo inviato via LoRa in più pezzi parte ora con pezzi di scorta, uno ogni quattro, così arriva intero anche se uno o due pezzi si perdono nell'aria; un Erevos più vecchio lo legge come prima. E i testi lunghi vengono compressi, senza perdere nulla, prima di essere cifrati, quando così occupano meno byte, verso i contatti il cui Erevos li decomprime. Vedi [Con una radio LoRa](#lora).",
  "**Ways at a glance**: **Settings** → **Relay and networks** → **Ways** shows each way your messages go out by, the relay, Nostr, the phones nearby, LoRa, SMS and Tor, with how each is now and a line under it: full when it works, faint when it reaches no one now, dashed when it is off. Above them, how many of your messages wait to go, an orange dot for each. Only the space that is open shows, never hidden chats. See [How Erevos picks the path](#paths).": "**Le vie a colpo d’occhio**: **Impostazioni** → **Relay e reti** → **Vie** mostra ogni via da cui escono i tuoi messaggi, il relay, Nostr, i telefoni vicini, LoRa, gli SMS e Tor, con com’è ora ognuna e una linea sotto: piena quando funziona, tenue quando ora non raggiunge nessuno, a trattini quando è spenta. Sopra, quanti tuoi messaggi aspettano di partire, un punto arancione per ognuno. Si vede solo lo spazio aperto, mai le chat nascoste. Vedi [Come Erevos sceglie la strada](#paths).",
  "**Answer a hidden contact's call with no PIN**: where hidden chats receive while closed, **Answer** on the ringing screen takes their contact's call at once, on a call screen with no name and no face, and the hidden chats stay closed; the small sign and the PIN still open them. See [Hidden chats](#hidden).": "**Rispondere senza PIN alla chiamata di un contatto nascosto**: dove le chat nascoste ricevono da chiuse, **Rispondi** sulla schermata della chiamata la prende subito, su una schermata senza nome né volto, e le chat nascoste restano chiuse; il piccolo segno e il PIN le aprono ancora. Vedi [Chat nascoste](#hidden).",
  "**See yourself in a video call**: once their picture comes, yours stays in a small window in the top corner, on both phones; before, it vanished, and each side saw only the other. See [Chat through a relay](#relay).": "**Vediti in una videochiamata**: appena arriva l’immagine dell’altro, la tua resta in una piccola finestra nell’angolo in alto, su entrambi i telefoni; prima spariva, e ognuno vedeva solo l’altro. Vedi [Chat tramite un relay](#relay).",
  "**Phones nearby are off until you turn them on**: Erevos no longer looks for phones nearby by itself, with Bluetooth, Wi-Fi Aware or on the same Wi-Fi, as on the same Wi-Fi it held a call back for up to a minute before it rang. Turn on **Look for phones nearby** under **Nearby, with no internet**, on **New chat**, to chat and call with no internet. See [Chat with a nearby phone](#nearby).": "**I telefoni vicini sono spenti finché non li attivi**: Erevos non cerca più da solo i telefoni vicini, via Bluetooth, Wi-Fi Aware o sulla stessa Wi-Fi, perché sulla stessa Wi-Fi tratteneva una chiamata fino a un minuto prima che squillasse. Attiva **Cerca telefoni vicini** in **Vicino, senza internet**, in **Nuova chat**, per chattare e chiamare senza internet. Vedi [Chat con un telefono vicino](#nearby).",
  "**Open a file with another app**: a file in a chat, a PDF say, has **Open** too, not only **Save**: the phone's app for it reads it from Erevos's memory, with no copy left on the phone. Erevos asks first, and never opens web pages, drawings or app packages that way. See [Chat through a relay](#relay).": "**Aprire un file con un’altra app**: un file in una chat, un PDF per esempio, ha anche **Apri**, non solo **Salva**: l’app del telefono lo legge dalla memoria di Erevos, senza che resti una copia sul telefono. Erevos chiede prima, e non apre mai così pagine web, disegni o pacchetti di app. Vedi [Chat tramite un relay](#relay).",
  "**Shared chats say how far they are, on both phones**: chats a contact shared from a relay your Erevos does not take from by itself show **Coming, 40%** once you tap them, and their phone says it is taking them; if they did not come, both phones say so and yours buzzes twice. See [Chat through a relay](#relay).": "**Le chat condivise dicono a che punto sono, su entrambi i telefoni**: le chat che un contatto ha condiviso da un relay da cui il tuo Erevos non prende da solo mostrano **In arrivo, 40%** appena le tocchi, e il suo telefono dice che le stai prendendo; se non sono arrivate, lo dicono entrambi i telefoni e il tuo vibra due volte. Vedi [Chat tramite un relay](#relay).",
  "**Calls connect again**: a call that rang no longer stays at **Connecting** on both phones; each phone now waits for its own addresses before it calls or answers. See [Chat through a relay](#relay).": "**Le chiamate si collegano di nuovo**: una chiamata che ha squillato non resta più su **Connessione** su entrambi i telefoni; ogni telefono ora aspetta i propri indirizzi prima di chiamare o rispondere. Vedi [Chat tramite un relay](#relay).",
  "**A phone beside you brings your messages**: with no internet, an Erevos phone beside yours that has it, and carries for others, takes what waits for you on your relay and hands it over nearby, once you say yes to that phone. It learns your queue there, never what your messages say, and your phone moves to a new queue once it has internet again. Yours does the same for others while **Carry messages for others** is on, as it now is from the start. Never through Tor, and from another relay only once you say yes, warned it sees your address. See [Chat with a nearby phone](#nearby).": "**Un telefono accanto ti porta i messaggi**: senza internet, un telefono con Erevos accanto al tuo che ce l’ha, e trasporta per gli altri, prende ciò che ti aspetta sul tuo relay e te lo dà da vicino, dopo il tuo sì a quel telefono. Sa la tua coda lì, mai cosa dicono i tuoi messaggi, e il tuo telefono passa a una nuova coda appena ha di nuovo internet. Il tuo fa lo stesso per gli altri finché **Trasporta messaggi per altri** è attivo, come ora è fin dall’inizio. Mai tramite Tor, e da un altro relay solo dopo il tuo sì, avvisato che vede il tuo indirizzo. Vedi [Chat with a nearby phone](#nearby).",
  "**A Matrix chat read elsewhere is read here too**: an encrypted Matrix chat you read, or answered, in Element or on another device of yours no longer keeps its count of new messages here. See [Matrix](#matrix).": "**Una chat Matrix letta altrove è letta anche qui**: una chat Matrix cifrata che hai letto, o a cui hai risposto, in Element o su un altro tuo dispositivo non tiene più qui il suo numero di messaggi nuovi. Vedi [Matrix](#matrix).",
  "**Matrix rooms with very long messages open**: a message with a very long run of names, dots or dashes, as some public Matrix rooms have, no longer closes Erevos+ as its chat shows it.":
    "**Le stanze Matrix con messaggi molto lunghi si aprono**: un messaggio con una sequenza molto lunga di nomi, punti o trattini, come ne hanno alcune stanze Matrix pubbliche, non chiude più Erevos+ quando la sua chat lo mostra.",
  "**Messenger chats you read stay read**: a Messenger chat you marked read, or wrote in, no longer comes back as unread when Messenger sends it again, after Erevos+ reconnects or starts.":
    "**Le chat Messenger lette restano lette**: una chat Messenger che hai segnato come letta, o in cui hai scritto, non torna più non letta quando Messenger la invia di nuovo, dopo che Erevos+ si riconnette o si avvia.",
  "**Chats stay where you read**: in Telegram, Matrix, XMPP and Nostr chats, the chat no longer moves by itself to other messages as older ones load above it; it stays at the last message, or where you were reading.":
    "**Le chat restano dove leggi**: nelle chat di Telegram, Matrix, XMPP e Nostr, la chat non si sposta più da sola su altri messaggi mentre quelli più vecchi si caricano sopra; resta sull'ultimo messaggio o dove stavi leggendo.",
  "**Erevos+ says its own name, with an icon of its own**: the app and its guide now say Erevos+ everywhere, and its icon is Erevos's mark on a purple tile. Where it speaks of the plain Erevos, it still says Erevos.":
    "**Erevos+ dice il suo nome, con un'icona tutta sua**: l'app e la sua guida ora dicono Erevos+ ovunque, e la sua icona è il marchio di Erevos su una tessera viola. Dove parla dell'Erevos semplice, dice ancora Erevos.",
  "**Signal: one chat for each person, with their name**: in Erevos+, a Signal chat shows the person's name, what you send from the phone Erevos+ is linked to shows in the chat of the one you sent it to, and someone who first wrote to your phone number keeps one chat with you on their phone too.":
    "**Signal: una chat per ogni persona, con il suo nome**: in Erevos+, una chat Signal mostra il nome della persona, ciò che invii dal telefono a cui Erevos+ è collegato compare nella chat di chi l'ha ricevuto, e chi ti ha scritto per primo al tuo numero tiene anche lui una sola chat con te sul suo telefono.",
  "**A message's menu always opens**: holding a message, in a chat or a group, opens its menu every time; before, after you had been in another app, it could stop opening until Erevos was closed and opened again.": "**Il menu di un messaggio si apre sempre**: tenendo premuto un messaggio, in una chat o in un gruppo, il suo menu si apre ogni volta; prima, dopo essere passati in un'altra app, poteva smettere di aprirsi finché Erevos non veniva chiuso e riaperto.",
  "**New chat, made anew**: your QR code is on New chat as soon as it opens, with **Scan theirs** and **Share** under it; the field at the top finds a contact by name, or adds someone whose link you paste; and **No Erevos yet?** makes an invite, showing again one no one took yet instead of making another. On a new phone with no relay, New chat starts with **Start with an invite**. The small QR code is new each time and good once: the first to scan it is a contact at once, and anyone after, or with the link you share, writes a message request first. See [Chat through a relay](#relay).": "**Nuova chat, rifatta**: il tuo codice QR è su Nuova chat appena si apre, con **Scansiona il suo** e **Condividi** sotto; il campo in alto trova un contatto per nome, o aggiunge qualcuno di cui incolli il link; e **Non ha ancora Erevos?** fa un invito, mostrando di nuovo uno che nessuno ha ancora preso invece di farne un altro. Su un telefono nuovo senza relay, Nuova chat inizia con **Inizia con un invito**. Il codice QR piccolo è nuovo ogni volta e vale una volta: il primo che lo scansiona è subito un contatto, e chi viene dopo, o con il link che condividi, scrive prima una richiesta di messaggio. Vedi [Chat through a relay](#relay).",
  "What's new": 'Novità',
  'What each version changed': 'Cosa è cambiato in ogni versione',
  'What each version of Erevos changed, the newest first.': 'Cosa è cambiato in ogni versione di Erevos, dalla più recente.',
  'Not out yet': 'Non ancora uscita',
  'This version': 'Questa versione',
  'For you': 'Per te',
  'Under the hood': 'Sotto il cofano',
  "**Chats you have read stay read, on every network**: in Erevos+, Messenger, Signal, Session, Telegram, Matrix, XMPP and Nostr chats you have read no longer notify you again of messages already read, after a restart, a reconnect or when a chat opens. Signal's reads go both ways with the phone it is linked to, and a Nostr chat you answer from another app is read here too.": "**Le chat che hai letto restano lette, su ogni rete**: in Erevos+, le chat di Messenger, Signal, Session, Telegram, Matrix, XMPP e Nostr che hai letto non ti avvisano più di messaggi già letti, dopo un riavvio, una riconnessione o quando si apre una chat. Le letture di Signal vanno nei due sensi con il telefono a cui è collegato, e una chat Nostr a cui rispondi da un’altra app risulta letta anche qui.",
  "**The guide tells of Messenger, Signal and Session**: in Erevos+, the user guide has a section for each, on signing in, chats, groups, calls, notifications, Tor and signing out. See [Messenger](#messenger), [Signal](#signal) and [Session](#session).": "**La guida spiega Messenger, Signal e Session**: in Erevos+, la guida ha una sezione per ciascuno, su accesso, chat, gruppi, chiamate, notifiche, Tor e uscita. Vedi [Messenger](#messenger), [Signal](#signal) e [Session](#session).",
  // Not out yet.
  "**New chat asks whether they have Erevos**: over your QR code on **New chat**, choose **Has Erevos already** or **New to Erevos**. The first is your QR code as before, and says that it works only when both phones have a relay; the second shows an invite, which brings in someone new, or someone whose phone has no relay. New chat remembers your choice. See [Chat through a relay](#relay).":
    "**Nuova chat chiede se ha Erevos**: sopra il tuo codice QR in **Nuova chat**, scegli **Ha già Erevos** o **Nuovo su Erevos**. Il primo è il tuo codice QR come prima, e dice che funziona solo se entrambi i telefoni hanno un relay; il secondo mostra un invito, che porta dentro qualcuno di nuovo, o qualcuno il cui telefono non ha un relay. Nuova chat ricorda la tua scelta. Vedi [Chat tramite un relay](#relay).",
  "**The keypad lists the contacts it finds, and shows its letters**: on the Phone's **Keypad**, the contacts what you type finds are listed in the room over the number, all of them, not one at a time; and each key shows its letters in the app's language, ΑΒΓ in Greek, ABC in the others. See [Phone](#phone).":
    "**Il tastierino elenca i contatti che trova, e mostra le sue lettere**: sul **Tastierino** del Telefono, i contatti che trova ciò che digiti compaiono in un elenco nello spazio sopra il numero, tutti insieme e non uno alla volta; e ogni tasto mostra le sue lettere nella lingua dell’app, ΑΒΓ in greco, ABC nelle altre. Vedi [Telefono](#phone).",
  "**A phone beside you no longer slows Erevos**: with another Erevos phone near you on the same Wi-Fi, Erevos no longer links to it over Wi-Fi Aware too, which took your phone's Wi-Fi away for moments and slowed your messages and the relay, as if the other phone were far away; and a link to a phone nearby that stopped carrying anything is let go at once, not used on. See [Chat with a nearby phone](#nearby).":
    "**Un telefono accanto a te non rallenta più Erevos**: con un altro telefono con Erevos vicino a te sulla stessa Wi-Fi, Erevos non si collega più a esso anche tramite Wi-Fi Aware, che toglieva per qualche istante la Wi-Fi al tuo telefono e rallentava i tuoi messaggi e il relay, come se l'altro telefono fosse lontano; e un collegamento con un telefono vicino che ha smesso di portare qualcosa viene lasciato subito, invece di continuare a usarlo. Vedi [Chat con un telefono vicino](#nearby).",
  "**Calls start sooner and sound steadier**: a call through the call relay no longer waits up to 5 seconds on each phone for every way to the relay, only for the first that works; while it goes on, Erevos looks for phones nearby less often, which took the phone's Wi-Fi away for moments and made gaps in the sound; and in a video call, their picture is no longer put aside when their sound came apart from it. See [Chat through a relay](#relay).":
    "**Le chiamate partono prima e si sentono più stabili**: una chiamata tramite il relay delle chiamate non aspetta più fino a 5 secondi su ogni telefono ogni via verso il relay, solo la prima che funziona; mentre dura, Erevos cerca i telefoni vicini meno spesso, cosa che toglieva per un attimo il Wi-Fi al telefono e interrompeva il suono; e in una videochiamata la loro immagine non viene più messa da parte quando il loro suono è arrivato separato. Vedi [Chat through a relay](#relay).",
  "**Contacts as you dial**: on the Phone's **Keypad**, a contact whose number holds the digits you type, or whose name starts with them on the keys' letters (2 for ABC and ΑΒΓ), shows over the keys: tap it to call. See [Phone](#phone).":
    "**Contatti mentre componi**: sul **Tastierino** del Telefono, un contatto il cui numero contiene le cifre digitate, o il cui nome inizia con esse sulle lettere dei tasti (2 per ABC e ΑΒΓ), compare sopra i tasti: toccalo per chiamare. Vedi [Telefono](#phone).",
  "**Chats open at once**: a chat no longer waits, showing your contact as encrypted, for Erevos to finish what it was doing with the relay in the background; it is ready to use as it opens, and holding a message opens its menu, at most a moment later while Erevos says it is still reading what came. See [Chat through a relay](#relay).":
    "**Le chat si aprono subito**: una chat non aspetta più, mostrando il tuo contatto come cifrato, che Erevos finisca ciò che faceva con il relay in background; è pronta appena si apre, e tenere premuto un messaggio apre il suo menu, al massimo un momento dopo, mentre Erevos dice che sta ancora leggendo ciò che è arrivato. Vedi [Chat tramite un relay](#relay).",
  "**Pair with a code with no relay yet**: on a phone with no relay yet, **New chat** now has **Pair with a code** too, under your QR code, and opens straight on **Start with an invite** without first showing the screen of a phone with a relay. See [Chat through a relay](#relay).":
    "**Abbina con un codice senza relay**: su un telefono ancora senza relay, **Nuova chat** ha ora anche **Abbina con un codice**, sotto il tuo codice QR, e si apre subito su **Inizia con un invito** senza mostrare prima la schermata di un telefono con relay. Vedi [Chat through a relay](#relay).",
  "**The Public tab says why it shows no Nostr post**: whether the list of people you follow was not found, or they were found but no relay sent their posts, or their posts came but could not be shown, and how each relay answered. Before, it said only that no public posts were found. See [Chats with other Nostr apps](#nostr-chats).":
    "**La scheda Pubblico dice perché non mostra nessun post Nostr**: se non è stata trovata la lista delle persone che segui, se sono state trovate ma nessun relay ha inviato i loro post, o se i loro post sono arrivati ma non si sono potuti mostrare, e come ha risposto ogni relay. Prima diceva solo che non era stato trovato nessun post pubblico. Vedi [Chat con altre app Nostr](#nostr-chats).",
  "**A new computer links to the end**: a computer with no relay before linking now takes the phone's answer at once, so linking with the small code finishes by itself, and with the full code **They match** shows. Before, the phone waited for **They match** while the computer showed nothing more until Erevos started again. See [Linked devices](#devices).":
    "**Un computer nuovo si collega fino in fondo**: un computer senza relay prima del collegamento prende ora subito la risposta del telefono, così il collegamento con il piccolo codice si completa da solo, e con il codice completo compare **Coincidono**. Prima, il telefono aspettava **Coincidono** mentre il computer non mostrava più nulla finché Erevos non ripartiva. Vedi [Dispositivi collegati](#devices).",
  "**Sharing into Erevos reaches every service**: **Send to** now lists the chats of your Matrix, XMPP and Nostr accounts too, beside Erevos chats, groups and SMS conversations. A photo or file shared from another app no longer goes missing when Erevos locks as it opens: after the password, **Send to** shows it again, where before it said that nothing came to send. See [Chat through a relay](#relay).":
    "**Condividere in Erevos raggiunge ogni servizio**: **Invia a** ora elenca anche le chat dei tuoi account Matrix, XMPP e Nostr, accanto alle chat di Erevos, ai gruppi e alle conversazioni SMS. Una foto o un file condiviso da un’altra app non va più perso quando Erevos si blocca mentre si apre: dopo la password, **Invia a** lo mostra di nuovo, dove prima diceva che non era arrivato nulla da inviare. Vedi [Chat tramite un relay](#relay).",
  "**Search, media, days and export in Matrix, XMPP, Nostr and SMS**: these chats now have **Search in this chat**, **Media, links and files**, **Go to a day** and **Export chat**, as Erevos chats do, over what your phone keeps of them; an SMS conversation has them under **⋮**. Nothing you search for leaves your phone. See [Getting started](#start).":
    "**Ricerca, media, giorni ed esportazione su Matrix, XMPP, Nostr e SMS**: queste chat ora hanno **Cerca in questa chat**, **Media, link e file**, **Vai a un giorno** ed **Esporta chat**, come le chat di Erevos, su ciò che il tuo telefono ne conserva; una conversazione SMS li ha in **⋮**. Niente di ciò che cerchi lascia il tuo telefono. Vedi [Per iniziare](#start).",
  "**Styles, cards and video in Matrix, XMPP and Nostr**: these chats now show bold, italic and the other marks for how words look, with tappable links, and send a contact card, a video without where it was filmed, or a photo from the camera at the quality you choose. In groups, @ offers the members; Nostr chats send your location, and a message you forward is marked as forwarded on your phone. See [Matrix](#matrix).":
    "**Stili, schede e video su Matrix, XMPP e Nostr**: queste chat ora mostrano grassetto, corsivo e gli altri segni per l’aspetto delle parole, con link da toccare, e inviano una scheda contatto, un video senza il luogo dove è stato girato o una foto dalla fotocamera con la qualità che scegli. Nei gruppi, @ propone i membri; le chat Nostr inviano la tua posizione, e un messaggio che inoltri è segnato come inoltrato sul tuo telefono. Vedi [Matrix](#matrix).",
  "**Starred messages in every chat**: star a message in Matrix, XMPP, Nostr and SMS too, and find it again under **Starred messages**; save a photo, video, voice message or file that came there to the Collection, and keep a sticker or photo that came as one of your stickers. See [Chat through a relay](#relay).":
    "**Messaggi importanti in ogni chat**: segna un messaggio come importante anche su Matrix, XMPP, Nostr e SMS, e ritrovalo in **Messaggi importanti**; salva nella Raccolta una foto, un video, un messaggio vocale o un file arrivato lì, e tieni uno sticker o una foto arrivati come uno dei tuoi sticker. Vedi [Chat tramite un relay](#relay).",
  "**Pin and archive any chat**: hold any chat down on the home screen (an Erevos contact or group, Matrix, XMPP or Nostr) to **Pin to the top**, **Archive** or, on Android, mute it, as SMS conversations already could. Archived chats wait under **Archived** until a new message comes from them. Matrix favourites show pinned, and low-priority rooms come last. A Matrix row shows ✓✓✓ once everyone has read yours. Matrix rooms, XMPP contacts and group MMS can take a name of your own. See [Getting started](#start).":
    "**Fissa e archivia qualsiasi chat**: tieni premuta una chat qualsiasi nella schermata principale (un contatto o gruppo Erevos, Matrix, XMPP o Nostr) per **Fissa in alto**, **Archivia** o, su Android, silenziarla, come già potevano le conversazioni SMS. Le chat archiviate aspettano in **Archiviate** finché non ne arriva un nuovo messaggio. I preferiti di Matrix appaiono fissati, e le stanze a bassa priorità vengono per ultime. Una riga Matrix mostra ✓✓✓ appena tutti hanno letto il tuo. Stanze Matrix, contatti XMPP e MMS di gruppo possono avere un nome tuo. Vedi [Per iniziare](#start).",
  "**Drafts, Send later and Remind me on Matrix, XMPP and Nostr**: what you type in a chat and do not send stays as its draft, also after Erevos closes, and shows on the chat's row. Hold **Send** down to send a message later from this phone. A Matrix or XMPP message that did not go has **Send again** in its menu, and **Remind me** on a message of any of these chats, SMS too, puts it in Chat with myself with a reminder. See [Matrix](#matrix).":
    "**Bozze, Invia più tardi e Ricordamelo su Matrix, XMPP e Nostr**: ciò che scrivi in una chat e non invii resta come sua bozza, anche dopo che Erevos si chiude, e si vede nella riga della chat. Tieni premuto **Invia** per inviare un messaggio più tardi da questo telefono. Un messaggio Matrix o XMPP che non è partito ha **Invia di nuovo** nel suo menu, e **Ricordamelo** su un messaggio di queste chat, e degli SMS, lo mette in Chat con me stesso con un promemoria. Vedi [Matrix](#matrix).",
  "**A PIN and screenshots for Matrix, XMPP, Nostr and SMS chats**: lock a chat on Matrix, XMPP or Nostr, or an SMS conversation, with a PIN of its own and block its screenshots, as an Erevos chat; an SMS conversation can also have its own look, be muted, or have a sound of its own. See [Hidden chats](#hidden).":
    "**Un PIN e gli screenshot per le chat Matrix, XMPP, Nostr e SMS**: blocca una chat su Matrix, XMPP o Nostr, o una conversazione SMS, con un PIN suo e blocca i suoi screenshot, come una chat Erevos; una conversazione SMS può anche avere il suo aspetto, essere silenziata o avere un suono suo. Vedi [Chat nascoste](#hidden).",
  "**Chat rules on Matrix, XMPP, Nostr and SMS**: disappearing messages, a timer for the chat or **Disappear** for one message, each chat saying what the other side keeps; **Block** on Matrix and Nostr, with a list of whom you blocked on each service's screen; **Delete** asks **This phone** or **Everyone**; on XMPP, **Appear offline** to one contact; and **Check in person** by QR code on XMPP and Nostr. See [Matrix](#matrix).":
    "**Regole della chat su Matrix, XMPP, Nostr e SMS**: messaggi effimeri, con un tempo per la chat o **Effimero** per un messaggio, e ogni chat dice cosa tiene l’altra parte; **Blocca** su Matrix e Nostr, con l’elenco di chi hai bloccato nella schermata di ogni servizio; **Elimina** chiede **Questo telefono** o **Per tutti**; su XMPP, **Mostrati offline** a un contatto; e **Verifica di persona** con codice QR su XMPP e Nostr. Vedi [Matrix](#matrix).",
  "**Choose where a call's sound goes**: with a Bluetooth or wired headset connected, **Speaker** in a call becomes **Audio output**, to choose the phone, the speaker or the headset, a Bluetooth one by its own name. A headset connected as a call starts, or during it, takes the sound, as in a phone call. On Android. See [Chat through a relay](#relay).":
    "**Scegli dove va il suono di una chiamata**: con cuffie Bluetooth o con filo collegate, **Altoparlante** in una chiamata diventa **Uscita audio**, per scegliere il telefono, l’altoparlante o le cuffie, quelle Bluetooth con il loro nome. Delle cuffie collegate all’inizio di una chiamata, o durante, prendono il suono, come in una telefonata. Su Android. Vedi [Chat tramite un relay](#relay).",
  "**Nothing goes through Tor unless you turn it on**: on Android, **Automatically from your relay** under **Home relay** is now off in a new space, so a space no longer takes its relay's paired relay as a home relay through Tor by itself; turn it on there if you want it. Turning it off now also lets go of the home relay it took, so Tor does not run for it. See [Home relay](#home-relay).":
    "**Niente passa da Tor se non lo accendi tu**: su Android, **Automaticamente dal tuo relay** in **Relay di casa** ora è spento in un nuovo spazio, quindi uno spazio non prende più da solo il relay abbinato al suo relay come relay di casa tramite Tor; accendilo lì se lo vuoi. Spegnerlo ora lascia anche il relay di casa che ha preso, così Tor non gira per lui. Vedi [Relay di casa](#home-relay).",
  "**Your relays first, Nostr only after them**: a text to a contact who reads on Nostr now goes through your relay, then their home relays, then your home relay, and through the public Nostr relays only when none of them took it. Before, it went to the Nostr relays first and through your relay only when they were slow or did not take it. See [Through Nostr](#nostr).":
    "**Prima i tuoi relay, Nostr solo dopo**: un testo a un contatto che legge su Nostr ora passa dal tuo relay, poi dai relay di casa del contatto, poi dal tuo relay di casa, e dai relay Nostr pubblici solo quando nessuno l’ha preso. In precedenza andava per primo ai relay Nostr e dal tuo relay solo quando erano lenti o non lo prendevano. Vedi [Tramite Nostr](#nostr).",
  "**One chat only through Tor**: on Android, **Through Tor** in an Erevos chat's **Details** sends that chat's messages and files only through Tor, on circuits of its own, whatever the space's Tor setting. It is off unless you turn it on, and calls do not go through Tor. See [Through Tor](#tor).":
    "**Una sola chat tramite Tor**: su Android, **Tramite Tor** nei **Dettagli** di una chat di Erevos invia i messaggi e i file di quella chat solo tramite Tor, su circuiti propri, qualunque cosa dica l’impostazione Tor dello spazio. È disattivato finché non lo attivi, e le chiamate non passano tramite Tor. Vedi [Tramite Tor](#tor).",
  "**One chat only through Tor reaches Nostr too**: a chat with **Through Tor** on in its **Details** now sends and reads its Nostr texts only through Tor, and its photos and files on Nostr file servers too, even when the space's Tor is **Nothing**; Tor is started for it, and what goes waits for it. Until your contact first writes to the chat's own queue, their first messages come to the space's own queue, which is read the space's way. Before, with the space's Tor off, such a chat's texts could reach the public Nostr relays straight, and they saw the phone's internet address. See [Through Tor](#tor).":
    "**Una sola chat tramite Tor raggiunge anche Nostr**: una chat con **Tramite Tor** attivo nei suoi **Dettagli** ora invia e legge i suoi testi Nostr solo tramite Tor, e anche le sue foto e i suoi file sui server di file Nostr, anche quando il Tor dello spazio è **Niente**; Tor viene avviato per lei, e quello che parte lo aspetta. Finché il tuo contatto non scrive per la prima volta nella coda propria della chat, i suoi primi messaggi arrivano nella coda dello spazio, che si legge come dice lo spazio. Prima, con il Tor dello spazio disattivato, i testi di una chat così potevano arrivare direttamente ai relay Nostr pubblici, che vedevano l’indirizzo internet del telefono. Vedi [Tramite Tor](#tor).",
  "**Through Tor on your linked devices too**: a chat's **Through Tor** switch, set in its **Details**, now reaches your linked devices (your computer, the web app and Jolla) and back: switched on or off on any of them, it is switched everywhere. On a linked device that chat's messages, files and send-later messages then go only through Tor too, on the chat's own circuits, never straight; so do the copies that go to your contact's other devices. The web app has no Tor: there a chat with the switch on sends nothing while it is on, and the switch is shown so it can be turned off. A device on an older version never turns it off anywhere; it learns a change made elsewhere at that contact's next change. Before, it was only on the phone where you set it. See [Through Tor](#tor).":
    "**Tramite Tor anche sui tuoi dispositivi collegati**: l’interruttore **Tramite Tor** di una chat, impostato nei suoi **Dettagli**, ora arriva ai tuoi dispositivi collegati (il tuo computer, l’app web e Jolla) e torna indietro: attivato o disattivato su uno, lo è ovunque. Su un dispositivo collegato, i messaggi, i file e i messaggi da inviare più tardi di quella chat passano allora anch’essi solo tramite Tor, sui circuiti propri della chat, mai in diretta; così anche le copie che vanno agli altri dispositivi del tuo contatto. L’app web non ha Tor: lì una chat con l’interruttore attivo non invia nulla finché è attivo, e l’interruttore viene mostrato per poterlo disattivare. Un dispositivo con una versione più vecchia non lo disattiva mai da nessuna parte; viene a sapere di una modifica fatta altrove alla successiva modifica di quel contatto. Prima valeva solo sul telefono dove lo impostavi. Vedi [Tramite Tor](#tor).",
  "**Nostr has its own Tor switch**: the **Nostr** screen now has **Nostr through Tor**, **On** or **Off**, off unless you turn it on. **On**, Erevos reaches the Nostr relays and the Nostr file servers only through Tor, and starts Tor for it even when the space's Tor is **Nothing**; a text that goes there waits while Tor starts. It only adds Tor: with the space's Tor on, or for a chat set to **Through Tor**, Nostr goes through Tor whatever it says. Before, Nostr only followed the space's Tor setting, and the screen only said whether it was on. See [Through Nostr](#nostr).":
    "**Nostr ha un suo interruttore Tor**: la schermata **Nostr** ora ha **Nostr tramite Tor**, **Attivato** o **Disattivato**, disattivato a meno che tu non lo attivi. **Attivato**, Erevos raggiunge i relay Nostr e i server di file Nostr solo tramite Tor e avvia Tor per questo, anche quando il Tor dello spazio è **Niente**; un testo che va lì aspetta mentre Tor si avvia. Aggiunge solo Tor: con il Tor dello spazio attivato, o per una chat impostata su **Tramite Tor**, Nostr passa da Tor qualunque cosa dica. Prima, Nostr seguiva solo l’impostazione Tor dello spazio, e la schermata diceva solo se era attivo. Vedi [Tramite Nostr](#nostr).",
  "**Erevos warns before your internet address can be seen**: once before the first message, voice message or file in an Erevos chat that can go without Tor, with **Through Tor for this chat** to fix it or **Go on**; before the first message in an Erevos group that can go without Tor; before a call, as calls never go through Tor, unless the contact is nearby on the same network; before fetching a file from a server your contact chose; and in every **Open this link?** question, where the site sees the address. Each has a **Guide** button. Before, Erevos did not say it. See [Who sees your internet address](#ip).":
    "**Erevos avvisa prima che il tuo indirizzo internet possa essere visto**: una volta prima del primo messaggio, messaggio vocale o file in una chat Erevos che può andare senza Tor, con **Tramite Tor per questa chat** per risolvere o **Vai avanti**; prima del primo messaggio in un gruppo Erevos che può andare senza Tor; prima di una chiamata, perché le chiamate non passano mai da Tor, a meno che il contatto sia vicino sulla stessa rete; prima di scaricare un file da un server scelto dal tuo contatto; e in ogni domanda **Aprire questo link?**, dove il sito vede l’indirizzo. Ognuno ha un pulsante **Guida**. Prima, Erevos non lo diceva. Vedi [Chi vede il tuo indirizzo internet](#ip).",
  "**A Tor switch of their own**: backups to a server, the Collection's server copy, radio and TV lists, link previews and updates each have a **Through Tor** switch in their own screen, off unless you turn it on. On, that goes only through Tor, whatever the space's Tor setting, and waits while Tor starts; nothing goes straight. Off, it goes as before. It only adds Tor. For updates, the switch makes the daily new-version notice and **Check for updates** ask the web app's server instead of GitHub; a new version is told, but it does not download through Tor: to install it, turn the switch off for a moment. Playing a radio station or a TV channel always goes straight. Before, backups, the Collection and radio and TV followed only the space's Tor setting, and link previews and updates never went through Tor. See [Who sees your internet address](#ip).":
    "**Un interruttore Tor per ciascuno**: i backup su un server, la copia della Raccolta su un server, le liste radio e TV, le anteprime dei link e gli aggiornamenti hanno ognuno un interruttore **Tramite Tor** nella propria schermata, disattivato finché non lo attivi. Attivo, passa solo tramite Tor, qualunque sia l’impostazione Tor dello spazio, e aspetta mentre Tor si avvia; nulla va in modo diretto. Disattivo, va come prima. Aggiunge solo Tor. Per gli aggiornamenti, l’interruttore fa chiedere al server dell’app web, e non a GitHub, la notifica giornaliera di una nuova versione e **Cerca aggiornamenti**; una nuova versione viene segnalata, ma non si scarica tramite Tor: per installarla, disattivalo per un momento. Riprodurre una stazione radio o un canale TV va sempre in modo diretto. Prima, i backup, la Raccolta e radio e TV seguivano solo l’impostazione Tor dello spazio, e le anteprime dei link e gli aggiornamenti non passavano mai da Tor. Vedi [Chi vede il tuo indirizzo internet](#ip).",
  "**Bare web addresses open too**: t.me/name, example.org/page and the like are now tappable in every chat, as in Telegram and Signal, and show whole before they open; e-mail addresses and file names are not. See [Chat through a relay](#relay).":
    "**Si aprono anche gli indirizzi web nudi**: t.me/name, example.org/page e simili ora si possono toccare in ogni chat, come in Telegram e Signal, e si mostrano interi prima di aprirsi; gli indirizzi e-mail e i nomi di file no. Vedi [Chat tramite un relay](#relay).",
  "**Read marks no longer go missing**: when you read a message and put the phone away at once, the other person still learns that you read it, at Erevos's next look, also after Erevos was closed. Before, it could stay at ✓✓ for them for good.": "**Le conferme di lettura non si perdono più**: quando leggi un messaggio e metti subito via il telefono, l’altra persona sa comunque che l’hai letto, al prossimo controllo di Erevos, anche dopo che Erevos è stato chiuso. Prima poteva restare a ✓✓ per lei per sempre.",
  "**Backups are checked**: after each automatic backup Erevos reads it back from the folder, opens it with its password, makes sure every part it names is there, of its size, and reads two of them through. On a server it looks at the listing only. **Check now** under Backups also downloads the server’s newest backup and ten of its parts; a part missing or damaged shows in red. **Full check of the folder** compares every part there with its SHA-256, on the phone. See [Backups](#backup).":
    "**I backup vengono controllati**: dopo ogni backup automatico Erevos lo rilegge dalla cartella, lo apre con la sua password, si assicura che ogni parte che nomina ci sia, della sua dimensione, e ne legge due per intero. Su un server guarda solo l’elenco. **Controlla ora**, in Backup, scarica anche il backup più recente del server e dieci sue parti; una parte mancante o danneggiata appare in rosso. **Controllo completo della cartella** confronta ogni parte lì con il suo SHA-256, sul telefono. Vedi [Backup](#backup).",
  "**A new first start**: the first screen now says what you do not give, no phone number, email, user name or account, and asks for a name for your contacts, if you want one. After the modules comes a short screen for each, with how to begin with it and what Android should allow for it, **Allow all, one by one** among it; then the password lock and backups, then what is ready and what is missing. **I already have Erevos on another phone** goes straight to restoring a backup. See [Modules](#modules).":
    "**Un nuovo primo avvio**: la prima schermata dice ora ciò che non dai, né numero di telefono, né e-mail, né nome utente, né account, e chiede un nome per i tuoi contatti, se lo vuoi. Dopo i moduli arriva una breve schermata per ciascuno, con come iniziare e ciò che Android deve consentire per esso, tra cui **Consenti tutto, uno per uno**; poi il blocco con password e i backup, poi ciò che è pronto e ciò che manca. **Ho già Erevos su un altro telefono** va dritto al ripristino di un backup. Vedi [Moduli](#modules).",
  "**Leftovers**: photos and files that nothing names any more, as those of an import that stopped in its middle, can now be found and deleted, under Backups → **Leftovers**. Type the PIN of each of your hidden chats and the password of any other space, tap **Find leftovers**, and Erevos shows how much none of them names; **Delete them** deletes it once you say so. See [Backups](#backup).":
    "**Avanzi**: foto e file che più nulla nomina, come quelli di un'importazione interrotta a metà, ora si possono trovare ed eliminare, in Backup → **Avanzi**. Scrivi il PIN di ciascuna delle tue chat nascoste e la password di ogni altro spazio, tocca **Cerca avanzi**, ed Erevos mostra quanto nessuno di essi nomina; **Eliminali** lo elimina appena confermi. Vedi [Backup](#backup).",
  "**An import that stops leaves nothing behind**: when Erevos stops while it brings in the photos and files of a Telegram, WhatsApp or Viber export, as when Android closes it or the battery runs out, what it had written of them is deleted the next time it starts. Before, it stayed on the phone, and in every backup, for good. See [Imported chats](#import).":
    "**Un'importazione interrotta non lascia nulla**: quando Erevos si ferma mentre porta dentro le foto e i file di un'esportazione di Telegram, WhatsApp o Viber, come quando Android lo chiude o la batteria si scarica, ciò che aveva già scritto viene cancellato al prossimo avvio. Prima restava sul telefono, e in ogni backup, per sempre. Vedi [Chat importate](#import).",
  // 7.0.0-rc.7
  "**What takes room**: Backups now have **What takes room**, which shows on Android how much room Erevos takes on the phone, by kind: the Collection with the chats' photos and files, voice messages, chat history, Tor, and what writes that did not end left over. Each automatic backup holds it all, so it tells why one is large. See [Backups](#backup).":
    "**Cosa occupa spazio**: i backup hanno ora **Cosa occupa spazio**, che mostra su Android quanto spazio occupa Erevos sul telefono, per tipo: la Raccolta con le foto e i file delle chat, i messaggi vocali, la cronologia, Tor e i resti di scritture non concluse. Ogni backup automatico contiene tutto questo, così si vede perché è grande. Vedi [Backup](#backup).",
  "**Backups to a server get there again**: a backup to your own server, such as a Nextcloud, no longer stops when the server misses one of its pieces for a moment, as when it closes for a few minutes at night. That piece goes again a little later and the backup carries on; before, it started over the next time, and a large backup could fail day after day. See [Backups](#backup).":
    '**I backup su un server arrivano di nuovo**: un backup sul tuo server, come un Nextcloud, non si ferma più quando il server non accetta per un momento uno dei suoi pezzi, come quando chiude per qualche minuto di notte. Quel pezzo riparte poco dopo e il backup continua; prima ricominciava la volta dopo, e un backup grande poteva fallire giorno dopo giorno. Vedi [Backup](#backup).',
  // 7.0.0-rc.6
  "**Photos and files from the Collection, straight from a chat**: **+** in a chat now has **Collection**, which opens the Collection of that chat's place, its photos and its other files. Tap what to send, then **Send**, and it goes in the chat. Before, **Photo** opened only the phone's own gallery. See [Collection](#collection).":
    "**Foto e file dalla Raccolta, direttamente da una chat**: **+** in una chat ora ha **Raccolta**, che apre la Raccolta del luogo di quella chat, con le sue foto e gli altri file. Tocca ciò che vuoi inviare, poi **Invia**, e va nella chat. Prima, **Foto** apriva solo la galleria del telefono. Vedi [Raccolta](#collection).",
  "**A chat opens at its last message again**: opened from the home screen or a notification, a chat could stop above its newest messages, often above the unread ones. Now it goes to its end at once, and once more as its messages come into view.":
    "**Una chat si apre di nuovo sul suo ultimo messaggio**: aperta dalla schermata iniziale o da una notifica, una chat poteva fermarsi sopra i suoi messaggi più recenti, spesso sopra quelli non letti. Ora va subito alla fine, e ancora una volta appena i suoi messaggi si vedono.",
  "**A new sign-in to a relay is no longer undone**: after you signed in to your relay again, a chat screen open from before could later write back the token from before, which the relay no longer lets in, and the relay then refused this phone. Now the new token is kept at once, and every chat screen open takes it. See [Chat through a relay](#relay).":
    "**Un nuovo accesso al relay non viene più annullato**: dopo un nuovo accesso al tuo relay, una schermata di chat aperta da prima poteva in seguito riscrivere il token precedente, che il relay non accetta più, e allora il relay rifiutava questo telefono. Ora il nuovo token viene salvato subito, e ogni schermata di chat aperta lo prende. Vedi [Chat tramite un relay](#relay).",
  // 7.0.0-rc.5
  "**A message sent offline is no longer lost when you leave the chat**: what you sent while your chats were still opening, as they do for a while with no connection, was lost if you left the chat before it went. Now it waits, marked **Waiting**, and goes by itself once the relay or their phone nearby can take it, a voice message too. See [Chat through a relay](#relay).":
    "**Un messaggio inviato senza connessione non va più perso quando esci dalla chat**: quello che inviavi mentre le chat si stavano ancora aprendo, come fanno per un po' senza connessione, andava perso se uscivi dalla chat prima che partisse. Ora aspetta, segnato **In attesa**, e parte da solo appena il relay o il suo telefono vicino può prenderlo, anche un messaggio vocale. Vedi [Chat tramite un relay](#relay).",
  // 7.0.0-rc.4
  "**No more freezing after a space opens**: while an automatic backup was made, the screen could stop answering for minutes. Now the backup's files are written, listed and deleted in their folder away from the screen, and its parts are checked natively, many times faster.":
    '**Niente più blocchi quando si apre uno spazio**: mentre veniva fatto un backup automatico, lo schermo poteva smettere di rispondere per minuti. Ora i file del backup vengono scritti, elencati ed eliminati nella loro cartella, lontano dallo schermo, e le sue parti sono controllate in modo nativo, molte volte più velocemente.',
  // 7.0.0-rc.3
  "**Your SMS on your computer**: the phone's SMS can now show on this space's linked devices too, a computer, a browser or a tablet, end-to-end encrypted: read them there and answer, and the phone sends the answer. The latest 50 conversations go, each with its latest 50 messages; photos stay on the phone. Off until you turn it on, on the phone, under Settings → Phone and SMS → SMS → **On my linked devices too**. See [SMS](#sms).":
    "**I tuoi SMS sul computer**: gli SMS del telefono ora possono apparire anche sui dispositivi collegati di questo spazio, un computer, un browser o un tablet, con crittografia end-to-end: lì li leggi e rispondi, e il telefono invia la risposta. Vanno le ultime 50 conversazioni, ciascuna con i suoi ultimi 50 messaggi; le foto restano sul telefono. Disattivato finché non lo attivi, sul telefono, in Impostazioni → Telefono e SMS → SMS → **Anche sui miei dispositivi collegati**. Vedi [SMS](#sms).",
  "**TV in the Collection**: the Collection's new **TV** tab plays TV channels from IPTV lists (.m3u), by their link or from a file, or from iptv-org's public list of free channels, by country or whole, in their groups, with a search, on Android, on a computer and in a browser. There is no programme guide, logos show only if you turn them on, and a channel's name and link, or a radio station's, can be sent to a chat. See [Collection](#collection).":
    "**TV nella Raccolta**: la nuova scheda **TV** della Raccolta riproduce canali TV da liste IPTV (.m3u), dal loro link o da un file, o dalla lista pubblica di canali gratuiti di iptv-org, per paese o intera, nei loro gruppi, con una ricerca, su Android, sul computer e in un browser. Non c’è una guida ai programmi, i loghi appaiono solo se li attivi, e il nome e il link di un canale, o di una stazione radio, si possono inviare a una chat. Vedi [Raccolta](#collection).",
  "**Radio that keeps playing**: when a station's server, or a proxy on the way, drops the stream, or the network goes for a moment, Erevos asks the station again by itself, a few seconds later, instead of stopping.":
    "**Radio che continua a suonare**: quando il server di una stazione, o un proxy lungo la strada, interrompe il flusso, o la rete se ne va per un momento, Erevos si ricollega da solo pochi secondi dopo, invece di fermarsi.",
  "**Radio playlists with many stations**: in the Collection's Radio, **Add a station** takes a playlist link (.m3u, .pls) that names many stations and adds each of them, and **Import a playlist file** adds the stations of a .m3u or .pls file from your device. Only stations with an https link are added, and Erevos says how many were left out.":
    "**Playlist radio con molte stazioni**: nella Radio della Raccolta, **Aggiungi una stazione** accetta un link di playlist (.m3u, .pls) con molte stazioni e le aggiunge tutte, e **Importa un file di playlist** aggiunge le stazioni di un file .m3u o .pls dal tuo dispositivo. Vengono aggiunte solo stazioni con link https, ed Erevos dice quante ne sono rimaste fuori.",
  "**Block screenshots in a chat**: in a chat's details, **Block screenshots** keeps screenshots and screen recordings of it out on both phones, on Android, and either of you can turn it off again. Erevos on an iPhone, on a computer, in a browser or on Sailfish cannot block them, and says so. See [Chat through a relay](#relay).":
    "**Bloccare gli screenshot in una chat**: nei dettagli di una chat, **Blocca gli screenshot** impedisce screenshot e registrazioni dello schermo della chat su entrambi i telefoni, su Android, e ognuno dei due può disattivarlo di nuovo. Erevos su un iPhone, su un computer, in un browser o su Sailfish non può bloccarli, e lo dice. Vedi [Chat tramite un relay](#relay).",
  "**Every chat in its own look**: groups, Chat with myself and chats on Matrix, XMPP and Nostr now have **Chat look** too, as a contact's chat had, for that chat only. See [Chat through a relay](#relay).":
    "**Ogni chat con il suo aspetto**: i gruppi, Chat con me stesso e le chat su Matrix, XMPP e Nostr hanno ora anche **Aspetto della chat**, come l’aveva la chat di un contatto, solo per quella chat. Vedi [Chat tramite un relay](#relay).",
  "**Letters and text size**: Settings → Appearance has **Letters** (the style's own, the phone's, serif or monospace) and the messages' **Text size**, for the whole app or, from **Chat look**, for one chat. See [Appearance](#appearance).":
    "**Carattere e dimensione del testo**: Impostazioni → Aspetto ha **Carattere** (quello dello stile, quello del telefono, con grazie o a spaziatura fissa) e la **Dimensione del testo** dei messaggi, per tutta l’app o, da **Aspetto della chat**, per una chat. Vedi [Aspetto](#appearance).",
  "**Muting hidden Matrix, XMPP and Nostr chats**: a hidden place's own Matrix, XMPP and Nostr chats can now be muted, as hidden chats are, and then say nothing at all. See [Hidden chats](#hidden).":
    "**Silenziare le chat nascoste di Matrix, XMPP e Nostr**: le chat degli account Matrix, XMPP e Nostr di un luogo nascosto ora si possono silenziare, come le chat nascoste, e allora non dicono nulla. Vedi [Chat nascoste](#hidden).",
  "**Say when I open Erevos**: with **Last seen** on, opening Erevos now tells your contacts at once, without waiting for a message: only those you talked with in the last 30 days who show their own time too, each after a random wait of up to a minute, at most every 15 minutes. The relay can then tell when you open Erevos: turn it off under Settings → Privacy and security → Last seen, or in a chat's details. See [Chat through a relay](#relay).":
    "**Dire quando apro Erevos**: con **Ultimo accesso** attivo, aprire Erevos ora lo dice subito ai tuoi contatti, senza aspettare un messaggio: solo quelli con cui hai parlato negli ultimi 30 giorni che mostrano anche la propria ora, ciascuno dopo un’attesa casuale fino a un minuto, al massimo ogni 15 minuti. Il relay può allora capire quando apri Erevos: spegnilo in Impostazioni → Privacy e sicurezza → Ultimo accesso, o nei dettagli di una chat. Vedi [Chat tramite un relay](#relay).",
  "**Moving to a new phone**: a new chapter of the guide takes you step by step from the old phone to the new one with one backup: what to get ready, what comes over, what to set again, and wiping the old one at the end. See [Moving to a new phone](#new-phone).":
    "**Passare a un nuovo telefono**: un nuovo capitolo della guida ti accompagna passo dopo passo dal telefono vecchio a quello nuovo con un solo backup: cosa preparare, cosa passa, cosa reimpostare, e la cancellazione del vecchio alla fine. Vedi [Passare a un nuovo telefono](#new-phone).",
  '**A lost phone**: if the phone a backup came from was lost or stolen and may still be on, **The old phone was lost** under Settings → Data and devices → Backups moves every space and its hidden chats to new relay queues, so that phone reads nothing more of yours there, and tells your contacts quietly. The contact links and QR codes you gave before work for 14 more days. See [Backups](#backup).':
    '**Un telefono perso**: se il telefono da cui viene un backup è stato perso o rubato e può essere ancora acceso, **Il vecchio telefono è perso**, sotto Impostazioni → Dati e dispositivi → Backup, sposta ogni spazio e le sue chat nascoste su nuove code sul relay, così quel telefono non legge più niente di tuo lì, e avvisa in silenzio i tuoi contatti. I link di contatto e i codici QR che hai dato prima valgono ancora 14 giorni. Vedi [Backup](#backup).',
  '**Restored chats go on by themselves**: after a backup is restored, a chat that went on after the backup was made starts a new conversation with the contact by itself, so you no longer give each other your links again, but with a contact on an older Erevos. See [Backups](#backup).':
    '**Le chat ripristinate proseguono da sole**: dopo il ripristino di un backup, una chat proseguita dopo il backup avvia da sola una nuova conversazione con il contatto, così non dovete più scambiarvi di nuovo i link, tranne con un contatto con un Erevos più vecchio. Vedi [Backup](#backup).',
  '**Backups every 6 hours, and lighter**: automatic backups can now come every 6 hours too, made while Erevos is open and as it goes to the background. Each one writes and sends only the photos, files and voice messages that are new, and names again those of the backups before it: keep the whole backup folder together. See [Backups](#backup).':
    '**Backup ogni 6 ore, e più leggeri**: i backup automatici ora possono farsi anche ogni 6 ore, mentre Erevos è aperto e quando passa in secondo piano. Ognuno scrive e invia solo le foto, i file e i messaggi vocali che sono nuovi, e nomina di nuovo quelli dei backup prima: tieni insieme tutta la cartella dei backup. Vedi [Backup](#backup).',
  '**Linked devices after a restore**: the phone a backup was restored on can ask the computers and browsers the old phone had linked to link again: tap **Ask to link again** under Settings → Data and devices → Linked devices, then **Link again** on the device. It keeps its chats, with no code to scan. See [Backups](#backup).':
    '**Dispositivi collegati dopo un ripristino**: il telefono su cui è stato ripristinato un backup può chiedere ai computer e ai browser che il vecchio telefono aveva collegato di collegarsi di nuovo: tocca **Chiedi di collegarsi di nuovo** in Impostazioni → Dati e dispositivi → Dispositivi collegati, poi **Collega di nuovo** sul dispositivo. Tiene le sue chat, senza codice da scansionare. Vedi [Backup](#backup).',
  "**The phone's calls in backups**: on Android, **Put the calls in backups** under Backups adds the call history and Android's blocked numbers to your backups, and restoring adds back those the phone lacks. Off until you turn it on. See [Backups](#backup).":
    '**Le chiamate del telefono nei backup**: su Android, **Includi le chiamate nei backup**, sotto Backup, aggiunge ai tuoi backup la cronologia delle chiamate e i numeri bloccati di Android, e il ripristino rimette quelli che mancano al telefono. Disattivato finché non lo attivi. Vedi [Backup](#backup).',
  "**Groups after a restore**: a member restored from a backup asks the group's admin to put it in again, which works while the group moved on only a little.":
    '**Gruppi dopo un ripristino**: un membro ripristinato da un backup chiede all’amministratore del gruppo di rimetterlo dentro, cosa che funziona finché il gruppo è andato avanti solo di poco.',
  "**The time of a message that waited**: a message that waited on the relay, as for a computer or for hidden chats that were closed, now shows when it was sent, not when it came. From an Erevos before this version it still shows when it came.":
    "**L’ora di un messaggio che ha atteso**: un messaggio che ha atteso sul relay, come per un computer o per chat nascoste chiuse, ora mostra quando è stato inviato, non quando è arrivato. Da un Erevos precedente a questa versione mostra ancora quando è arrivato.",
  // 7.0.0-rc.2
  "**Find radio stations by name**: Add a station in the Collection's Radio tab searches Radio Browser, a free directory, sent only the words you type when you press Search. See [Collection](#collection).":
    "**Trova le stazioni per nome**: Aggiungi una stazione nella scheda Radio della Raccolta cerca in Radio Browser, un elenco libero, a cui vengono inviate solo le parole che scrivi quando premi Cerca. Vedi [Raccolta](#collection).",
  "**Internet radio in the Collection**: a Radio tab with stations you add by their https link, kept encrypted with the Collection, played like the music, with the notice on the phone. The station sees your device's IP address. See [Collection](#collection).":
    "**Radio via internet nella Raccolta**: una scheda Radio con le stazioni che aggiungi dal loro link https, cifrate con la Raccolta, che suonano come la musica, con la notifica sul telefono. La stazione vede l’indirizzo IP del tuo dispositivo. Vedi [Raccolta](#collection).",
  "**Music and videos of any size in the desktop app's Collection**: they play and seek at once, read a piece at a time from their encrypted pieces, never held whole in memory. See [Collection](#collection).":
    "**Musica e video di qualsiasi dimensione nella Raccolta dell’app desktop**: suonano e si spostano subito, letti un pezzo alla volta dai loro pezzi cifrati, mai interi in memoria. Vedi [Raccolta](#collection).",
  "**Playlists in the Collection's Music**: songs in the order you choose, kept encrypted with the Collection, played in order or shuffled. Make one at the top of Music, and add songs from their menu or by holding them down. See [Collection](#collection).":
    "**Playlist nella Musica della Raccolta**: canzoni nell’ordine che scegli, cifrate con la Raccolta, in ordine o in ordine casuale. Creane una in alto in Musica, e aggiungi canzoni dal loro menu o tenendole premute. Vedi [Raccolta](#collection).",
  "**Subtitles for the Collection's videos**: an .srt or .vtt file in the same folder with the video's name (film.srt, or film.en.srt) shows as its subtitles, and a tap at the top turns them off or on. See [Collection](#collection).":
    "**Sottotitoli per i video della Raccolta**: un file .srt o .vtt nella stessa cartella con il nome del video (film.srt, o film.en.srt) si mostra come i suoi sottotitoli, e un tocco in alto li toglie o li rimette. Vedi [Raccolta](#collection).",
  "**A player's screen for the Collection**: tap the bar of the music playing, or **Now playing**, for its cover, title, artist and album, a bar to move in it, previous and next, **Shuffle**, **Repeat** (all or one), the speed from 0.5× to 2×, and the list, to tap another. A video, or music of 10 minutes or more, starts where you left it. The notification shows the title and cover only with **Show the title in the notification** on. See [Collection](#collection).":
    "**Una schermata del lettore per la Raccolta**: tocca la barra della musica in riproduzione, o **Ora in riproduzione**, per copertina, titolo, artista e album, una barra per spostarti, precedente e successivo, **Casuale**, **Ripeti** (tutto o uno), la velocità da 0.5× a 2× e l’elenco, per toccarne un altro. Un video, o musica di 10 minuti o più, riparte da dove l’hai lasciato. La notifica mostra titolo e copertina solo con **Mostra il titolo nella notifica** attivo. Vedi [Raccolta](#collection).",
  "**Photos, Videos, Music and Files**: the Collection has a tab for each, each with the folders that hold any of its files above it. See [Collection](#collection).":
    "**Foto, Video, Musica e File**: la Raccolta ha una scheda per ciascuno, con sopra le cartelle che ne contengono. Vedi [Raccolta](#collection).",
  "**Music of the Collection goes on with the screen off**: on Android, music could stop a while after the screen went off. Now the player is kept in the foreground for as long as the list plays. See [Collection](#collection).":
    "**La musica della Raccolta continua a schermo spento**: su Android la musica poteva fermarsi un po’ dopo lo spegnimento dello schermo. Ora il lettore resta in primo piano finché la lista suona. Vedi [Raccolta](#collection).",
  "**More music and video formats in the Collection**: on Android MP3, AAC, M4A, FLAC, Ogg, Opus, WAV, AMR, MP4, MKV, WebM and 3GP play, also a file that came with no type, known by its name's ending, and seeking works in an MP3 with no table of its seconds. See [Collection](#collection).":
    "**Più formati di musica e video nella Raccolta**: su Android si riproducono MP3, AAC, M4A, FLAC, Ogg, Opus, WAV, AMR, MP4, MKV, WebM e 3GP, anche un file arrivato senza tipo, riconosciuto dalla fine del suo nome, e lo spostamento a un punto funziona anche in un MP3 senza tabella dei suoi secondi. Vedi [Raccolta](#collection).",
  "**New modules on after an update**: where the modules were chosen before the Collection came, as on a phone or computer updated from 6, the Collection stayed off. Now it is on there, as is any module that comes later, until you turn it off in Settings → General → Modules. See [Modules](#modules).":
    "**Nuovi moduli attivi dopo un aggiornamento**: dove i moduli erano stati scelti prima che arrivasse la Raccolta, come su un telefono o un computer aggiornato dalla 6, la Raccolta restava disattivata. Ora lì è attiva, come ogni modulo che arriva dopo, finché non la disattivi in Impostazioni → Generali → Moduli. Vedi [Moduli](#modules).",
  "**A home relay by itself**: on Android, when your relay names a relay paired with it, a space with no home relay takes that one, only through Tor, with its token from a coupon: nothing to type. **Automatically from your relay**, under Settings → Relay and networks → Home relay, turns it off. See [Home relay](#home-relay).":
    "**Un relay di casa da solo**: su Android, quando il tuo relay nomina un relay abbinato a lui, uno spazio senza relay di casa prende quello, solo tramite Tor, con il suo token da un coupon: niente da scrivere. **Automaticamente dal tuo relay**, in Impostazioni → Relay e reti → Relay di casa, lo disattiva. Vedi [Relay di casa](#home-relay).",
  "**A chip for every part that is on**: above the chats, **SMS**, **Erevos**, **Matrix**, **XMPP** and **Nostr** each have their chip whenever they are on in Modules, also with no chat yet. Before, in a space with only SMS so far, choosing **All messages** after Erevos's icon opened its chats hid the chips, with no way back.":
    "**Un chip per ogni parte attiva**: sopra le chat, **SMS**, **Erevos**, **Matrix**, **XMPP** e **Nostr** hanno ciascuno il suo chip quando sono attivi in Moduli, anche senza ancora una chat. Prima, in uno spazio con solo SMS finora, scegliere **Tutti** dopo che l’icona di Erevos aveva aperto le sue chat nascondeva i chip, senza modo di tornare.",
  "**Invite at one tap**: on the home screen, **Invite** beside the relay's line shows an invite's QR code at once, with nothing to type: who it is for and your name for them can be typed below it, or never. See [Chat through a relay](#relay).":
    "**Invitare con un tocco**: nella schermata iniziale, **Invita** accanto alla riga del relay mostra subito il codice QR di un invito, senza scrivere nulla: per chi è e il tuo nome per quella persona si possono scrivere sotto, o mai. Vedi [Chat tramite un relay](#relay).",
  "**Sign in with LPHL without typing a code**: on Android, once you sign in on the page the browser opened, tap **Open Erevos** there, and Erevos finishes signing in by itself. The code to type is still on the page, in case nothing opens. It needs the relay updated. See [Chat through a relay](#relay).":
    "**Accedi con LPHL senza scrivere un codice**: su Android, dopo aver effettuato l’accesso nella pagina aperta dal browser, tocca lì **Apri Erevos** ed Erevos completa l’accesso da solo. Il codice da scrivere resta nella pagina, nel caso non si apra nulla. Serve il relay aggiornato. Vedi [Chat tramite un relay](#relay).",
  "**Invites and contact links by touch**: on an Android phone with NFC, while **Invite someone** or **My QR code** shows the small QR code, hold the back of their phone to the back of yours: their phone opens it by itself, in Erevos where it is installed. See [Chat through a relay](#relay).":
    "**Inviti e link di contatto con un tocco**: su un telefono Android con NFC, mentre **Invita qualcuno** o **Il mio codice QR** mostra il codice QR piccolo, appoggia il retro del suo telefono al retro del tuo: il suo telefono lo apre da solo, in Erevos se è installato. Vedi [Chat tramite un relay](#relay).",
  "**Smaller invite QR codes**: the QR code of **Invite someone** now holds about eight times less, so simpler and older cameras read it too, and its link is short enough for an SMS. It opens Erevos's page for invites, which offers Erevos and then opens the invite in it. Where your relay lets this phone make no invite, the long one is still made. See [Chat through a relay](#relay).":
    "**Codici QR d’invito più piccoli**: il codice QR di **Invita qualcuno** ora contiene circa otto volte meno, così lo leggono anche fotocamere più semplici e vecchie, e il suo link è abbastanza corto per un SMS. Apre la pagina degli inviti di Erevos, che offre Erevos e poi vi apre l’invito. Dove il tuo relay non lascia fare inviti a questo telefono, si fa ancora quello lungo. Vedi [Chat tramite un relay](#relay).",
  "**A small contact QR code**: **Show my QR code** now shows your contact link in short, so any camera reads it, and **Share my contact link** sends a link any app lets you tap. Whoever scans it while it shows is your contact at once; later, they write a message request first. **Large QR code, for no internet** shows the whole one, for near with no internet. See [Chat through a relay](#relay).":
    "**Un piccolo codice QR di contatto**: **Mostra il mio codice QR** ora mostra il tuo link di contatto in breve, così qualsiasi fotocamera lo legge, e **Condividi il mio link di contatto** invia un link che qualsiasi app lascia toccare. Chi lo scansiona mentre è mostrato diventa subito un tuo contatto; più tardi, scrive prima una richiesta di messaggio. **Codice QR grande, senza internet** mostra quello intero, per vicino e senza internet. Vedi [Chat tramite un relay](#relay).",
  "**Links open Erevos**: on Android, an invite or contact link tapped in any app opens Erevos, which asks before it takes it, once the web server and a new Erevos are both out. See [Chat through a relay](#relay).":
    "**I link aprono Erevos**: su Android, un link di invito o di contatto toccato in qualsiasi app apre Erevos, che chiede prima di accettarlo, quando saranno usciti il server web e un nuovo Erevos. Vedi [Chat tramite un relay](#relay).",
  "**Home relay**: the screen no longer says that whoever runs a home relay sees this phone's address when it is set to **Only through Tor**.":
    "**Relay di casa**: la schermata non dice più che chi gestisce un relay di casa vede l’indirizzo di questo telefono quando è su **Solo tramite Tor**.",
  "**An invite that opened Erevos for the first time** opens once the first start's setup is done, however long it took; before, after five minutes on the setup screens it was lost.":
    "**Un invito che ha aperto Erevos per la prima volta** si apre quando la configurazione del primo avvio è finita, per quanto tempo ci sia voluto; prima, dopo cinque minuti sulle schermate di configurazione, andava perso.",
  // 7.0.0-rc.1
  "**Linked devices on the same Wi-Fi**: the phone and a computer on the same Wi-Fi or hotspot give each other what changes straight there, with no internet too. See [Linked devices](#devices).":
    "**Dispositivi collegati sullo stesso Wi-Fi**: il telefono e un computer sullo stesso Wi-Fi o hotspot si passano ciò che cambia direttamente lì, anche senza internet. Vedi [Dispositivi collegati](#devices).",
  "**Your Matrix, XMPP and Nostr accounts on every linked device**: each device linked gets them by itself, with no choice to make, and they follow as they change on the phone: one you sign out of there, or replace with another, goes from the devices too. See [Linked devices](#devices).":
    "**I tuoi account Matrix, XMPP e Nostr su ogni dispositivo collegato**: ogni dispositivo collegato li riceve da sé, senza nulla da scegliere, e seguono i cambiamenti sul telefono: quello da cui esci lì, o che sostituisci con un altro, se ne va anche dai dispositivi. Vedi [Dispositivi collegati](#devices).",
  "**Same settings on your linked devices**: the language, the look and Last seen changed on the phone or a computer change on the others too. A photo behind the screens, passwords, PINs and what is about one device alone stay on each. A device can keep its own: **Same settings on every device** in Linked devices. See [Linked devices](#devices).":
    "**Stesse impostazioni sui tuoi dispositivi collegati**: la lingua, l’aspetto e Ultimo accesso cambiati sul telefono o su un computer cambiano anche sugli altri. Una foto dietro le schermate, le password, i PIN e ciò che riguarda un solo dispositivo restano su ciascuno. Un dispositivo può tenere le sue: **Stesse impostazioni su tutti i dispositivi** in Dispositivi collegati. Vedi [Dispositivi collegati](#devices).",
  "**Last seen**: when a contact is not online, their chat says when they last had Erevos open, to the minute. It goes end-to-end encrypted, never to the relay. It is on, and both ways: turn it off in Settings → Privacy and security → Last seen, and no one sees yours, nor you theirs. Hidden chats have their own time and their own switch, in a chat's details there. See [Chat through a relay](#relay).":
    "**Ultimo accesso**: quando un contatto non è online, la sua chat dice quando ha avuto Erevos aperto l’ultima volta, al minuto. Viene inviato crittografato end-to-end, mai al relay. È attivo, e in entrambe le direzioni: disattivalo in Impostazioni → Privacy e sicurezza → Ultimo accesso, e nessuno vede il tuo, né tu il loro. Le chat nascoste hanno un’ora propria e un interruttore proprio, nei dettagli di una chat di lì. Vedi [Chat tramite un relay](#relay).",
  "**One Public feed**: the new **Public** chip on the home screen shows the public posts of the Nostr people you follow and the public Matrix rooms you are in as one feed, as in Amethyst, with photos inside the posts and a card for a link. Answer, share again, like, share and write new posts with photos; for Matrix, answer, react and share. **Photos** chooses whether photos come at once, only through Tor or on a tap. The **Nostr** chip shows only the Nostr chats again. See [Chats with other Nostr apps](#nostr-chats).":
    "**Un solo feed pubblico**: il nuovo pulsante **Pubblico** nella schermata principale mostra in un solo feed, come in Amethyst, i post pubblici delle persone Nostr che segui e le stanze Matrix pubbliche in cui sei, con le foto dentro i post e una scheda per un link. Rispondi, condividi di nuovo, metti Mi piace, condividi e scrivi nuovi post con foto; per Matrix, rispondi, reagisci e condividi. **Foto** sceglie se le foto arrivano subito, solo tramite Tor o con un tocco. Il pulsante **Nostr** mostra di nuovo solo le chat Nostr. Vedi [Chat con altre app Nostr](#nostr-chats).",
  "**Collection**: an encrypted place in every space and hidden place for photos, files and folders, with its icon next to the lock. Turn it on in Modules. See [Collection](#collection).":
    "**Raccolta**: un posto cifrato in ogni spazio e in ogni luogo nascosto per foto, file e cartelle, con la sua icona accanto al lucchetto. Attivala in Moduli. Vedi [Raccolta](#collection).",
  "**Music, videos and PDFs in the Collection**: music and videos play from their encrypted pieces, music on with the screen off and with play, pause, next and previous on the lock screen, and PDFs read page by page inside Erevos. **Open with another app** leaves no plain copy, and a photo or video picked from the gallery can be deleted there after importing. See [Collection](#collection).":
    "**Musica, video e PDF nella Raccolta**: musica e video si riproducono dai loro pezzi cifrati, la musica anche a schermo spento, con riproduci, pausa, successivo e precedente sulla schermata di blocco, e i PDF si leggono pagina per pagina dentro Erevos. **Apri con un’altra app** non lascia copie in chiaro, e una foto o un video della galleria può esservi eliminato dopo l’importazione. Vedi [Raccolta](#collection).",
  "**The Collection on a computer**: in the desktop app for Linux, macOS and Windows the Collection keeps your photos and files encrypted too. Photos, PDFs, music and videos open in memory only, never as a plain copy on the disk, and close when the space locks. **Save to the computer** asks first. See [Collection](#collection).":
    "**La Raccolta sul computer**: nell’app per computer per Linux, macOS e Windows la Raccolta tiene cifrati anche lì le tue foto e i tuoi file. Foto, PDF, musica e video si aprono solo in memoria, mai come copia in chiaro sul disco, e si chiudono quando lo spazio si blocca. **Salva sul computer** chiede prima. Vedi [Raccolta](#collection).",
  "**Files up to 4 GB in the Collection**: on Android a file picked from the phone's files is encrypted as it is read, with no plain copy first, so it comes in faster and needs no room twice. In the desktop app music and videos up to 1 GB play. See [Collection](#collection).":
    "**File fino a 4 GB nella Raccolta**: su Android un file scelto dai file del telefono viene cifrato mentre viene letto, senza una copia in chiaro prima, così entra più in fretta e non occupa il doppio dello spazio. Nell’app per computer si riproducono musica e video fino a 1 GB. Vedi [Raccolta](#collection).",
  "**The Collection on a WebDAV server**: each space and hidden place can copy its Collection, still encrypted, to a folder on a server you choose, Nextcloud, ownCloud or any that speaks WebDAV, so big files are not only on the phone. Only what is new goes, and a phone that lacks a file fetches it from there. See [Collection](#collection).":
    "**La Raccolta su un server WebDAV**: ogni spazio e ogni luogo nascosto può copiare la sua Raccolta, sempre cifrata, in una cartella su un server che scegli tu, Nextcloud, ownCloud o qualsiasi server che parli WebDAV, così i file grandi non stanno solo sul telefono. Va solo ciò che è nuovo, e un telefono a cui manca un file lo prende da lì. Vedi [Raccolta](#collection).",
  "**The Collection on your linked devices**: turn on **On my linked devices too** in a Collection's settings and that Collection goes to the space's or hidden place's linked devices, changes and deletions with it. Small pictures come at once, a file itself on the same Wi-Fi or when you open it, a piece at a time, going on where it stopped after the network drops. See [Collection](#collection).":
    "**La Raccolta sui tuoi dispositivi collegati**: attiva **Anche sui miei dispositivi collegati** nelle impostazioni di una Raccolta e quella Raccolta va sui dispositivi collegati dello spazio o luogo nascosto, con modifiche ed eliminazioni. Le miniature arrivano subito, il file stesso sulla stessa Wi-Fi o quando lo apri, un pezzo alla volta, riprendendo da dove si era fermato se la rete cade. Vedi [Raccolta](#collection).",
  "**Groups stay on the device you choose**: on the phone, under Linked devices → Groups stay on, move the groups to a linked computer. Their keys go there, never copied, so the groups work there with the phone off and new ones can be made there; members see nothing new. See [Linked devices](#devices).":
    "**I gruppi restano sul dispositivo che scegli**: sul telefono, in Dispositivi collegati → I gruppi restano su, sposta i gruppi su un computer collegato. Le loro chiavi vanno lì, mai copiate, così i gruppi funzionano lì a telefono spento e lì se ne possono creare di nuovi; i membri non vedono niente di nuovo. Vedi [Dispositivi collegati](#devices).",
  "**Add someone new on a linked device without the phone**: a computer adds someone whose contact link is from this version by itself, with the phone off, and writes to them at once; they see your account as a request, with the same safety number, and the phone adds them too once it is on. See [Linked devices](#devices).":
    "**Aggiungi qualcuno di nuovo su un dispositivo collegato senza il telefono**: un computer aggiunge da solo qualcuno il cui link di contatto è di questa versione, a telefono spento, e gli scrive subito; quella persona vede il tuo account come una richiesta, con lo stesso numero di sicurezza, e il telefono la aggiunge anche lui appena è acceso. Vedi [Dispositivi collegati](#devices).",
  "**Calls and Send later on your linked devices without the phone**: with a contact on this version, a computer calls and is called by itself and sends a message for later itself, with the phone off, and a copy goes to each of their devices too, held till its time. Every device of yours shows what is scheduled, and deleting it on any of them takes it back everywhere. See [Linked devices](#devices).":
    "**Chiamate e Invia più tardi sui tuoi dispositivi collegati senza il telefono**: con un contatto con questa versione, un computer chiama e riceve le chiamate da solo e invia da sé un messaggio per dopo, a telefono spento, e una copia va anche a ognuno dei suoi dispositivi, tenuta fino alla sua ora. Ogni tuo dispositivo mostra ciò che è programmato, ed eliminarlo su uno qualsiasi lo annulla ovunque. Vedi [Dispositivi collegati](#devices).",
  '**Support Erevos**: every way has its QR code now, Liberapay and PayPal too, and PayPal opens in the browser.':
    '**Sostieni Erevos**: ogni modo ha ora il suo codice QR, anche Liberapay e PayPal, e PayPal si apre nel browser.',
  '**Chats open at their end**: a long chat, or one with imported messages, could open at a message read long ago, often a photo, as it drew earlier messages on its way to the end. Now it opens at the newest message, and the arrow to where you left off is there when new ones came.':
    '**Le chat si aprono alla fine**: una chat lunga, o una con messaggi importati, poteva aprirsi su un messaggio letto da tempo, spesso una foto, perché caricava messaggi precedenti mentre andava verso la fine. Ora si apre sul messaggio più recente, e la freccia verso dove avevi lasciato c’è quando ne sono arrivati di nuovi.',
  "**Tor off unless you turn it on**: a new space sends nothing through Tor, so messages go fastest, and turning Tor on asks first, as it makes them slower. A space you already have keeps its choice, under Settings → Relay and networks → Tor. Texts through Nostr now go without Tor too: then the Nostr relays see your phone's internet address, never who wrote to whom. See [Through Tor](#tor).":
    "**Tor spento finché non lo attivi**: un nuovo spazio non invia nulla tramite Tor, quindi i messaggi vanno più veloci, e attivare Tor chiede prima, perché li rallenta. Uno spazio che hai già mantiene la sua scelta, in Impostazioni → Relay e reti → Tor. I testi tramite Nostr ora vanno anche senza Tor: allora i relay Nostr vedono l’indirizzo internet del tuo telefono, mai chi ha scritto a chi. Vedi [Tramite Tor](#tor).",
  "**Moving a chat to a space with no relay**: **Move to another space** stopped there, as that space had no relay of its own. Now it offers this space's relay, which that space then keeps, and it makes that space's relay queue when it has a relay but no queue yet. See [Second password](#second).":
    "**Spostare una chat in uno spazio senza relay**: **Sposta in un altro spazio** si fermava lì, perché quello spazio non aveva un relay suo. Ora offre il relay di questo spazio, che quello spazio poi tiene, e crea la coda di quello spazio sul relay quando ha un relay ma ancora nessuna coda. Vedi [Seconda password](#second).",
  "**Fixes from a review of all the code**: a message you were typing stays with its chat when you open another, and never shows in a PIN-locked chat's place; a locked chat under a locked group stays out of screenshots when the group closes; the Collection's catalogue goes into backups, so a restored phone opens its files; calls in a public group reach their members; a Matrix or XMPP account no longer stops for good at one bad message or an unreachable server; a message sent for later stays listed while its details are still coming; the computer app's Wi-Fi link refuses an impossible port; and the panic button lets the apps it tells start before it closes.":
    "**Correzioni da una revisione di tutto il codice**: un messaggio che stavi scrivendo resta nella sua chat quando ne apri un'altra, e non compare mai al posto di una chat con PIN; una chat bloccata sotto un gruppo bloccato resta fuori dagli screenshot quando il gruppo si chiude; il catalogo della Collezione entra nei backup, così un telefono ripristinato apre i suoi file; le chiamate in un gruppo pubblico raggiungono i suoi membri; un account Matrix o XMPP non si ferma più per sempre su un messaggio danneggiato o un server irraggiungibile; un messaggio per dopo resta in elenco mentre i suoi dettagli stanno ancora arrivando; il collegamento Wi-Fi dell'app per computer rifiuta una porta impossibile; e il pulsante antipanico lascia avviare le app che avvisa prima di chiudersi.",
  "**Safer in twelve more ways, from the review before 7**: a message the relay hands you is deleted there only once your phone has kept it, so a connection cut at that moment loses nothing (an older relay works as before); a relay keeps a bound on what it holds in all and for each phone; in a public group no one can have another member taken out by claiming to be them; with SMS invites off, no one becomes a contact from your number alone; searches that find nothing are forgotten after a quarter of an hour; a Matrix message is shown as its sender's only when the key came from their device, else as **Not verified**, and an XMPP or Matrix device that changes its key gets nothing until you accept it, while a new device is said in the chat; a photo or file from a server its sender chose is fetched by itself only through Tor, else on a tap; an old first packet replayed to you never takes over a chat; and your linked devices' log takes each device's changes only from that device, and forgets devices that are gone.":
    "**Più sicuro in altri dodici modi, dalla revisione prima della 7**: un messaggio che il relay ti consegna viene cancellato lì solo quando il tuo telefono l'ha conservato, così una connessione interrotta in quel momento non perde nulla (un relay più vecchio funziona come prima); un relay tiene un limite a quanto conserva in tutto e per ogni telefono; in un gruppo pubblico nessuno può far espellere un altro membro spacciandosi per lui; con gli inviti SMS disattivati, nessuno diventa contatto solo dal tuo numero; le ricerche che non trovano nulla vengono dimenticate dopo un quarto d'ora; un messaggio Matrix è mostrato come del suo mittente solo quando la chiave è venuta dal suo dispositivo, altrimenti come **Non verificato**, e un dispositivo XMPP o Matrix che cambia chiave non riceve nulla finché non lo accetti, mentre un nuovo dispositivo viene detto nella chat; una foto o un file da un server scelto dal mittente arriva da solo soltanto tramite Tor, altrimenti con un tocco; un vecchio primo pacchetto rimandato non prende mai una chat; e il registro dei tuoi dispositivi collegati prende le modifiche di ogni dispositivo solo da quel dispositivo, e dimentica i dispositivi andati via.",
  "**A home relay only through Tor**: switch a home relay to **Only through Tor** and it never sees your phone's address, whatever Tor is set to for the rest. With no token typed, it gives one for a coupon that your relay signs blind, so neither relay can tell whose it is, and two spaces can use each other's relays as home relays with nothing tying them together. The token comes within the hour, lasts 90 days, and Erevos renews it by itself. Needs Tor, on Android. See [Home relay](#home-relay).":
    '**Un relay di casa solo tramite Tor**: imposta un relay di casa su **Solo tramite Tor** e non vede mai l’indirizzo del tuo telefono, qualunque cosa sia impostata per Tor per il resto. Senza token scritto, ne dà uno in cambio di un coupon che il tuo relay firma alla cieca, così nessuno dei due relay può capire di chi è, e due spazi possono usare i relay l’uno dell’altro come relay di casa senza che nulla li leghi. Il token arriva entro un’ora, dura 90 giorni ed Erevos lo rinnova da solo. Serve Tor, su Android. Vedi [Relay di casa](#home-relay).',
  // 6.0.0-rc.2
  "**Home's buttons stay at the bottom**: after the password, home's **Remind me** and **New chat** could float halfway up the screen, over the chats, with the list ending above them, until Erevos went away and came back. Now the screen asks Android at once whether a keyboard is open. See [Password lock](#lock).":
    "**I pulsanti della schermata iniziale restano in basso**: dopo la password, **Ricordamelo** e **Nuova chat** potevano restare a metà schermo, sopra le chat, con l’elenco che finiva sopra di loro, finché non si usciva da Erevos e si tornava. Ora la schermata chiede subito ad Android se c’è una tastiera aperta. Vedi [Blocco con password](#lock).",
  "**The Nostr tab's posts come**: **Posts** could stay on **Looking…** for good through Tor. Each wait through Tor took one of the threads the whole app shares, and once all were taken, every look-up of the posts waited behind the others; a relay that answered and then could not be reached kept them waiting with no end. Now Tor's waits have threads of their own, a relay that cannot be reached is let be after 20 seconds, and the posts come within about two minutes at most, with what was found by then. See [Chats with other Nostr apps](#nostr-chats).":
    "**Arrivano i post della scheda Nostr**: **Post** poteva restare per sempre su **Ricerca…** tramite Tor. Ogni attesa tramite Tor occupava uno dei thread che tutta l’app condivide, e quando erano tutti occupati, ogni ricerca dei post aspettava dietro alle altre; un relay che aveva risposto e poi non era più raggiungibile li faceva aspettare senza fine. Ora le attese di Tor hanno thread propri, un relay che non si può raggiungere viene lasciato dopo 20 secondi, e i post arrivano entro circa due minuti al massimo, con quello che è stato trovato fino ad allora. Vedi [Chat con altre app Nostr](#nostr-chats).",
  "**Linux, Windows and macOS again**: 6.0.0-rc.1 came out without them: the check that each build for computers opens did not know the setup of Erevos's very first start. Now it does.":
    "**Di nuovo Linux, Windows e macOS**: la 6.0.0-rc.1 è uscita senza di loro: il controllo che ogni versione per computer si apra non conosceva la configurazione del primissimo avvio di Erevos. Ora la conosce.",
  // 6.0.0-rc.1
  "**Links open on Sailfish OS**: **Sign in with LPHL**, a donation page or a link in a chat opened nothing there. Now Sailfish OS opens them: a web page in the browser, a number in the phone or the messages, an address in the mail.":
    "**I link si aprono su Sailfish OS**: **Accedi con LPHL**, una pagina di donazione o un link in una chat non aprivano nulla. Ora li apre Sailfish OS: una pagina web nel browser, un numero nel telefono o nei messaggi, un indirizzo nella posta.",
  "**Matrix, and photos and files in XMPP and Nostr chats, on Sailfish OS**: Erevos there could not reach their servers over HTTPS, so Matrix could not sign in, photos and files neither came nor went, and links showed no preview. Now they work as on a computer.":
    "**Matrix, e foto e file nelle chat XMPP e Nostr, su Sailfish OS**: lì Erevos non raggiungeva i loro server via HTTPS, quindi Matrix non poteva accedere, foto e file non arrivavano né partivano e i link non mostravano l'anteprima. Ora funzionano come su un computer.",
  "**A phone call shows its screen**: with Erevos as the phone app, a call that came could ring with the phone's screen black, so it could not be answered, when Android's full-screen notifications for Erevos, Erevos's notices or its notices of incoming calls were off. Now the call screen comes up by itself, over the lock screen too, and turns the screen on. A call that Do Not Disturb holds back still comes quietly, with the screen off. See [Phone](#phone).":
    "**Una chiamata telefonica mostra la sua schermata**: con Erevos come app Telefono, una chiamata in arrivo poteva squillare con lo schermo nero, senza poter rispondere, quando erano disattivate le notifiche a schermo intero di Android per Erevos, le notifiche di Erevos o le sue notifiche delle chiamate in arrivo. Ora la schermata di chiamata compare da sola, anche sulla schermata di blocco, e accende lo schermo. Una chiamata che «Non disturbare» trattiene arriva ancora in silenzio, a schermo spento. Vedi [Telefono](#phone).",
  "**The calculator shows a long result from its start**: upright, a result with many decimals hid its first digits, which showed only with the phone turned sideways. Now a long number gets smaller to fit, its first digits always in sight.":
    "**La calcolatrice mostra un risultato lungo dall'inizio**: in verticale, un risultato con molti decimali nascondeva le prime cifre, visibili solo con il telefono in orizzontale. Ora un numero lungo si rimpicciolisce per starci, con le prime cifre sempre in vista.",
  "**Pick the recipient of a new SMS from your contacts**: **New SMS** has a **Contacts** button that opens your contacts with a search, and typing a name or number suggests the contacts that match. A contact with several numbers shows a line for each, and for a group MMS each one you pick is added. With only the SMS open, only the phone's contacts show. See [SMS](#sms).":
    "**Scegli il destinatario di un nuovo SMS tra i contatti**: **Nuovo SMS** ha un pulsante **Contatti** che apre i tuoi contatti con una ricerca, e scrivendo un nome o un numero vengono suggeriti i contatti che corrispondono. Un contatto con più numeri mostra una riga per ciascuno, e in un MMS di gruppo ogni contatto scelto si aggiunge. Con solo gli SMS aperti compaiono solo i contatti del telefono. Vedi [SMS](#sms).",
  "**More for a number in the Phone**: on the keypad, **⋯** beside a typed number offers **Add to contacts**, **Add to an existing contact**, **Send an SMS** and **Copy the number**. **Recents** and **Favourites** offer **Copy the number** and **Open the contact**; **Favourites** also **Send an SMS**, and **Recents** adds an unknown number to an existing contact. With Erevos locked, the Phone still only calls. See [Phone](#phone).":
    "**Altro per un numero nel Telefono**: sulla tastiera, **⋯** accanto a un numero digitato offre **Aggiungi ai contatti**, **Aggiungi a un contatto esistente**, **Invia un SMS** e **Copia il numero**. **Recenti** e **Preferiti** offrono **Copia il numero** e **Apri il contatto**; i **Preferiti** anche **Invia un SMS**, e i **Recenti** aggiungono un numero sconosciuto a un contatto esistente. Con Erevos bloccato, il Telefono continua solo a chiamare. Vedi [Telefono](#phone).",
  "**A short buzz on touch**: the keys of the keypad, **Call**, **End**, Send, the keyboard's Enter, switches and menus that open give a short buzz. **Settings** → **Appearance** → **Vibrate on touch** turns it off. See [Appearance](#appearance).":
    "**Una breve vibrazione al tocco**: i tasti della tastiera, **Chiama**, **Termina**, Invia, l’Invio della tastiera, gli interruttori e i menu che si aprono danno una breve vibrazione. In **Impostazioni** → **Aspetto** → **Vibrazione al tocco** la spegni. Vedi [Aspetto](#appearance).",
  "**A number on each icon, on Huawei and Honor**: their launchers now show a number on each of Erevos's icons apart, with **Number on the icon** on: on Erevos's own the messages, on SMS's the SMS not read, on Phone's the missed calls, on Contacts's a birthday today. Most other launchers, such as those of Pixel and GrapheneOS, Samsung's and Kvaesitso, give a notice's dot or number to all of an app's icons alike, and Erevos cannot change that there. See [Appearance](#appearance).":
    "**Un numero su ogni icona, su Huawei e Honor**: i loro launcher ora mostrano un numero su ciascuna icona di Erevos a parte, con **Numero sull’icona** attivo: su quella di Erevos i messaggi, su quella degli SMS gli SMS non letti, su quella del Telefono le chiamate perse, su quella dei Contatti un compleanno di oggi. La maggior parte degli altri launcher, come quelli dei Pixel e di GrapheneOS, quello di Samsung e Kvaesitso, dà il punto o il numero di una notifica a tutte le icone di un’app allo stesso modo, e lì Erevos non può cambiarlo. Vedi [Aspetto](#appearance).",
  "**Choose the parts of Erevos you use**: Erevos's own chats, the Phone, the SMS, and the chats with Nostr, Matrix and XMPP apps are modules now, any of them on, Erevos's own too, at least one. One that is off does not start and shows nowhere, and the Phone's and the SMS's icons leave the phone's apps: Erevos is lighter, opens faster and uses less battery. Nothing of it is deleted: it is all there again when it is back on. Erevos's very first start sets it up as an installer does, its language, the modules and what Android should allow for them; a module turned on later asks for its permissions again. After this update every module stays on until you change them in **Settings** → **General** → **Modules**. See [Modules](#modules).":
    "**Scegli le parti di Erevos che usi**: le chat di Erevos, il Telefono, gli SMS e le chat con app Nostr, Matrix e XMPP ora sono moduli, uno qualsiasi può essere attivo, anche quello di Erevos, almeno uno. Uno disattivato non si avvia e non compare da nessuna parte, e le icone del Telefono e degli SMS escono dalle app del telefono: Erevos è più leggero, si apre più in fretta e consuma meno batteria. Di esso non si cancella nulla: torna tutto quando viene riattivato. Il primissimo avvio di Erevos lo configura come fa un installer, la lingua, i moduli e ciò che Android deve consentire per loro; un modulo attivato più tardi chiede di nuovo le sue autorizzazioni. Dopo questo aggiornamento ogni modulo resta attivo finché non lo cambi in **Impostazioni** → **Generali** → **Moduli**. Vedi [Moduli](#modules).",
  "**Public posts in the Nostr tab**: on the home screen, the Nostr tab shows first **Posts**, the public posts of the people your Nostr key follows and what they shared again, newest first, as in Amethyst or a Telegram channel, with **Chats** one tap away. Older ones come as you scroll to the end, the newest when you pull the list down; tap who wrote a post for their posts or to write to them. Read only, looked up through Tor as the space says and not kept, and no pictures or links are opened. See [Chats with other Nostr apps](#nostr-chats).":
    "**Post pubblici nella scheda Nostr**: nella schermata principale, la scheda Nostr mostra per primi i **Post**, i post pubblici delle persone che la tua chiave Nostr segue e quello che hanno condiviso di nuovo, dal più recente, come in Amethyst o in un canale Telegram, con le **Chat** a un tocco. I meno recenti arrivano quando scorri fino in fondo, i più recenti quando tiri giù la lista; tocca chi ha scritto un post per i suoi post o per scrivergli. In sola lettura, cercati tramite Tor come dice lo spazio e non conservati, e non vengono aperte immagini né link. Vedi [Chat con altre app Nostr](#nostr-chats).",
  "**Hidden chats on your linked devices**: each place of hidden chats now links on its own, from inside it, to the same place on a computer or in a browser, with **Linked devices** under its list. Its chats, messages, groups, calls, Chat with myself and its own Matrix, XMPP and Nostr accounts go there, and its contacts write to it there directly. Nothing of it shows in the space or on the space's linked devices. The link runs while the place is open, and while it is closed too with **Receive while closed** on. See [Linked devices](#devices).":
    "**Chat nascoste sui tuoi dispositivi collegati**: ogni posto di chat nascoste ora si collega per conto suo, dall’interno, allo stesso posto su un computer o in un browser, con **Dispositivi collegati** sotto il suo elenco. Le sue chat, i messaggi, i gruppi, le chiamate, la sua Chat con me stesso e i suoi account Matrix, XMPP e Nostr vanno lì, e i suoi contatti gli scrivono lì direttamente. Niente di questo si vede nello spazio né sui dispositivi collegati dello spazio. Il collegamento funziona finché il posto è aperto, e anche da chiuso con **Ricevere da chiuse** attivo. Vedi [Dispositivi collegati](#devices).",
  "**Move a chat to another space**: in a chat's **Details**, **Move to another space** takes it, with its messages, name, picture, look and imported chats, into the space whose password you type, as a move into hidden chats does: the safety number stays the same, and their phone is told at once to write there. That space stays closed, and the row shows in every space. A chat never takes the place of one that space, or hidden chats, already have with the same person. See [Second password](#second).":
    "**Spostare una chat in un altro spazio**: nei **Dettagli** di una chat, **Sposta in un altro spazio** la porta, con i suoi messaggi, nome, immagine, aspetto e chat importate, nello spazio di cui scrivi la password, come lo spostamento nelle chat nascoste: il codice di sicurezza resta lo stesso, e al suo telefono viene detto subito di scrivere lì. Quello spazio resta chiuso, e la voce si vede in ogni spazio. Una chat non prende mai il posto di un’altra che quello spazio, o delle chat nascoste, hanno già con la stessa persona. Vedi [Seconda password](#second).",
  // 4.0.0-rc.10
  "**Erevos no longer stops when only the SMS or the Contacts are open**: from them, a contact's chat, an SMS, another icon or a screen that asks for the password again could make Erevos say it could not open (Maximum call stack size exceeded). Now the password opens all of Erevos, then that screen. And when Erevos cannot open, **Try again** starts it again. See [Password lock](#lock).":
    "**Erevos non si ferma più quando sono aperti solo gli SMS o i contatti**: da lì, la chat di un contatto, un SMS, un'altra icona o una schermata che chiede di nuovo la password potevano far dire a Erevos che non si era potuto aprire (Maximum call stack size exceeded). Ora la password apre tutto Erevos e poi quella schermata. E quando Erevos non si può aprire, **Riprova** lo riavvia. Vedi [Blocco con password](#lock).",
  "**Each icon opens what it names**: after Erevos was opened by the SMS icon, or from the recent apps, another icon, the widget or a notice could sometimes show the SMS instead. Now each opens what it names. With only the SMS or the Contacts open, another icon asks for the password as when Erevos is locked, then opens its own part: the Contacts icon only the contacts, Erevos's own icon all of it. And Back on Erevos's first screen now puts it behind, as Home does, whatever opened it. See [Password lock](#lock).":
    "**Ogni icona apre ciò che indica**: dopo che Erevos era stato aperto dall’icona SMS o dalle app recenti, un’altra icona, il widget o una notifica potevano a volte mostrare invece gli SMS. Ora ognuno apre ciò che indica. Quando sono aperti solo gli SMS o i contatti, un’altra icona chiede la password come quando Erevos è bloccato e poi apre la propria parte: l’icona Contatti solo i contatti, l’icona stessa di Erevos tutto Erevos. E Indietro nella prima schermata di Erevos ora lo mette in secondo piano, come Home, qualunque cosa lo abbia aperto. Vedi [Blocco con password](#lock).",
  // 4.0.0-rc.9
  "**Only the Contacts**: with Erevos locked, the Contacts icon, the widget's Contacts button and the notice of a birthday ask for the password, then open only the contacts. A chat, an SMS, Settings, and the orange padlock **Unlock everything**, ask for it again, then open all of Erevos. See [Password lock](#lock).":
    "**Solo i Contatti**: con Erevos bloccato, l’icona Contatti, il pulsante Contatti del widget e la notifica di un compleanno chiedono la password e poi aprono solo i contatti. Una chat, un SMS, le Impostazioni e il lucchetto arancione **Sblocca tutto** la chiedono di nuovo e poi aprono tutto Erevos. Vedi [Blocco con password](#lock).",
  "**Old private messages in Nostr chats**: Erevos also reads private messages sent the older way (NIP-04), which Damus, Primal and many apps still send and keep, past and new, in the same chats. The relays see who wrote such a message to whom; Erevos itself still sends only the NIP-17 way. See [Chats with other Nostr apps](#nostr-chats).":
    "**Vecchi messaggi privati nelle chat Nostr**: Erevos legge anche i messaggi privati mandati alla vecchia maniera (NIP-04), che Damus, Primal e molte app ancora mandano e tengono: passati e nuovi, nelle stesse chat. I relay vedono chi ha scritto un messaggio così a chi; Erevos stesso manda ancora solo alla maniera di NIP-17. Vedi [Chat con altre app Nostr](#nostr-chats).",
  "**Public posts in Nostr chats**: in a chat with one person, **Public posts** shows what they post for everyone, newest first, read only. It is looked up through Tor as the space says and not kept, and no pictures or links are opened. See [Chats with other Nostr apps](#nostr-chats).":
    "**Post pubblici nelle chat Nostr**: in una chat con una persona, **Post pubblici** mostra quello che pubblica per tutti, dal più recente, in sola lettura. Viene cercato tramite Tor come dice lo spazio e non viene conservato, e non vengono aperte immagini né link. Vedi [Chat con altre app Nostr](#nostr-chats).",
  // 4.0.0-rc.8
  // 4.0.0-rc.7
  "**Licence**: Settings → General → Licence says under which licence Erevos is free software, AGPL-3.0-or-later, its three additional terms, that it comes with no warranty, and who made it. See [Licence](#licence).":
    "**Licenza**: Impostazioni → Generali → Licenza dice con quale licenza Erevos è software libero, AGPL-3.0-or-later, le sue tre condizioni aggiuntive, che viene senza alcuna garanzia, e chi l’ha fatto. Vedi [Licenza](#licence).",
  "**Contact**: Settings → General → Contact adds the maker of Erevos as a contact, to write to in Erevos itself, end-to-end encrypted, with no phone number and no email. See [What Erevos is](#about).":
    "**Contatto**: Impostazioni → Generali → Contatto aggiunge l’autore di Erevos come contatto, per scrivergli nello stesso Erevos, con crittografia end-to-end, senza numero di telefono né email. Vedi [Che cos’è Erevos](#about).",
  "**A new sticker set, Angry Eyes**: 24 faces of big yellow eyes on a black disc, drawn by the maintainer, each with the moves he gave it.":
    "**Un nuovo set di adesivi, Angry Eyes**: 24 volti di grandi occhi gialli su un disco nero, disegnati dall’autore di Erevos, ciascuno con i movimenti che gli ha dato.",
  "**The calculator opens again**: in 4.0.0-rc.6 it closed as soon as it was tapped.":
    "**La calcolatrice si apre di nuovo**: nella 4.0.0-rc.6 si chiudeva appena la toccavi.",
  "**People you follow on Nostr are looked for on more relays**: **Show the people you follow** also asks relays that gather follow lists and more of the relays your key writes on, and waits longer for them; when it finds no one, it says why and how each relay answered. See [Chats with other Nostr apps](#nostr-chats).":
    "**Le persone che segui su Nostr sono cercate su più relay**: **Mostra le persone che segui** interroga anche relay che raccolgono le liste dei seguiti e più dei relay dove scrive la tua chiave, e li aspetta più a lungo; quando non trova nessuno, dice perché e come ha risposto ogni relay. Vedi [Chat con altre app Nostr](#nostr-chats).",
  // 4.0.0-rc.6
  "**Panic password**: with the password lock on, **Set the panic password** under the Panic button sets a password of its own that, typed on the lock screen, wipes Erevos as **Wipe everything now** does, while the screen shows **Wrong password**. Nothing shows whether one is set. See [Panic button](#panic).":
    "**Password di panico**: con il blocco con password attivo, **Imposta la password di panico** in «Pulsante di panico» imposta una password tutta sua che, scritta sulla schermata di blocco, cancella Erevos come fa **Cancella tutto ora**, mentre la schermata mostra **Password errata**. Niente mostra se ce n’è una impostata. Vedi [Pulsante di panico](#panic).",
  "**Calculator in place of Erevos**: on Android, under Launcher icons, a calculator that works can take the place of Erevos's icon; your code, then **=**, opens Erevos, which asks for its password as always. See [Appearance](#appearance).":
    "**Calcolatrice al posto di Erevos**: su Android, in «Icone del launcher», una calcolatrice che funziona può prendere il posto dell’icona di Erevos; il tuo codice, poi **=**, apre Erevos, che chiede la sua password come sempre. Vedi [Aspetto](#appearance).",
  "**Chat with myself on your linked devices too**: notes, photos, files, voice messages and reminders written on one device go to the others, as do a reminder changed or seen and a note deleted. Those from before go once, both ways. See [Linked devices](#devices).":
    "**Chat con me stesso anche sui tuoi dispositivi collegati**: note, foto, file, messaggi vocali e promemoria scritti su un dispositivo vanno agli altri, come un promemoria cambiato o visto e una nota eliminata. Quelli di prima vanno una volta, nei due sensi. Vedi [Dispositivi collegati](#devices).",
  "**Start when the phone turns on**: on Android, under In the background, Erevos can start by itself after the phone turns on, so the spaces set to say a message came while closed already say \"New message\", never which space or what. Off unless you choose it. See [Chat through a relay](#relay).":
    "**Avvia all’accensione del telefono**: su Android, in «In background», Erevos può avviarsi da solo dopo l’accensione del telefono, così gli spazi impostati per dire che è arrivato un messaggio mentre sono chiusi dicono già «New message», mai quale spazio o cosa. Disattivato se non lo scegli. Vedi [Chat tramite un relay](#relay).",
  "**Moving the clock no longer ends the wait after wrong passwords**: it goes by the phone's own time since it started, which no one can set; after a restart it starts again from its beginning. See [Password lock](#lock).":
    "**Spostare l’orologio non conclude più l’attesa dopo password sbagliate**: segue il tempo proprio del telefono da quando si è avviato, che nessuno può impostare; dopo un riavvio ricomincia dall’inizio. Vedi [Blocco con password](#lock).",
  "**People you follow on Nostr, found where your other app keeps them**: with a key brought from another Nostr app, **Show the people you follow** also looks on the relays your key writes on, and says so when no relay answered. See [Chats with other Nostr apps](#nostr-chats).":
    "**Le persone che segui su Nostr, trovate dove le tiene la tua altra app**: con una chiave portata da un’altra app Nostr, **Mostra le persone che segui** cerca anche sui relay dove scrive la tua chiave, e lo dice quando nessun relay ha risposto. Vedi [Chat con altre app Nostr](#nostr-chats).",
  "**Your Nostr name keeps the rest of your profile**: saving **Your name** changes only the name in your profile; a picture or words that another app of your key put there stay. Before, they could be wiped. See [Chats with other Nostr apps](#nostr-chats).":
    "**Il tuo nome Nostr tiene il resto del tuo profilo**: salvare **Il tuo nome** cambia solo il nome nel tuo profilo; una foto o delle parole che un’altra app della tua chiave ci ha messo restano. Prima potevano essere cancellate. Vedi [Chat con altre app Nostr](#nostr-chats).",
  "**Screens come down when no keyboard is open, in every case**: the home screen's list and buttons, or a chat, could still stay up as if a keyboard were open after it had gone. Now Erevos asks Android itself whether a keyboard is shown, and with none they come down within a second.":
    "**Le schermate scendono quando non c’è una tastiera aperta, in ogni caso**: l’elenco e i pulsanti della schermata iniziale, o una chat, potevano ancora restare in alto come se una tastiera fosse aperta, dopo che se n’era andata. Ora Erevos chiede ad Android stesso se una tastiera è mostrata, e senza tastiera scendono entro un secondo.",
  // 4.0.0-rc.5
  "**New chat opens hidden chats sooner**: hold **New chat** down for a moment, not a whole second, and the field for a PIN of hidden chats opens; on Android the phone buzzes once as it opens. See [Hidden chats](#hidden).":
    "**Nuova chat apre prima le chat nascoste**: tieni premuto **Nuova chat** per un attimo, non più un secondo intero, e si apre il campo per un PIN delle chat nascoste; su Android il telefono vibra una volta quando si apre. Vedi [Chat nascoste](#hidden).",
  "**People you follow on Nostr**: under New chat in Nostr chats, **Show the people you follow** lists the people your Nostr key follows, with their names; tap one to write to them. See [Chats with other Nostr apps](#nostr-chats).":
    "**Le persone che segui su Nostr**: nelle Chat Nostr, sotto Nuova chat, **Mostra le persone che segui** elenca le persone che la tua chiave Nostr segue, con i loro nomi; tocca una persona per scriverle. Vedi [Chat con altre app Nostr](#nostr-chats).",
  "**Who makes Erevos, and its licence**: About Erevos now names its maker, and every file of Erevos's source code says whose it is and under which licence; the AGPL-3.0 licence has three added terms (keep the maker's name, mark a changed version, give it another name). See [What Erevos is](#about).":
    "**Chi fa Erevos, e la sua licenza**: Informazioni su Erevos ora dice chi lo fa, e ogni file del codice sorgente dice di chi è e con quale licenza; la licenza AGPL-3.0 ha tre condizioni aggiuntive (mantenere il nome dell’autore, segnare una versione modificata come modificata, darle un altro nome). Vedi [Che cos’è Erevos](#about).",
  // 4.0.0-rc.4
  "**Numbers on the home chips**: each chip above the chats (All messages, SMS, Erevos, Matrix, XMPP, Nostr) shows how many messages are not read in it, as a small number after its name; muted chats and groups are not counted. See [Getting started](#start).":
    "**Numeri sui chip della schermata principale**: ogni chip sopra le chat (Tutti, SMS, Erevos, Matrix, XMPP, Nostr) mostra quanti messaggi non letti ci sono, con un piccolo numero dopo il suo nome; le chat e i gruppi in silenzio non contano. Vedi [Per iniziare](#start).",
  "**Open a photo full screen in Matrix, XMPP and Nostr chats**: tap a photo shown in a Matrix, XMPP or Nostr chat to see it on the whole screen, with zoom, turning with the phone and Save, as in a chat with a contact. See [Matrix](#matrix), [XMPP](#xmpp) and [Chats with other Nostr apps](#nostr-chats).":
    "**Foto a schermo intero nelle chat Matrix, XMPP e Nostr**: tocca una foto mostrata in una chat Matrix, XMPP o Nostr per vederla a tutto schermo, con zoom, rotazione con il telefono e Salva, come nella chat con un contatto. Vedi [Matrix](#matrix), [XMPP](#xmpp) e [Chat con altre app Nostr](#nostr-chats).",
  "**Who got and who read your messages in groups**: in a group that is not public, your messages show ✓, then ✓✓ once they reached the phone of every member, and ✓✓✓ once every one read them. Hold one and choose **Who read it** to see who read it and when, whose phone it reached and when, and who has neither yet. A member whose Erevos is older says nothing. A linked computer shows the same marks. See [Chat through a relay](#relay) and [Group chats](#groups).":
    "**Chi ha ricevuto e chi ha letto i tuoi messaggi nei gruppi**: in un gruppo che non è pubblico, i tuoi messaggi mostrano ✓, poi ✓✓ quando sono arrivati al telefono di ogni membro, e ✓✓✓ quando tutti li hanno letti. Tieni premuto uno e scegli **Chi l’ha letto** per vedere chi l’ha letto e quando, al telefono di chi è arrivato e quando, e chi non ha ancora fatto né l’una né l’altra cosa. Un membro con un Erevos più vecchio non dice nulla. Un computer collegato mostra gli stessi segni. Vedi [Chat tramite un relay](#relay) e [Chat di gruppo](#groups).",
  "**Who read your messages in Matrix**: your messages in a Matrix chat show ✓ once the Matrix server took them and ✓✓✓ once every other member read them, as their Matrix apps tell their servers; **Who read it**, on a message held down, lists who read it and when, and who has not. Matrix has no mark for a message that reached a phone, so there is no ✓✓. See [Matrix](#matrix).":
    "**Chi ha letto i tuoi messaggi in Matrix**: i tuoi messaggi in una chat Matrix mostrano ✓ quando il server Matrix li ha presi e ✓✓✓ quando tutti gli altri membri li hanno letti, come le loro app Matrix lo dicono ai loro server; **Chi l’ha letto**, su un messaggio tenuto premuto, elenca chi l’ha letto e quando, e chi no. Matrix non ha un segno per un messaggio arrivato a un telefono, quindi non c’è ✓✓. Vedi [Matrix](#matrix).",
  "**Quiet group messages for the marks**: the group message that says a message came or was read goes only to the senders concerned, and batched; after 300 such messages to some members only, the next goes to all, so no member falls behind in the phone's MLS keys (they accept a jump of 1000 at most). Groups let go of as their space closes send nothing more. See [Group chats](#groups).":
    "**Messaggi di gruppo silenziosi per i segni**: il messaggio di gruppo che dice che un messaggio è arrivato o è stato letto va solo ai mittenti interessati, e in blocco; dopo 300 di questi messaggi inviati solo ad alcuni membri, il successivo va a tutti, così nessun membro resta indietro nelle chiavi MLS del telefono (accettano un salto di 1000 al massimo). I gruppi lasciati andare quando si chiude il loro spazio non inviano più nulla. Vedi [Chat di gruppo](#groups).",
  // 4.0.0-rc.3
  "**Bold, italic, code and hidden words**: in chats and groups, words typed between * become bold, between _ italic, between ~ struck through, between ` code, and between || hidden behind a grey bar until tapped. See [Chat through a relay](#relay).":
    "**Grassetto, corsivo, codice e parole nascoste**: nelle chat e nei gruppi, le parole tra * diventano in grassetto, tra _ in corsivo, tra ~ barrate, tra ` codice, e tra || nascoste dietro una barra grigia finché non le tocchi. Vedi [Chat tramite un relay](#relay).",
  "**Hidden photo**: under + in a chat or a group, a photo that shows blurred until it is tapped. See [Chat through a relay](#relay).":
    "**Foto nascosta**: sotto + in una chat o in un gruppo, una foto che appare sfocata finché non la tocchi. Vedi [Chat tramite un relay](#relay).",
  "**Safety message**: under + in a chat, words to a contact that the relay sends by itself if you do not open Erevos for 6 hours to a week; each time you open it, they move on again. See [Chat through a relay](#relay).":
    "**Messaggio di sicurezza**: sotto + in una chat, parole per un contatto che il relay invia da solo se non apri Erevos per un periodo da 6 ore a una settimana; ogni volta che lo apri, slittano di nuovo. Vedi [Chat tramite un relay](#relay).",
  "**Name a member in a group with @**: type @ and pick a member; they are told of the message even if they muted the group. See [Group chats](#groups).":
    "**Nomina un membro in un gruppo con @**: scrivi @ e scegli un membro; viene avvisato del messaggio anche se ha silenziato il gruppo. Vedi [Chat di gruppo](#groups).",
  "**Reply, change, react and delete in XMPP chats**: hold a message in an XMPP chat or group to answer it, change your words, delete it for everyone or react with an emoji, as Conversations, Dino, Gajim, Monal and Kaidan do; and **typing…** shows while the other person writes. See [XMPP](#xmpp).":
    "**Rispondi, modifica, reagisci ed elimina nelle chat XMPP**: tieni premuto un messaggio in una chat o in un gruppo XMPP per rispondere, cambiare le tue parole, eliminarlo per tutti o reagire con un’emoji, come fanno Conversations, Dino, Gajim, Monal e Kaidan; e **sta scrivendo…** compare mentre l’altra persona scrive. Vedi [XMPP](#xmpp).",
  "**See who is writing in a Matrix chat**: **typing…** shows under a Matrix chat while someone writes in it, as the Matrix server says. It shows of you too only if you turn on **Say when I am writing** on the Matrix or XMPP screen: off at first, as it goes through the server not encrypted. See [Matrix](#matrix).":
    "**Vedi chi sta scrivendo in una chat Matrix**: **sta scrivendo…** compare sotto una chat Matrix mentre qualcuno ci scrive, come dice il server Matrix. Di te si vede solo se attivi **Dire quando scrivo** nella schermata Matrix o XMPP: spento all’inizio, perché passa dal server senza cifratura. Vedi [Matrix](#matrix).",
  "**Block someone on XMPP**: Block, at the bottom of an XMPP chat, keeps that person's messages, calls and requests from every app of your XMPP account; Unblock lets them through again. See [XMPP](#xmpp).":
    "**Blocca qualcuno su XMPP**: Blocca, in fondo a una chat XMPP, tiene messaggi, chiamate e richieste di quella persona lontani da ogni app del tuo account XMPP; Sblocca la fa passare di nuovo. Vedi [XMPP](#xmpp).",
  "**Voice messages in XMPP chats**: hold the microphone under an XMPP chat's message box to record, and let go to send; it goes encrypted as the chat is, as Conversations sends one. See [XMPP](#xmpp).":
    "**Messaggi vocali nelle chat XMPP**: tieni premuto il microfono sotto il campo del messaggio di una chat XMPP per registrare, e rilascia per inviare; parte cifrato come la chat, come lo invia Conversations. Vedi [XMPP](#xmpp).",
  "**Matrix groups from Erevos**: New group, on the Matrix screen, makes an encrypted group with a name and the people you invite; Join a group joins one by its address; Invite, in a group, asks someone else in; typing @ in a group names a member, who is told of it. See [Matrix](#matrix).":
    "**Gruppi Matrix da Erevos**: Nuovo gruppo, nella schermata di Matrix, crea un gruppo cifrato con un nome e le persone che inviti; Entra in un gruppo entra in uno con il suo indirizzo; Invita, in un gruppo, fa entrare qualcun altro; scrivere @ in un gruppo nomina un membro, che viene avvisato. Vedi [Matrix](#matrix).",
  "**The panic button on a computer and on Sailfish OS**: Settings → Privacy and security → Panic button now wipes Erevos there too, with its automatic backups if you choose; on a computer it then starts again as new. See [Panic button](#panic).":
    "**Il pulsante di panico su un computer e su Sailfish OS**: Impostazioni → Privacy e sicurezza → Pulsante di panico ora cancella Erevos anche lì, con i suoi backup automatici se lo scegli; su un computer poi riparte come nuovo. Vedi [Pulsante di panico](#panic).",
  "**Every chat opens at its latest message**: chats with contacts, groups and SMS, and the Matrix, XMPP and Nostr chats, all open at the last message with the message bar under it, and have round arrows to the start, to where you left off (the first message that was new when you opened it) and to the end. See [Getting started](#start).":
    "**Ogni chat si apre sul suo ultimo messaggio**: le chat con i contatti, i gruppi e gli SMS, e le chat Matrix, XMPP e Nostr si aprono tutte sull’ultimo messaggio con la barra dei messaggi sotto, e hanno frecce rotonde verso l’inizio, verso dove avevi lasciato (il primo messaggio che era nuovo all’apertura) e verso la fine. Vedi [Per iniziare](#start).",
  "**The panic button says when it refused**: when your panic app asked to wipe Erevos while the switch was off, or signed with another key, the panic screen now says so, with the time. An app that moves to a new key the way Android allows stays trusted; otherwise you can trust it again as it is now. See [Panic button](#panic).":
    "**Il pulsante di panico dice quando ha rifiutato**: quando la tua app di panico ha chiesto di cancellare Erevos con l’interruttore spento, o firmata con un’altra chiave, la schermata del pulsante di panico ora lo dice, con l’ora. Un’app che passa a una nuova chiave nel modo che Android permette resta fidata; altrimenti puoi fidarti di nuovo così com’è ora. Vedi [Pulsante di panico](#panic).",
  "**The home screen's chips stay on one line**: with a Nostr, Matrix or XMPP chip as well, **Names** went to a line of its own and the chips moved. Now they stay on one line that slides to the side, and the chosen one is always in sight.":
    "**I chip della schermata principale restano su una riga**: con in più un chip Nostr, Matrix o XMPP, **Nomi** andava su una riga a parte e i chip si spostavano. Ora restano su una sola riga che scorre di lato, e quello scelto è sempre in vista.",
  "**Screens come down when the keyboard is gone**: back from another app that had its keyboard open, the home screen's buttons (or a chat's field) could stay up where the keyboard had been, until a keyboard opened again. Now they come down within a second.":
    "**Le schermate scendono quando la tastiera se ne va**: tornando da un’altra app con la tastiera aperta, i pulsanti della schermata iniziale (o il campo di una chat) potevano restare in alto, dov’era la tastiera, finché non si riapriva una tastiera. Ora scendono entro un secondo.",
  // 4.0.0-rc.2
  "**See what you type in a password or a PIN**: every field for a password, a PIN or a token has an eye at its end: tap it to see what you type, and again to hide it. It is hidden again the next time. See [Password lock](#lock).":
    "**Guarda ciò che scrivi in una password o un PIN**: ogni campo per una password, un PIN o un token ha un occhio in fondo: toccalo per vedere ciò che scrivi, e di nuovo per nasconderlo. La volta dopo è di nuovo nascosto. Vedi [Blocco con password](#lock).",
  "**A chat read as it opens stays read**: messages read while their chat was still opening, as Erevos ended a look at the relay, showed as unread on the home screen once you went back. Now they are marked read as soon as they show.":
    "**Una chat letta mentre si apre resta letta**: i messaggi letti mentre la loro chat si stava ancora aprendo, mentre Erevos finiva di guardare sul relay, risultavano non letti nella schermata principale appena tornavi indietro. Ora sono segnati come letti appena si vedono.",
  "**Link for a website**: under New chat → Your contact link, a link to put on a web page, such as your contact page. It opens a page that offers Erevos to whoever has none yet, then adds you; what they send comes as a message request. See [Chat through a relay](#relay).":
    "**Link per un sito web**: in Nuova chat → Il tuo link di contatto, un link da mettere su una pagina web, come la tua pagina dei contatti. Apre una pagina che offre Erevos a chi non ce l’ha ancora, poi ti aggiunge; ciò che invia arriva come richiesta di messaggio. Vedi [Chat tramite un relay](#relay).",
  "**An update's download that stalls is tried again**: when the connection brings nothing for a while, Erevos starts the download again by itself, three times in all, and then says so in its own words. See [Updates](#updates).":
    "**Il download di un aggiornamento che si blocca viene ritentato**: quando la connessione non porta nulla per un po’, Erevos riparte da solo con il download, tre volte in tutto, e poi lo dice con parole sue. Vedi [Aggiornamenti](#updates).",
  // 4.0.0-rc.1
  "**Pieces of photos through Nostr stay with their chats**: while a photo that comes through Nostr waits for the rest of its pieces, they are now kept encrypted with the space or the hidden chats they came for, no longer apart where they could be counted, so nothing outside a hidden chats' password says that a photo is on its way to them. Pieces kept before go to the first chats whose photo they are, or after four days. See [Through Nostr](#nostr).":
    "**I pezzi delle foto tramite Nostr restano con le loro chat**: mentre una foto che arriva tramite Nostr aspetta il resto dei suoi pezzi, questi sono ora tenuti cifrati con lo spazio o le chat nascoste per cui sono arrivati, non più a parte, dove si potevano contare, così niente fuori dalla password di chat nascoste dice che una foto sta arrivando a loro. I pezzi tenuti prima vanno alle prime chat di cui sono la foto, o se ne vanno dopo quattro giorni. Vedi [Tramite Nostr](#nostr).",
  "**Encrypted SMS when nothing else works, if you choose**: on Android, when the relay, Nostr, the phones nearby and LoRa all fail, a text to an Erevos contact whose number is linked can go by SMS, end-to-end encrypted, hidden from their SMS app. Off until you turn it on, for all such contacts under Settings → Phone and SMS → SMS, or for one in a chat's Details. It costs SMS (3 for a short text, up to 10 for a longer one), and the phone company sees who wrote to whom, and when. Both phones need Erevos as the SMS app. See [SMS](#sms).":
    "**SMS crittografati quando nient’altro funziona, se lo scegli**: su Android, quando relay, Nostr, i telefoni vicini e LoRa falliscono tutti, un testo a un contatto Erevos con numero collegato può andare via SMS, crittografato end-to-end e nascosto alla sua app per gli SMS. Disattivato finché non lo attivi, per tutti questi contatti in Impostazioni → Telefono e SMS → SMS, o per uno nei Dettagli di una chat. Costa SMS (3 per un testo breve, fino a 10 per uno più lungo), e l’operatore vede chi ha scritto a chi, e quando. Entrambi i telefoni hanno bisogno di Erevos come app per gli SMS. Vedi [SMS](#sms).",
  "**Answer a hidden call with Answer**: on the \"Incoming call\" screen with no name that a call to your hidden chats brings, **Answer** now asks for the PIN, as the small sign does, and the right PIN answers the call; before, it could not connect, and only the small sign could. See [Hidden chats](#hidden).":
    "**Rispondere a una chiamata nascosta con Rispondi**: sulla schermata «Chiamata in arrivo» senza nome che porta una chiamata alle tue chat nascoste, **Rispondi** ora chiede il PIN, come il piccolo segno, e il PIN giusto risponde alla chiamata; prima non poteva collegare, e solo il piccolo segno poteva. Vedi [Chat nascoste](#hidden).",
  "**Spam SMS come quietly**: on Android, an SMS that the spam filter's own words catch, a link with words that try to fool from a number that is no contact and that you never answered, still goes to Spam but no longer shows a notice or makes a sound. Spam by your own words and rules still shows one, as they stay encrypted in the space; with the Spam filter off, every SMS does. See [SMS](#sms).":
    "**Gli SMS di spam arrivano in silenzio**: su Android, un SMS che le parole proprie del filtro antispam colgono, un link con parole che cercano di ingannare da un numero che non è un contatto e a cui non hai mai risposto, va ancora in Spam ma non mostra più una notifica né suona. Lo spam per le tue parole e regole ne mostra ancora una, perché restano cifrate nello spazio; con il Filtro antispam spento, ogni SMS la mostra. Vedi [SMS](#sms).",
  '**What\'s new in two parts**: each version says first what changes for you, then what changed under the hood: fixes, speed, battery and security inside. See [Updates](#updates).':
    '**Le novità in due parti**: ogni versione dice prima cosa cambia per te, poi cosa è cambiato sotto il cofano: correzioni, velocità, batteria e sicurezza all’interno. Vedi [Aggiornamenti](#updates).',
  '**A contact\'s SMS no longer stay counted as new**: opening their chat reads all of them, the earlier ones too, not only those that show.':
    '**Gli SMS di un contatto non restano più contati come nuovi**: aprire la sua chat li legge tutti, anche i precedenti, non solo quelli visibili.',
  '**A message no longer waits when Tor cannot reach the relay**: with Tor for messages, it goes straight at once, as the Tor settings say. See [Through Tor](#tor).':
    '**Un messaggio non resta più in attesa quando Tor non raggiunge il relay**: con Tor per i messaggi, parte subito in diretta, come dicono le impostazioni di Tor. Vedi [Tramite Tor](#tor).',
  '**Background notices no longer stop after a network change**: when the connection of a wait at the relay died on the way (Wi-Fi to mobile data, the relay restarting), Erevos took the relay for one from before, which cannot wait, for the whole run: contacts\' messages then came up to ten minutes late, and hidden chats, closed spaces and hidden rings said nothing until Erevos was restarted. See [Chat through a relay](#relay).':
    '**Gli avvisi in background non si fermano più dopo un cambio di rete**: quando la connessione di un’attesa al relay moriva per strada (da Wi-Fi a dati mobili, riavvio del relay), Erevos prendeva il relay per uno vecchio, che non sa aspettare, per tutta l’esecuzione: i messaggi dei contatti arrivavano fino a dieci minuti dopo, e le chat nascoste, gli spazi chiusi e gli squilli nascosti non dicevano nulla fino al riavvio di Erevos. Vedi [Chat tramite un relay](#relay).',
  '**A call hung up at once no longer rings**: when the hang-up came in the same look as the call, the phone rang 45 seconds for a call nobody was on; the same for a group call its starter left at once. See [Chat through a relay](#relay).':
    '**Una chiamata chiusa subito non squilla più**: quando la chiusura arrivava nello stesso sguardo della chiamata, il telefono squillava 45 secondi per una chiamata in cui non c’era nessuno; lo stesso per una chiamata di gruppo che chi l’ha avviata ha lasciato subito. Vedi [Chat tramite un relay](#relay).',
  '**A hidden call rings once**: a place with Receive while closed and a ring queue rang twice for one call, and a call taken while hidden chats were open rang again as they closed. See [Hidden chats](#hidden).':
    '**Una chiamata nascosta squilla una volta**: un posto con Ricevere da chiuse e una coda di squillo squillava due volte per una chiamata, e una chiamata presa mentre le chat nascoste erano aperte squillava di nuovo alla loro chiusura. Vedi [Chat nascoste](#hidden).',
  '**A member\'s contact link no longer says New message**: the answer to an ask from a group only adds the contact, with no notice. See [Group chats](#groups).':
    '**Il link di contatto di un membro non dice più Nuovo messaggio**: la risposta a una richiesta da un gruppo aggiunge solo il contatto, senza avviso. Vedi [Chat di gruppo](#groups).',
  '**The birthday notice and the phone\'s incoming call no longer replace each other**: they had the same notice number. See [Contacts](#contacts).':
    '**L’avviso di compleanno e la chiamata in arrivo del telefono non si sostituiscono più**: avevano lo stesso numero di avviso. Vedi [Contatti](#contacts).',
  '**A closed space tells of its contacts\' messages too**: since each contact writes to a queue of their own, a space that says a message came while another is open told only of group messages and first messages from new contacts. It now asks about its contacts\' queues too, up to 64. See [Chat through a relay](#relay).':
    '**Uno spazio chiuso avvisa anche dei messaggi dei suoi contatti**: poiché ogni contatto scrive in una coda tutta sua, uno spazio che avvisa che è arrivato un messaggio mentre ne è aperto un altro avvisava solo dei messaggi dei gruppi e dei primi messaggi dei nuovi contatti. Ora chiede anche delle code dei suoi contatti, fino a 64. Vedi [Chat tramite un relay](#relay).',
  '**The user guide is in every language of the app**: it shows in the one you chose, and names the buttons as the app shows them. See [Language](#start).':
    '**La guida è in tutte le lingue dell’app**: appare in quella che hai scelto e chiama i pulsanti come li mostra l’app. Vedi [Lingua](#start).',
  '**Location finds where you are, indoors too**: the phone looks by satellite and by its network at once, a sheet says it is looking, and when nothing is found it says why, with Try again. See [Chat through a relay](#relay).':
    '**Posizione trova dove ti trovi, anche al chiuso**: il telefono cerca via satellite e con la sua rete insieme, un foglio dice che sta cercando, e se non trova niente dice perché, con Riprova. Vedi [Chat tramite un relay](#relay).',
  '**The web app\'s icon counts what is not read**: on an iPhone, with notifications on for the space, Erevos\'s icon on the home screen shows how many messages are not read, never a hidden chat\'s, unless turned off under Settings → Notifications → Number on the icon. See [On an iPhone](#iphone).':
    '**L\'icona della web app conta i non letti**: su un iPhone, con le notifiche attive per lo spazio, l\'icona di Erevos nella schermata Home mostra quanti messaggi non sono letti, mai quelli di una chat nascosta, a meno che tu non lo spenga in Impostazioni → Notifiche → Numero sull\'icona. Vedi [Su un iPhone](#iphone).',
  "**Notifications for each chat**: on Android, mute a chat or a group for 8 hours, a week or always, and give its messages and its calls a sound of their own, or none. See [Chat through a relay](#relay).":
    "**Notifiche per ogni chat**: su Android, metti in silenzio una chat o un gruppo per 8 ore, una settimana o sempre, e dai ai suoi messaggi e alle sue chiamate un suono proprio, o nessuno. Vedi [Chat tramite un relay](#relay).",
  "**A chat locked with its own PIN stays locked**: when its contact's Erevos started a new conversation, as it does about once a month, the chat lost its PIN, and a public group joined again lost its own. See [Hidden chats](#hidden).":
    "**Una chat bloccata con un PIN suo resta bloccata**: quando l’Erevos del contatto iniziava una nuova conversazione, come fa circa una volta al mese, la chat perdeva il suo PIN, e un gruppo pubblico in cui sei rientrato perdeva il suo. Vedi [Chat nascoste](#hidden).",
  "**Erevos's icon keeps the number of messages not read, on Android**: leaving Erevos with messages not read, a notice without sound keeps how many until you read them, and the launcher shows it on the icon, as a number or a dot. Settings → Notifications → Number on the icon turns it off. See [Chat through a relay](#relay).":
    "**L'icona di Erevos tiene il numero dei messaggi non letti, su Android**: uscendo da Erevos con messaggi non letti, una notifica senza suono tiene quanti sono finché non li leggi, e il launcher la mostra sull'icona, come numero o punto. Impostazioni → Notifiche → Numero sull'icona lo disattiva. Vedi [Chat tramite un relay](#relay).",
  "**The web app's notifications, more dependable**: no New message over Erevos while it is open, and a push held back while the phone was offline no longer counts messages you already read (both with your relay updated), every notice sounds in Chrome, Firefox and Edge, they come back by themselves when the browser changes its push address, and Notifications while closed says when the browser blocks them or your relay was not told yet that they are off. See [On an iPhone](#iphone).":
    "**Le notifiche della web app, più affidabili**: nessun «Nuovo messaggio» sopra Erevos mentre è aperto, e un push trattenuto mentre il telefono era offline non conta più i messaggi che hai già letto (entrambi con il tuo relay aggiornato), ogni avviso fa un suono in Chrome, Firefox ed Edge, tornano da sole quando il browser cambia il suo indirizzo push, e «Notifiche ad app chiusa» dice quando il browser le blocca o quando al tuo relay non è ancora stato detto che sono disattivate. Vedi [Su un iPhone](#iphone).",
  "**Calls ring in the web app, on the computer and on Sailfish OS**: a call that comes while Erevos is open now rings, where only its screen showed, and vibrates where the phone can. On an iPhone it rings once you have touched Erevos, and not on silent. See [On an iPhone](#iphone).":
    "**Le chiamate squillano nella web app, sul computer e su Sailfish OS**: una chiamata che arriva mentre Erevos è aperto ora squilla, dove prima si vedeva solo la sua schermata, e vibra dove il telefono può. Su un iPhone squilla dopo che hai toccato Erevos, e non in silenzioso. Vedi [Su un iPhone](#iphone).",
  '**Erevos on a computer keeps running with its window closed**: in the system tray (on a Mac, in the Dock) it goes on receiving, a call rings and brings the window back, and a notification says how many messages are not read, never who or what. Turn it off under Settings → Notifications → In the background. See [On a computer](#desktop).':
    '**Erevos sul computer continua a funzionare con la finestra chiusa**: nell’area di notifica (su un Mac, nel Dock) continua a ricevere, una chiamata squilla e riporta la finestra, e una notifica dice quanti messaggi non sono letti, mai chi né cosa. Si disattiva in Impostazioni → Notifiche → In background. Vedi [Su un computer](#desktop).',
  "**Erevos on Sailfish OS tells of messages and calls while it is closed**: while it is out of sight or closed, a small helper waits at the relay for the open space, a notification says how many messages came, never who or what, and a call rings with the phone's ringtone. See [On Sailfish OS](#sailfish).":
    "**Erevos su Sailfish OS avvisa di messaggi e chiamate mentre è chiuso**: mentre non si vede o è chiuso, un piccolo aiutante aspetta sul relay per lo spazio aperto, una notifica dice quanti messaggi sono arrivati, mai da chi né cosa, e una chiamata suona con la suoneria del telefono. Vedi [Su Sailfish OS](#sailfish).",
  "**The relay's pushes to the web app, sturdier**: a push the push service could not take just then is sent again, a call goes before the messages waiting their turn, and whoever runs the relay can allow another push service. Your relay needs an update for it.":
    "**I push del relay alla web app, più solidi**: un push che il servizio push non ha potuto accettare in quel momento viene inviato di nuovo, una chiamata passa prima dei messaggi che aspettano il loro turno, e chi gestisce il relay può consentire un altro servizio push. Il tuo relay deve essere aggiornato per questo.",
  "**Permissions checks every notice Erevos uses**: on Android, the message notice without sound or with a chat's own sound, and the reminders', turned off, now show there, with a button to each. See [Chat through a relay](#relay).":
    '**Autorizzazioni controlla ogni notifica che Erevos usa**: su Android, la notifica dei messaggi senza suono o con il suono proprio di una chat, e quella dei promemoria, se disattivate, ora appaiono lì, con un pulsante per ciascuna. Vedi [Chat tramite un relay](#relay).',
  '**Hidden chats say what their switches need**: Say when a message comes and Ring calls when closed say so when Settings → Notifications → In the background lets them do nothing. See [Hidden chats](#hidden).':
    '**Le chat nascoste dicono di che cosa hanno bisogno i loro interruttori**: Avvisa quando arriva un messaggio e Fai squillare le chiamate quando sono chiuse lo dicono quando Impostazioni → Notifiche → In background non permette loro di fare nulla. Vedi [Chat nascoste](#hidden).',
  "**Truer words about notices**: Settings and the guide give the notices' own words and say what each one needs. See [Chat through a relay](#relay).":
    '**Parole più fedeli sulle notifiche**: le Impostazioni e la guida riportano le parole stesse delle notifiche e dicono di che cosa ha bisogno ciascuna. Vedi [Chat tramite un relay](#relay).',
  "**Calls ring as they should**: with Do Not Disturb only when their notice may break through, with a phone's clock off too once the relay is updated, and to the end on Android 7 and 8; a second call is told busy, and a ring stops only for its own call. See [Chat through a relay](#relay).":
    '**Le chiamate squillano come devono**: con Non disturbare solo quando la loro notifica può passare, anche con l’orologio di un telefono sballato una volta aggiornato il relay, e fino alla fine su Android 7 e 8; a una seconda chiamata viene detto occupato, e uno squillo si ferma solo per la sua chiamata. Vedi [Chat tramite un relay](#relay).',
  '**Hidden calls**: one turned down no longer leaves Erevos over the lock screen, one that comes while the password screen shows comes over it, and none rings twice. See [Hidden chats](#hidden).':
    '**Chiamate nascoste**: una rifiutata non lascia più Erevos sopra la schermata di blocco, una che arriva mentre è visibile la schermata della password appare sopra di essa, e nessuna squilla due volte. Vedi [Chat nascoste](#hidden).',
  '**Notices come again at once after a change of network**, and receiving starts again as Erevos shows when Android refused it. See [Chat through a relay](#relay).':
    '**Le notifiche tornano subito dopo un cambio di rete**, e la ricezione riparte appena Erevos è visibile quando Android l’aveva rifiutata. Vedi [Chat tramite un relay](#relay).',
  "**Hidden chats' notices tell each message once**: what came since a place last looked is told as it closes, a call that rang is not told again as a message, and a place whose queue the relay lost keeps its switch on. See [Hidden chats](#hidden).":
    '**Le notifiche delle chat nascoste annunciano ogni messaggio una volta**: quello che è arrivato dall’ultima volta che un posto ha guardato viene annunciato quando si chiude, una chiamata che ha squillato non viene annunciata di nuovo come messaggio, e un posto la cui coda è stata persa dal relay tiene attivo il suo interruttore. Vedi [Chat nascoste](#hidden).',
  '**Hidden chats close while Erevos is away**, after 30 seconds, so a call to them meanwhile rings with their PIN to answer. See [Hidden chats](#hidden).':
    '**Le chat nascoste si chiudono mentre Erevos è in background**, dopo 30 secondi, così una chiamata per loro nel frattempo squilla con il loro PIN per rispondere. Vedi [Chat nascoste](#hidden).',
  '**A voice message counts once**, on its last part, also when it goes again whole.':
    '**Un messaggio vocale conta una volta**, sulla sua ultima parte, anche quando viene inviato di nuovo per intero.',
  '**The number on the icon counts only what is still there**: a message deleted for everyone, or read on a linked computer, no longer counts. See [Chat through a relay](#relay).':
    '**Il numero sull’icona conta solo quello che c’è ancora**: un messaggio eliminato per tutti, o letto su un computer collegato, non conta più. Vedi [Chat tramite un relay](#relay).',
  '**Messages sent for later** tell of themselves only while their space is open, without sound if sent so.':
    '**I messaggi programmati** avvisano di sé solo mentre il loro spazio è aperto, senza suono se inviati così.',
  '**SMS**: one to the chat on screen only sounds there, they are marked read only while their screen shows, and Android names their notices SMS. See [SMS](#sms).':
    '**SMS**: uno per la chat sullo schermo suona solo lì, vengono segnati come letti solo mentre la loro schermata è visibile, e Android chiama le loro notifiche SMS. Vedi [SMS](#sms).',
  "**Reminders**: one seen in Chat with myself goes from the notice, a hidden place's go with a new PIN, and birthdays come at 9:00. See [Getting started](#start).":
    '**Promemoria**: uno visto nella Chat con me stesso se ne va dalla notifica, quelli di un posto nascosto se ne vanno con un nuovo PIN, e i compleanni arrivano alle 9:00. Vedi [Per iniziare](#start).',
  '**Nostr reads as soon as Tor is ready.** See [Through Nostr](#nostr).':
    '**Nostr legge appena Tor è pronto.** Vedi [Tramite Nostr](#nostr).',
  "**Erevos's notices show its mark** in the status bar.":
    '**Le notifiche di Erevos mostrano il suo simbolo** nella barra di stato.',
  '**Notices are asked for with receiving off too**, when Say a message came is on.':
    '**Le notifiche vengono chieste anche con la ricezione disattivata**, quando Avvisa dei nuovi messaggi è attivo.',
  "**Photos open on the whole screen**: tap one to see it edge to edge, zoom in with two fingers or a double tap, and tap again to hide or show what is around it; big photos open as small ones do. Erevos also turns with the phone while the phone's Auto-rotate is on, and a photo shown on its own even when it is off. See [Chat through a relay](#relay).":
    '**Le foto si aprono a tutto schermo**: tocca una foto per vederla da bordo a bordo, ingrandisci con due dita o un doppio tocco, e tocca di nuovo per nascondere o mostrare ciò che ha intorno; le foto grandi si aprono come quelle piccole. Erevos ruota anche con il telefono finché la sua Rotazione automatica è attiva, e una foto mostrata da sola anche quando è disattivata. Vedi [Chat tramite un relay](#relay).',
  "**Matrix accounts in Erevos**: sign a space in to Matrix and chat with people who use Element or another Matrix app, end-to-end encrypted, under Settings → Relay and networks → Matrix. These chats are not anonymous, and say so: the Matrix server sees who talks with whom. Text, photos and files. See [Matrix](#matrix).":
    "**Account Matrix in Erevos**: fai accedere uno spazio a Matrix e chatta con persone che usano Element o un’altra app Matrix, con cifratura end-to-end, in Impostazioni → Relay e reti → Matrix. Queste chat non sono anonime, e lo dicono: il server Matrix vede chi parla con chi. Testo, foto e file. Vedi [Matrix](#matrix).",
  "**Every network's chats on the home screen**: once you sign in to Matrix, its chats are in the list with the Erevos chats and the SMS, newest first, each marked Matrix, and the Matrix chip shows them alone, as SMS and Erevos do. See [Matrix](#matrix).":
    "**Le chat di ogni rete nella schermata principale**: una volta che hai fatto l’accesso a Matrix, le sue chat sono nell’elenco con le chat Erevos e gli SMS, le più recenti prima, ognuna segnata Matrix, e il chip Matrix mostra solo loro, come SMS ed Erevos. Vedi [Matrix](#matrix).",
  '**Test versions before a release**: Erevos reads a version such as 4.0.0-rc.1, a test version that comes before 4.0.0, when it looks for updates, tells of a new version and shows what is new. See [Updates](#updates).':
    '**Versioni di prova prima di una versione**: Erevos legge una versione come 4.0.0-rc.1, una versione di prova che viene prima della 4.0.0, quando cerca aggiornamenti, avvisa di una nuova versione e mostra le novità. Vedi [Aggiornamenti](#updates).',
  "**Check Matrix devices by emoji**: in a chat with one person on Matrix, Check by emoji shows you both seven pictures; if they match, nobody sits in between, and Element sees the check too. Check this device with another of yours makes your own Element trust Erevos. See [Matrix](#matrix).":
    "**Verifica i dispositivi Matrix con le emoji**: in una chat con una persona su Matrix, Verifica con le emoji mostra a entrambi sette immagini; se corrispondono, nessuno sta in mezzo, e anche Element vede la verifica. Verifica questo dispositivo con un altro tuo fa sì che il tuo Element si fidi di Erevos. Vedi [Matrix](#matrix).",
  "**Automatic backups to your own server too**: on Android, each automatic backup can also go to a folder on a server you choose, such as your Nextcloud, over WebDAV. Off until you add one. The server gets random bytes under a random name and cannot open them; it still sees your account, your address and when. See [Backups](#backup).":
    "**Backup automatici anche sul tuo server**: su Android, ogni backup automatico può andare anche in una cartella su un server che scegli tu, come il tuo Nextcloud, via WebDAV. Disattivato finché non ne aggiungi uno. Il server riceve byte casuali con un nome casuale e non può aprirli; vede comunque il tuo account, il tuo indirizzo e quando. Vedi [Backup](#backup).",
  "**Matrix Security Key and key backup**: enter the Security Key Element made, under Settings → Relay and networks → Matrix, and earlier messages open, new keys are backed up, and your other devices trust Erevos. An account with none can set one up there. See [Matrix](#matrix).":
    "**Chiave di sicurezza e backup delle chiavi Matrix**: inserisci la chiave di sicurezza creata da Element, in Impostazioni → Relay e reti → Matrix, e i messaggi precedenti si aprono, le nuove chiavi vanno nel backup, e gli altri tuoi dispositivi si fidano di Erevos. Un account senza può crearne una lì. Vedi [Matrix](#matrix).",
  "**Matrix through Tor**: on Android, a space's Matrix account follows its choice under Settings → Relay and networks → Tor, so the Matrix server no longer sees where you are; the Matrix screen says when it goes through Tor. See [Matrix](#matrix).":
    "**Matrix tramite Tor**: su Android, l’account Matrix di uno spazio segue la sua scelta in Impostazioni → Relay e reti → Tor, così il server Matrix non vede più dove sei; la schermata di Matrix dice quando passa da Tor. Vedi [Matrix](#matrix).",
  "**XMPP accounts in Erevos**: sign a space in to XMPP, under Settings → Relay and networks → XMPP, and chat with people who use Conversations, Monal, Gajim, Dino or another XMPP app, encrypted with OMEMO. These chats are not anonymous, and say so: the XMPP server sees who talks with whom. Text with delivery and read marks, photos and files, in the home list under an XMPP chip of its own, and through Tor on Android as you chose. See [XMPP](#xmpp).":
    "**Account XMPP in Erevos**: fai accedere uno spazio a XMPP, in Impostazioni → Relay e reti → XMPP, e chatta con persone che usano Conversations, Monal, Gajim, Dino o un’altra app XMPP, cifrato con OMEMO. Queste chat non sono anonime, e lo dicono: il server XMPP vede chi parla con chi. Testo con segni di consegna e di lettura, foto e file, nell’elenco della schermata iniziale sotto un chip XMPP a parte, e tramite Tor su Android come hai scelto. Vedi [XMPP](#xmpp).",
  "**Voice and video calls with people on XMPP**: the two tiles at the top of an XMPP chat call the person, and their calls ring on the same screen as Erevos's own, with apps that call as Conversations does. The call goes through your call relay or the XMPP server's, so they do not learn your address; the key that proves it passes through the XMPP servers, which could put themselves in between. See [XMPP](#xmpp).":
    "**Chiamate vocali e video con persone su XMPP**: i due riquadri in alto in una chat XMPP chiamano la persona, e le sue chiamate squillano sulla stessa schermata di quelle di Erevos, con le app che chiamano come Conversations. La chiamata passa per il tuo relay per le chiamate o quello del server XMPP, così non conosce il tuo indirizzo; la chiave che la prova passa per i server XMPP, che potrebbero mettersi in mezzo. Vedi [XMPP](#xmpp).",
  "**Voice and video calls with people on Matrix**: on Android, the two tiles at the top of a Matrix chat call with Element Call, the call app of Element and Element X, which opens inside Erevos in a window of its own, and their calls ring here as Erevos's own do. Sound and picture are end-to-end encrypted and go through the media server your Matrix server names, never through Tor. See [Matrix](#matrix).":
    "**Chiamate vocali e video con persone su Matrix**: su Android, i due riquadri in alto in una chat Matrix chiamano con Element Call, l’app di chiamata di Element ed Element X, che si apre dentro Erevos in una finestra sua, e le loro chiamate squillano qui come quelle di Erevos. Suono e immagine sono cifrati end-to-end e passano per il server multimediale indicato dal tuo server Matrix, mai per Tor. Vedi [Matrix](#matrix).",
  "**Voice and video calls with people on Matrix, in the web app and on a computer**: the two tiles at the top of a Matrix chat call with Element Call there too, as on Android, over the app; its back arrow makes it small in a corner, so you can keep using Erevos during the call. Element Call runs apart from Erevos and can read nothing of it. See [Matrix](#matrix).":
    "**Chiamate vocali e video con persone su Matrix, nella web app e su un computer**: i due riquadri in alto in una chat Matrix chiamano con Element Call anche lì, come su Android, sopra l’app; la freccia indietro della sua finestra la rimpicciolisce in un angolo, così puoi continuare a usare Erevos durante la chiamata. Element Call gira separato da Erevos e non può leggerne nulla. Vedi [Matrix](#matrix).",
  "**Chats with people on other Nostr apps**: give a space a Nostr key of its own, under Settings → Relay and networks → Nostr chats, and chat with people who use Damus, Amethyst, Primal, 0xchat or another Nostr app, one to one or in groups, encrypted as NIP-17 asks: the relays see whom a message is for, not who wrote it. These chats are not anonymous, and say so: your key is the same to everyone you write to. Text, photos, files and reactions, in the home list under a Nostr chip of its own, and through Tor on Android as you chose. See [Chats with other Nostr apps](#nostr-chats).":
    "**Chat con persone su altre app Nostr**: dai a uno spazio una chiave Nostr tutta sua, in Impostazioni → Relay e reti → Chat Nostr, e chatta con persone che usano Damus, Amethyst, Primal, 0xchat o un’altra app Nostr, a tu per tu o in gruppo, cifrato come chiede NIP-17: i relay vedono a chi è destinato un messaggio, non chi l’ha scritto. Queste chat non sono anonime, e lo dicono: la tua chiave è la stessa per tutti quelli a cui scrivi. Testo, foto, file e reazioni, nella lista della home sotto un pulsante Nostr tutto suo, e tramite Tor su Android come hai scelto. Vedi [Chat con altre app Nostr](#nostr-chats).",
  "**Notices for Matrix, XMPP and Nostr messages**: a message in a chat on Matrix, XMPP or Nostr shows a notice and counts in the number on Erevos's icon, as in Erevos's own chats. On Android, Notifications at the bottom of such a chat mutes it or gives it a sound of its own, and an XMPP or Matrix call rings with its chat's ringtone. See [Matrix](#matrix), [XMPP](#xmpp) and [Chats with other Nostr apps](#nostr-chats).":
    "**Avvisi per i messaggi Matrix, XMPP e Nostr**: un messaggio in una chat Matrix, XMPP o Nostr mostra un avviso e conta nel numero sull’icona di Erevos, come nelle chat di Erevos stesso. Su Android, Notifiche, in fondo a una chat così, la silenzia o le dà un suono suo, e una chiamata XMPP o Matrix squilla con la suoneria della sua chat. Vedi [Matrix](#matrix), [XMPP](#xmpp) e [Chat con altre app Nostr](#nostr-chats).",
  "**A closed space tells of Matrix messages**: on Android, Say a message came under While this space is closed, on the Matrix screen, has a closed space say \"New message\" when something comes on Matrix while another space is open, never what, from whom or in which chat. Off until you choose it. The Matrix server then tells the space's relay of each message, with no words in it: it learns the relay's address, and the relay when messages come. See [Matrix](#matrix).":
    "**Uno spazio chiuso avvisa dei messaggi Matrix**: su Android, «Avvisa dei nuovi messaggi» sotto «Mentre questo spazio è chiuso», nella schermata di Matrix, fa dire «Nuovo messaggio» a uno spazio chiuso quando arriva qualcosa su Matrix mentre un altro spazio è aperto, mai cosa, da chi o in quale chat. Spento finché non lo scegli. Il server Matrix avvisa allora il relay dello spazio di ogni messaggio, senza nessuna sua parola: impara l’indirizzo del relay, e il relay quando arrivano messaggi. Vedi [Matrix](#matrix).",
  "**Made with others' open source**: About Erevos, and the guide, now name the open-source projects Erevos is built on, with their makers and their licences. See [What Erevos is](#about).":
    "**Fatto con l’open source degli altri**: In Informazioni su Erevos e nella guida compaiono ora i progetti open source su cui è costruito Erevos, con i loro autori e le loro licenze. Vedi [Che cos’è Erevos](#about).",
  "**Groups on XMPP**: under Settings → Relay and networks → XMPP, make a private group with your contacts, encrypted with OMEMO for every member as Conversations' private groups are, or join a group by its address, and answer invitations to groups. A group that is not private, a channel, is not encrypted, and says so. Your groups follow your account's other XMPP apps, and a channel tells only of messages that name you. See [XMPP](#xmpp).":
    "**Gruppi su XMPP**: in Impostazioni → Relay e reti → XMPP, crea un gruppo privato con i tuoi contatti, cifrato con OMEMO per ogni membro come i gruppi privati di Conversations, oppure entra in un gruppo con il suo indirizzo, e rispondi agli inviti a gruppi. Un gruppo che non è privato, un canale, non è cifrato, e lo dice. I tuoi gruppi seguono le altre app XMPP del tuo account, e un canale avvisa solo dei messaggi che ti nominano. Vedi [XMPP](#xmpp).",
  "**More in Matrix chats**: hold a message to react to it, reply to it, copy it and, if it is yours, edit it or delete it for everyone. Load earlier messages brings in older ones, and the microphone under the message box sends voice messages that Element plays too. Reactions are not encrypted, as Element sends them. See [Matrix](#matrix).":
    "**Di più nelle chat Matrix**: tieni premuto un messaggio per reagire, rispondergli, copiarlo e, se è tuo, modificarlo o eliminarlo per tutti. «Carica i messaggi precedenti» porta dentro quelli più vecchi, e il microfono sotto il campo del messaggio invia messaggi vocali che anche Element riproduce. Le reazioni non sono cifrate, come le invia Element. Vedi [Matrix](#matrix).",
  "**Video added to an XMPP call**: in a voice call with someone on XMPP, either of you can turn on video with Add video; the other is asked first and can say Not now. It works with apps that add video to a call as Conversations does. See [XMPP](#xmpp).":
    "**Il video aggiunto a una chiamata XMPP**: in una chiamata vocale con qualcuno su XMPP, ognuno di voi può attivare il video con «Aggiungi video»; all’altra persona si chiede prima e può dire «Non ora». Funziona con le app che aggiungono il video a una chiamata come Conversations. Vedi [XMPP](#xmpp).",
  "**Voice messages and replies in Nostr chats**: hold the microphone under the message box to send a voice message, which plays with Play; hold a message to reply to it, and the answer shows the message it is to, here and in other Nostr apps. See [Chats with other Nostr apps](#nostr-chats).":
    "**Messaggi vocali e risposte nelle chat Nostr**: tieni premuto il microfono sotto il campo del messaggio per inviare un messaggio vocale, che si riproduce con «Riproduci»; tieni premuto un messaggio per rispondergli, e la risposta mostra il messaggio a cui risponde, qui e nelle altre app Nostr. Vedi [Chat con altre app Nostr](#nostr-chats).",
  "**OMEMO 2 in XMPP chats**: a message to someone whose app speaks OMEMO 2, as Kaidan does, now goes with OMEMO 2 to that app and with OMEMO 0.3 to their others, as before. The XMPP screen shows this device's key both ways, to compare with what each app shows. See [XMPP](#xmpp).":
    "**OMEMO 2 nelle chat XMPP**: un messaggio a qualcuno la cui app parla OMEMO 2, come Kaidan, ora va con OMEMO 2 a quell’app e con OMEMO 0.3 alle sue altre app, come prima. La schermata XMPP mostra la chiave di questo dispositivo nei due modi, da confrontare con ciò che mostra ogni app. Vedi [XMPP](#xmpp).",
  "**Hidden chats can have their own Matrix, XMPP and Nostr accounts**: under the list of a place of hidden chats, Matrix, XMPP and Nostr open an account of that place alone, apart from the space's, kept encrypted with the hidden chats' key. Its chats show among the hidden chats only. It connects while they are open, and while they are closed too if Receive while closed is on, as the hidden chats do: then a message says only \"New message\", and a call rings with no name and is answered with the PIN. See [Hidden chats](#hidden).":
    "**Le chat nascoste possono avere i loro account Matrix, XMPP e Nostr**: sotto l’elenco di un posto di chat nascoste, Matrix, XMPP e Nostr aprono un account di quel solo posto, a parte quello dello spazio e tenuto cifrato con la chiave delle chat nascoste. Le sue chat si vedono solo tra le chat nascoste. Si collega mentre sono aperte, e anche da chiuse se Ricevere da chiuse è attivo, come le chat nascoste stesse: allora un messaggio dice solo «Nuovo messaggio», e una chiamata squilla senza nome e si risponde con il PIN. Vedi [Chat nascoste](#hidden).",
  "**Matrix, XMPP and Nostr in backups**: a backup now holds the Matrix, XMPP and Nostr accounts of every space and of its hidden chats. After a restore, a Nostr key comes back with its chats as they were; an XMPP account goes on as a new device of the account, with its contacts and chats; a Matrix account is let go of on this phone, and the space signs in again as a new device; its Security Key opens the messages from before. See [Backups](#backup).":
    "**Matrix, XMPP e Nostr nei backup**: un backup ora contiene gli account Matrix, XMPP e Nostr di ogni spazio e delle sue chat nascoste. Dopo un ripristino, una chiave Nostr torna con le sue chat com’erano; un account XMPP prosegue come nuovo dispositivo dell’account, con i suoi contatti e le sue chat; un account Matrix viene lasciato andare su questo telefono, e lo spazio accede di nuovo come nuovo dispositivo; la sua chiave di sicurezza apre i messaggi di prima. Vedi [Backup](#backup).",
  "**Matrix voice messages show their waveform, and Nostr answers can be photos**: a voice message sent in a Matrix chat carries its waveform, which Element draws, and one that comes with a waveform shows it under Play; in a Nostr chat, a photo, file or voice message sent while a message shows over the message box answers it. See [Matrix](#matrix) and [Chats with other Nostr apps](#nostr-chats).":
    "**I messaggi vocali Matrix mostrano la loro forma d’onda, e le risposte Nostr possono essere foto**: un messaggio vocale inviato in una chat Matrix porta la sua forma d’onda, che Element disegna, e uno che arriva con la forma d’onda la mostra sotto Riproduci; in una chat Nostr, una foto, un file o un messaggio vocale inviato mentre un messaggio compare sopra il campo gli risponde. Vedi [Matrix](#matrix) e [Chat con altre app Nostr](#nostr-chats).",
  "**Group calls in XMPP groups**: in a private XMPP group, start a voice or video call, answer one that rings, or join one going on, together with people who use Dino. See [XMPP](#xmpp).":
    "**Chiamate di gruppo nei gruppi XMPP**: in un gruppo privato XMPP, avvia una chiamata vocale o video, rispondi a una che squilla, o unisciti a una in corso, insieme a persone che usano Dino. Vedi [XMPP](#xmpp).",
  '**A call to a slow phone rings in full**: the caller now waits up to a minute and a quarter for the other phone to say it rings, and then 45 seconds from then, so a call that reached it late no longer rings there only to stop at once; and the phone called reads a call before anything it has to send, and waits for calls again at once after its network changes. See [Chat through a relay](#relay).':
    '**Una chiamata a un telefono lento squilla per intero**: chi chiama ora aspetta fino a un minuto e un quarto che l\'altro telefono dica che squilla, e poi 45 secondi da quel momento, così una chiamata arrivata in ritardo non squilla più per poi fermarsi subito; e il telefono chiamato legge una chiamata prima di tutto ciò che ha da inviare, e torna subito ad aspettare chiamate dopo un cambio di rete. Vedi [Chat tramite un relay](#relay).',
  "**The web app and the computer reach Matrix, XMPP and Nostr servers over HTTPS**: their page policy allowed only WebSocket connections, so Matrix sign-in, XMPP server discovery and file sharing, and Nostr files and name lookups failed there. They work now. See [Matrix](#matrix), [XMPP](#xmpp) and [Chats with other Nostr apps](#nostr-chats).":
    "**La web app e il computer raggiungono i server Matrix, XMPP e Nostr in HTTPS**: la politica della loro pagina ammetteva solo connessioni WebSocket, perciò lì non funzionavano l’accesso a Matrix, la scoperta del server XMPP e la condivisione di file, né i file e le ricerche di nomi su Nostr. Ora funzionano. Vedi [Matrix](#matrix), [XMPP](#xmpp) e [Chat con altre app Nostr](#nostr-chats).",
  // 3.4.2
  '**A message sent as a chat opens waits for it**, marked Sending…, and goes as soon as the chat is open, never saying that Erevos cannot encrypt.':
    '**Un messaggio inviato mentre una chat si apre la aspetta**, segnato Invio…, e parte appena la chat è aperta, senza dire che Erevos non può cifrare.',
  '**What you read as a chat opens stays read**: the home screen no longer counts it as new.':
    '**Ciò che leggi mentre una chat si apre resta letto**: la schermata iniziale non lo conta più come nuovo.',
  '**No question from Samsung about its sharing**: on a Samsung phone, Wi-Fi Aware and the Wi-Fi with phones nearby stay off until you turn them on. See [Chat with a nearby phone](#nearby).':
    '**Nessuna domanda di Samsung sulla sua condivisione**: su un telefono Samsung, Wi-Fi Aware e la rete Wi-Fi con i telefoni vicini restano spenti finché non li attivi. Vedi [Chattare con un telefono vicino](#nearby).',
  '**The SMS field keeps its width on a small screen**: Photo and Send beside it are round buttons, as in a chat.':
    '**Il campo dell’SMS mantiene la sua larghezza su uno schermo piccolo**: Foto e Invia accanto sono pulsanti rotondi, come in una chat.',
  // 3.4.1
  '**Send answers at once**: a short buzz as you press it, the field empties and the message shows, marked Sending…, so it never goes twice.':
    '**Invia risponde subito**: una breve vibrazione quando lo premi, il campo si svuota e il messaggio compare, segnato Invio…, così non parte mai due volte.',
  '**The screen no longer stays pushed up** after the keyboard closed behind a sheet, a dialog or another app.':
    '**Lo schermo non resta più spinto in alto** dopo che la tastiera si è chiusa dietro un pannello, una finestra di dialogo o un’altra app.',
  '**Importing a chat with its photos no longer freezes Erevos**: the screen moves while the files come in, says what share of them is in, and **Cancel** stops it. A chat moved into hidden chats takes the chats imported into it along. See [Imported chats](#import).':
    '**Importare una chat con le sue foto non blocca più Erevos**: lo schermo resta attivo mentre arrivano i file, dice quale parte è arrivata e **Annulla** la ferma. Una chat spostata nelle chat nascoste porta con sé le chat importate in essa. Vedi [Chat importate](#import).',
  // 3.4.0
  '**Your relay proves its own key**: every connection to it starts with a check only the relay holding that key can pass, so no one in between can pass for it. Once it has, Erevos never reaches it without the check. Your relay needs an update for it.':
    '**Il tuo relay dimostra la sua chiave**: ogni connessione inizia con un controllo che solo il relay con quella chiave può superare, così nessuno nel mezzo può spacciarsi per lui. Dopo averla dimostrata, Erevos non lo raggiunge più senza il controllo. Per questo il tuo relay va aggiornato.',
  '[Transparency](#transparency), a new part of the guide: what the server behind Erevos keeps and for how long, what it does not keep, and who else sees something.':
    '[Trasparenza](#transparency), una nuova parte della guida: cosa conserva il server dietro Erevos e per quanto tempo, cosa non conserva, e chi altro vede qualcosa.',
  "**What's new**: this list, in Settings → General, by version.": '**Novità**: questo elenco, in Impostazioni → Generali, per versione.',
  "**Nothing shows behind a chat's PIN**: none of the messages of a chat locked with a PIN is drawn until its PIN is typed, and with glass, a wallpaper or a style's own scene, the PIN screen is a dense frost that lets nothing through.":
    "**Dietro il PIN di una chat non si vede niente**: nessun messaggio di una chat bloccata con un PIN viene mostrato prima che il suo PIN sia scritto, e con il vetro, uno sfondo o uno stile con una scena propria, la schermata del PIN è un vetro smerigliato fitto che non lascia vedere niente.",
  "**A group video call from the top of the group**: a blue camera beside the green handset, as in a contact's chat.":
    "**Una videochiamata di gruppo dalla parte alta del gruppo**: una videocamera blu accanto alla cornetta verde, come nella chat con un contatto.",
  "**A relay queue for each contact**: each contact writes to a queue only they know, so the relay cannot tell that two contacts write to the same phone, and deleting or blocking someone deletes only theirs. Your relay needs an update for it.":
    "**Una coda del relay per ogni contatto**: ogni contatto scrive in una coda che conosce solo lui, così il relay non può capire che due contatti scrivono allo stesso telefono, ed eliminare o bloccare qualcuno cancella solo la sua. Il tuo relay deve essere aggiornato per questo.",
  "**Hidden chats, more like the others**: they close after 30 seconds in the background, not at once, and never during a call or while you pick a photo or a file; while open, a message plays its sound, and link previews have a switch of their own there. See [Hidden chats](#hidden).":
    "**Le chat nascoste, più come le altre**: si chiudono dopo 30 secondi in background, non subito, e mai durante una chiamata o mentre scegli una foto o un file; mentre sono aperte, un messaggio fa il suo suono, e le anteprime dei link hanno lì un interruttore proprio. Vedi [Chat nascoste](#hidden).",
  "**Hidden chats that receive while closed**: a switch at the top of each place, on for new places, has them receive as your other chats do: their contacts see at once that a message came, a notice says only \"New message\", and a call rings with no name. See [Hidden chats](#hidden).":
    "**Chat nascoste che ricevono da chiuse**: un interruttore in cima a ogni posto, attivo nei posti nuovi, le fa ricevere come le tue altre chat: i loro contatti vedono subito che un messaggio è arrivato, una notifica dice solo «Nuovo messaggio», e una chiamata squilla senza nome. Vedi [Chat nascoste](#hidden).",
  "**Hidden chats wait and import too**: what cannot go now waits, marked Waiting, and goes by itself through their relay; Send later works there as in your other chats; and a chat from Telegram, WhatsApp or Viber can be imported into a hidden chat, kept only there. See [Hidden chats](#hidden).":
    "**Anche le chat nascoste aspettano e importano**: ciò che non può partire ora resta in attesa, segnato «In attesa», e parte da solo tramite il loro relay; «Invia più tardi» funziona lì come nelle tue altre chat; e una chat di Telegram, WhatsApp o Viber può essere importata in una chat nascosta, tenuta solo lì. Vedi [Chat nascoste](#hidden).",
  "**Hidden chats listed like your chats**: they open on a list as the home screen's, with what was said last and how many are not read, and each place has a Chat with myself of its own at its top. See [Hidden chats](#hidden).":
    "**Le chat nascoste in un elenco come le tue chat**: si aprono su un elenco come quello della schermata iniziale, con l’ultima cosa detta e quanti non sono letti, e ogni posto ha in cima la sua Chat con me stesso. Vedi [Chat nascoste](#hidden).",
  "**More in hidden chats**: with Receive while closed on, what comes to them through Nostr is read while they are closed too; and there a contact can be added from a photo of their QR code, and a hidden contact given a photo. See [Hidden chats](#hidden).":
    "**Di più nelle chat nascoste**: con Ricevere da chiuse, ciò che arriva loro tramite Nostr si legge anche mentre sono chiuse; e lì si può aggiungere un contatto da una foto del suo codice QR e dare una foto a un contatto nascosto. Vedi [Chat nascoste](#hidden).",
  "**Hidden chats with no relay**: as your other chats, they can begin through Nostr only: their contact link and QR code say where they read there, and texts and reactions go there. See [Hidden chats](#hidden).":
    "**Chat nascoste senza relay**: come le tue altre chat, possono iniziare solo tramite Nostr: il loro link di contatto e il codice QR dicono dove leggono lì, e testi e reazioni vanno lì. Vedi [Chat nascoste](#hidden).",
  "**Groups in hidden chats**: under their list, New group makes a group with their contacts; it lists among their chats, goes through their relay only, and is read while they are closed if Receive while closed is on. See [Hidden chats](#hidden).":
    "**Gruppi nelle chat nascoste**: sotto il loro elenco, Nuovo gruppo crea un gruppo con i loro contatti; compare tra le loro chat, passa solo dal loro relay e viene letto mentre sono chiuse se Ricevere da chiuse è attivo. Vedi [Chat nascoste](#hidden).",
  "**No test version line**: the home screen no longer ends saying this is a test version. The guide still says exactly what is protected, and that nothing has been audited yet. See [What is protected today](#privacy).":
    "**Niente più riga sulla versione di prova**: la schermata iniziale non finisce più dicendo che è una versione di prova. La guida dice ancora esattamente cosa è protetto, e che niente è stato ancora verificato. Vedi [Cosa è protetto oggi](#privacy).",
  "**The contacts menu in hidden chats**: their Contacts has a menu again, with what is theirs only: a .vcf file imported into them, their contacts saved as a .vcf file, and a contact's QR code read from a photo. An Erevos ID typed there adds them to the hidden chats. See [Contacts](#contacts).":
    "**Il menu dei contatti nelle chat nascoste**: i loro Contatti hanno di nuovo un menu, solo con ciò che è loro: un file .vcf importato in esse, i loro contatti salvati come file .vcf e il codice QR di un contatto letto da una foto. Un ID Erevos scritto lì lo aggiunge alle chat nascoste. Vedi [Contatti](#contacts).",
  // 3.3.2
  '**The plain call button for more contacts**: the orange keypad at the top of a contact’s chat also takes the number of a contact you connected them to (**Connect to one of my contacts**), the mobile number first.':
    '**Il pulsante di chiamata normale per più contatti**: il tastierino arancione in cima alla chat di un contatto usa anche il numero del contatto a cui l’hai collegato (**Collega a uno dei miei contatti**), prima il cellulare.',
  // 3.3.1
  '**Viber chats can be imported**: from the HTML file of the Android app Backup Text for Viber, words only.':
    '**Si possono importare le chat di Viber**: dal file HTML dell’app Android Backup Text for Viber, solo i testi.',
  // 3.3.0
  '**Start without a relay, through Nostr**: **Start without a relay** on New chat. Texts, stickers, reactions, edits and the delivered and read marks go through Nostr over Tor. Photos, voice messages, files and calls still need a relay or a phone nearby.':
    '**Inizia senza relay, tramite Nostr**: **Inizia senza relay** in Nuova chat. Testi, sticker, reazioni, modifiche e i segni di consegna e lettura passano per Nostr, tramite Tor. Foto, messaggi vocali, file e chiamate richiedono ancora un relay o un telefono vicino.',
  '**The relay comes by itself**: whoever has a relay that invites sends a contact with no relay an invite once, inside the chat, and the other phone takes it by itself.':
    '**Il relay arriva da solo**: chi ha un relay che fa inviti manda una volta un invito a un contatto senza relay, dentro la chat, e l’altro telefono lo accetta da solo.',
  '**Told when a new version is out** (Android): once a day Erevos asks LPHL’s server, then shows a pinned Erevos row and a notice, only for a version the release computer signed. It turns off in Settings → General → Updates.':
    '**Avviso quando esce una nuova versione** (Android): una volta al giorno Erevos chiede al server di LPHL, poi mostra una riga Erevos fissata in alto e una notifica, solo per una versione firmata dal computer delle versioni. Si disattiva in Impostazioni → Generali → Aggiornamenti.',
  '**Lock a chat with a PIN**: Details → Lock with a PIN, for chats and groups. Nothing of it shows in search, starred messages or imports. In hidden chats it asks for no PIN.':
    '**Blocca una chat con un PIN**: Dettagli → Blocca con un PIN, per chat e gruppi. Niente di quella chat compare nella ricerca, nei messaggi importanti o nelle importazioni. Nelle chat nascoste non chiede nessun PIN.',
  '**A new handset** on the green tiles: Phone, and the call in a chat.': '**Una nuova cornetta** sui riquadri verdi: Telefono, e la chiamata in una chat.',
  '**A new New chat screen**: How you connect now at the top, three large cards for a phone without a relay (I have an invite, Sign in with LPHL, Start without a relay), and the technical part under For advanced users.':
    '**Una nuova schermata Nuova chat**: «Come ti colleghi ora» in alto, tre grandi schede per un telefono senza relay (Ho un invito, Accedi con LPHL, Inizia senza relay), e la parte tecnica in «Per utenti esperti».',
  '**Nostr steadier through Tor**: each Nostr relay has its own way through Tor, and after a failure it tries a new exit. A clearer error on the Nostr screen.':
    '**Nostr più stabile tramite Tor**: ogni relay Nostr ha il suo percorso in Tor, e dopo un errore prova una nuova uscita. Un messaggio di errore più chiaro nella schermata Nostr.',
  '**When the connection to the relay drops** while Erevos waits on it, Erevos notices and connects again, where it stayed stuck before.':
    '**Quando la connessione al relay cade** mentre Erevos aspetta una risposta, Erevos se ne accorge e si ricollega, dove prima restava bloccato.',
  '**Invite by SMS** (Android): on a phone contact’s card, for one person, for 2 days. The link opens a page that offers Erevos (the APK for Android, the web app for an iPhone or a computer), then opens the invite. The QR code and Share the invite stay as they were.':
    '**Invita via SMS** (Android): nella scheda di un contatto del telefono, per una persona, per 2 giorni. Il link apre una pagina che offre Erevos (l’APK per Android, la web app per iPhone o computer), poi apre l’invito. Il codice QR e Condividi l’invito restano come prima.',
  '**Fixes to the SMS invite**: a link copied as /i/#… works too, an older web app opens the invite as well, and on iOS 26 it says Share is under •••.':
    '**Correzioni all’invito via SMS**: funziona anche un link copiato come /i/#…, anche una web app più vecchia apre l’invito, e su iOS 26 dice che Condividi è dentro •••.',
  '**A phone call button** in Erevos chats and SMS chats.': '**Un pulsante per le telefonate** nelle chat Erevos e nelle chat SMS.',
  // 3.2.1
  '**Edit a message** you sent, up to a day after: to contacts, groups and linked devices, with Edited beside the time.':
    '**Modifica un messaggio** che hai inviato, fino a un giorno dopo: per contatti, gruppi e dispositivi collegati, con Modificato accanto all’ora.',
  '**Nostr says what it did**: Sent through Nostr, and on the Nostr screen what each relay did last.':
    '**Nostr dice cosa ha fatto**: «Inviato tramite Nostr», e nella schermata Nostr cosa ha fatto per ultimo ogni relay.',
  '**Coloured call buttons** at the top of a chat: video blue, voice green.': '**Pulsanti di chiamata colorati** in cima a una chat: video blu, voce verde.',
  // 3.2.0
  'Arrows to the start and the end of a chat; earlier messages come by themselves as you scroll.':
    'Frecce per andare all’inizio e alla fine di una chat; i messaggi precedenti arrivano da soli mentre scorri.',
  'Chats imported from Telegram and WhatsApp look like Erevos messages: bubbles, days, photos, voice messages, search.':
    'Le chat importate da Telegram e WhatsApp sembrano messaggi di Erevos: fumetti, giorni, foto, messaggi vocali, ricerca.',
  'Dogs instead of cats in the stickers.': 'Cani al posto dei gatti negli sticker.',
  'Screenshots: a switch in Settings → Privacy and security.': 'Screenshot: un interruttore in Impostazioni → Privacy e sicurezza.',
  'Hidden chats from New chat: hold it for a second.': 'Chat nascoste da Nuova chat: tienila premuta per un secondo.',
  'Coloured tiles on the home screen: Phone green, Contacts violet, the lock orange.': 'Riquadri colorati nella schermata principale: Telefono verde, Contatti viola, il lucchetto arancione.',
  '**Chat with myself**, always first, and **Remind me**, the orange bell.': '**Chat con me stesso**, sempre in cima, e **Ricordamelo**, la campanella arancione.',
  '**Media, links and files** in a chat’s Details, with a calendar and Go to a day.':
    '**Media, link e file** nei Dettagli di una chat, con un calendario e Vai a un giorno.',
  'Import a chat from inside the chat: Details → Imported chats.': 'Importa una chat da dentro la chat stessa: Dettagli → Chat importate.',
  'A closed space can say that a message came while another space is open.': 'Uno spazio chiuso può dire che è arrivato un messaggio mentre è aperto un altro spazio.',
  'The message menu says when a message went or came through Nostr.': 'Il menu del messaggio dice quando un messaggio è partito o arrivato tramite Nostr.',
  '**Support Erevos**: Liberapay, PayPal, Monero, Bitcoin.': '**Sostieni Erevos**: Liberapay, PayPal, Monero, Bitcoin.',
  'Who makes Erevos and why, in About Erevos; the guide says why everywhere.': 'Chi fa Erevos e perché, in Informazioni su Erevos; la guida spiega ovunque il perché.',
  // 3.1.2
  '**Settings in 8 groups**, with a search: General, Appearance, Notifications, Privacy and security, Relay and networks, Phone and SMS, Data and devices, For testing. The home screen’s ⋯ keeps only the places, and Settings last.':
    '**Impostazioni in 8 gruppi**, con una ricerca: Generali, Aspetto, Notifiche, Privacy e sicurezza, Relay e reti, Telefono e SMS, Dati e dispositivi, Per i test. Il ⋯ della schermata principale tiene solo le schermate, e per ultime le Impostazioni.',
  // 3.1.1
  'Check for updates says what stopped an update.': 'Cerca aggiornamenti dice cosa ha bloccato un aggiornamento.',
  'Invite someone is not made from a token for all; it asks you to sign in to the relay first.':
    'Invita qualcuno non parte più da un token condiviso; prima ti chiede di accedere al relay.',
  'The relay’s token for all becomes a token of the phone’s own, by itself (needs the relay updated).':
    'Il token condiviso del relay diventa da solo un token tutto del telefono (serve il relay aggiornato).',
  'A relay that refuses through Tor says why.': 'Un relay che rifiuta tramite Tor dice perché.',
  // 3.1.0
  'Less battery in the background: the relay, Tor and the nearby radios.': 'Meno batteria in background: il relay, Tor e le radio per i telefoni vicini.',
  'Erevos no longer closes when you make a sticker from a photo.': 'Erevos non si chiude più quando crei uno sticker da una foto.',
  'Hidden chats’ notices are right.': 'Le notifiche delle chat nascoste sono corrette.',
  'Hidden chats by holding New chat.': 'Chat nascoste tenendo premuto Nuova chat.',
  'A search for contacts on the Phone.': 'Una ricerca dei contatti nel Telefono.',
  'New chat shows first how to add a contact.': 'Nuova chat mostra per prima cosa come aggiungere un contatto.',
  'A call shows over the screen saver, and the screen wakes.': 'Una chiamata appare sopra il salvaschermo, e lo schermo si riaccende.',
  'Erevos in other apps’ Share.': 'Erevos in Condividi delle altre app.',
  'A sound for every new message, also while Erevos shows.': 'Un suono per ogni nuovo messaggio, anche mentre Erevos è aperto.',
  'The SMS settings say right what holding does.': 'Le impostazioni SMS dicono bene cosa succede tenendo premuto.',
  // 3.0.0
  'Each icon opens what it names: Erevos, SMS, Phone, Contacts, the widget.': 'Ogni icona apre ciò che indica: Erevos, SMS, Telefono, Contatti, il widget.',
  '**Messages through Tor by default**: Messages, Everything or Nothing.': '**Messaggi tramite Tor in modo predefinito**: Messaggi, Tutto o Niente.',
  '**Texts through Nostr**: three public relays, through Tor, with your own relay as backup after 5 minutes.':
    '**I testi tramite Nostr**: tre relay pubblici, tramite Tor, con il tuo relay come riserva dopo 5 minuti.',
  // 2.0.3
  'One invite for everything: the relay and the contact together.': 'Un solo invito per tutto: il relay e il contatto insieme.',
  'Spam rules for senders and numbers abroad, with the reason.': 'Regole antispam per mittenti e numeri esteri, con il motivo.',
  '480 stickers in 20 sets.': '480 sticker in 20 set.',
  'Lighter chats on older phones; QR codes at once.': 'Chat più leggere sui telefoni più vecchi; codici QR subito.',
  'Copy code for one-time codes in SMS.': 'Copia codice per i codici monouso negli SMS.',
  'Locked, Erevos keeps receiving.': 'Anche bloccato, Erevos continua a ricevere.',
  'Faster contacts; the hidden chats’ notice counts only messages.': 'Contatti più veloci; la notifica delle chat nascoste conta solo i messaggi.',
  'The relay tries every address: push, other relays, the LPHL sign-in.': 'Il relay prova ogni indirizzo: push, altri relay, l’accesso con LPHL.',
  // 2.0.2
  'Swiping on the tabs only changes the tab.': 'Scorrere sulle schede cambia solo la scheda.',
  'The icons fill the launcher’s shape.': 'Le icone riempiono la forma del launcher.',
  // 2.0.1
  'Coloured icons (Erevos red, Phone green, SMS blue, Contacts violet) and a new SMS icon.':
    'Icone colorate (Erevos rosso, Telefono verde, SMS blu, Contatti viola) e una nuova icona SMS.',
  'A colour for each icon, and the order of the widget’s buttons.': 'Un colore per ogni icona, e l’ordine dei pulsanti del widget.',
  'Swipe to go back, and between tabs.': 'Scorri per tornare indietro, e tra le schede.',
  // 2.0.0
  'An update of the WebView no longer closes Erevos.': 'Un aggiornamento della WebView non chiude più Erevos.',
  'Deleting or blocking a contact gives you a new queue on the relay.': 'Eliminare o bloccare un contatto ti dà una nuova coda sul relay.',
  'A new contact can take the name of a contact on the phone.': 'Un nuovo contatto può prendere il nome di un contatto del telefono.',
  '**Sign in to the relay with LPHL**, and **invites to the relay**.': '**Accesso al relay con LPHL**, e **inviti al relay**.',
  'Permissions in the web app, and more on Android; the web app’s notice says how many came.':
    'Permessi nella web app, e altri su Android; la notifica della web app dice quanti messaggi sono arrivati.',
  'Hidden chats can ring calls while they are closed.': 'Le chat nascoste possono far squillare le chiamate mentre sono chiuse.',
  'New keys every month in chats, every week in groups.': 'Chiavi nuove ogni mese nelle chat, ogni settimana nei gruppi.',
  'Linked devices work with the phone off.': 'I dispositivi collegati funzionano con il telefono spento.',
  'A new chat screen; QR codes from a photo; the Phone for small screens.': 'Una nuova schermata della chat; codici QR da una foto; il Telefono per schermi piccoli.',
  'Add as contact inside a group.': 'Aggiungi come contatto dentro un gruppo.',
  'Stickers in sets, moving, and your own.': 'Sticker in set, animati, e i tuoi.',
  'SMS inside the Erevos chat.': 'Gli SMS dentro la chat di Erevos.',
  'Android updates need the release computer’s signature.': 'Gli aggiornamenti Android richiedono la firma del computer delle versioni.',
  'An F-Droid build; Serbo-Croatian; new version numbers.': 'Una versione per F-Droid; il serbo-croato; nuovi numeri di versione.',
  'Much for security: Argon2id, messages encrypted for the relay too, a token for each phone, no link starts a call.':
    'Molto per la sicurezza: Argon2id, messaggi cifrati anche per il relay, un token per ogni telefono, nessun link avvia una chiamata.',
  // 0.1.16
  'Imports from Telegram and WhatsApp bring photos, videos, voice messages and files.': 'Le importazioni da Telegram e WhatsApp portano foto, video, messaggi vocali e file.',
  'A phone without a relay talks through a place on a contact’s relay.': 'Un telefono senza relay comunica tramite un posto sul relay di un contatto.',
  // 0.1.14
  'Back to my chats, for hidden chats.': 'Riporta nelle mie chat, per le chat nascoste.',
  'Erevos receives and rings even after you swipe it away from the recent apps.': 'Erevos riceve e squilla anche dopo che lo togli dalle app recenti.',
  // 0.1.12
  'Hidden chats can say a message came.': 'Le chat nascoste possono dire che è arrivato un messaggio.',
  'Fixes: menus, QR codes from a photo, Bluetooth on Android 17, long lists.': 'Correzioni: menu, codici QR da una foto, Bluetooth su Android 17, elenchi lunghi.',
  // 0.1.11
  'The Phone without the password, if you allow it; a home screen widget; an SMS and Erevos filter.':
    'Il Telefono senza password, se lo permetti; un widget per la schermata principale; un filtro SMS ed Erevos.',
  // 0.1.10
  'Links wait for the password; Phone and Contacts icons; the Erevos ID on a contact.': 'I link aspettano la password; icone di Telefono e Contatti; l’ID Erevos su un contatto.',
  // 0.1.8
  '61 new features: 5 new languages, linked devices, public groups, replies, reactions, polls, send later, Erevos as the phone and contacts app, Tor bridges, the fingerprint, Windows and more.':
    '61 nuove funzioni: 5 nuove lingue, dispositivi collegati, gruppi pubblici, risposte, reazioni, sondaggi, invio più tardi, Erevos come app per telefono e contatti, bridge Tor, l’impronta, Windows e altro.',
  // 0.1.7 to 0.1.2
  'SMS notices in the background.': 'Notifiche SMS in background.',
  'The web app comes out with every release.': 'La web app esce con ogni versione.',
  'Greek in the whole app.': 'Il greco in tutta l’app.',
  'Web Push in the web app.': 'Web Push nella web app.',
  'The first signed Android release: encrypted chats, calls, groups, hidden chats, backups, imports, and phones nearby without the internet.':
    'La prima versione Android firmata: chat cifrate, chiamate, gruppi, chat nascoste, backup, importazioni, e telefoni vicini senza internet.',
  "**Two new sticker sets of 24 moods**: **Tux**, the Linux penguin as he is drawn, and **Aikido**, an aikidoka in keikogi and a wide hakama, who also bows, sits in seiza and rolls.":
    "**Due nuovi set di adesivi con 24 stati d'animo**: **Tux**, il pinguino di Linux così com'è disegnato, e **Aikido**, un aikidoka in keikogi e ampio hakama, che si inchina anche, siede in seiza e fa una capriola.",
  "**A new sticker set, Takis**: a caricature in a dark suit and a purple tie with dots, in 24 moods that move.":
    "**Un nuovo set di adesivi, Takis**: una caricatura in abito scuro e cravatta viola a pois, in 24 stati d'animo che si muovono.",
  "**Photos, files and voice messages with no relay**: when there is no relay between you and your contact and they read on Nostr, a voice message goes through Nostr like a text, a photo up to 3 MB in pieces, and a larger photo, a video or another file, up to 20 MB, to an encrypted file server (Blossom), all through Tor. See [Through Nostr](#nostr).":
    "**Foto, file e messaggi vocali senza relay**: quando non c’è un relay tra te e il tuo contatto e lui legge su Nostr, un messaggio vocale passa da Nostr come un testo, una foto fino a 3 MB in pezzi, e una foto più grande, un video o un altro file, fino a 20 MB, verso un server di file cifrato (Blossom), tutto tramite Tor. Vedi [Tramite Nostr](#nostr).",
  "**More battery saved in the background, if you choose**: under Settings → Notifications → In the background, Only the waste stays the default; And nearby phones also turns off the radios for phones nearby while Erevos is in the background; And sleep also lets the phone sleep, so Erevos looks at your relay about once a minute and a message or a call can be a minute or two late. Android only. See [Chat through a relay](#relay).":
    "**Più batteria risparmiata in secondo piano, se lo scegli**: in Impostazioni → Notifiche → In background, Solo lo spreco resta il predefinito; E i telefoni vicini spegne anche le radio per i telefoni vicini finché Erevos è in secondo piano; E il sonno lascia dormire anche il telefono, così Erevos guarda il tuo relay circa una volta al minuto e un messaggio o una chiamata può arrivare con uno o due minuti di ritardo. Solo Android. Vedi [Chat tramite un relay](#relay).",
  "**A contact you delete no longer comes back from an old ask**: in a group, a member you asked for their contact link, or who asked for yours, and whom you then deleted as a contact before Erevos looked at the relay again, could be added again by that old ask. Deleting them now lets go of it at once. See [Group chats](#groups).":
    "**Un contatto eliminato non torna più da una vecchia richiesta**: in un gruppo, un membro di cui avevi chiesto il link di contatto, o che aveva chiesto il tuo, e che poi eliminavi come contatto prima che Erevos guardasse di nuovo il relay, poteva essere aggiunto di nuovo da quella vecchia richiesta. Ora eliminarlo la lascia subito. Vedi [Chat di gruppo](#groups).",
  "**Every message says which way it went**: hold a message and its menu says whether it went or came through the relay, through Nostr, to a phone nearby or over LoRa. Messages from before say nothing. See [Through Nostr](#nostr).":
    "**Ogni messaggio dice da che parte è passato**: tieni premuto un messaggio e il suo menu dice se è andato o arrivato tramite il relay, tramite Nostr, da un telefono vicino o tramite LoRa. I messaggi di prima non dicono nulla. Vedi [Tramite Nostr](#nostr).",
  "**The spam filter reads words as they look**: a scam text that swaps a letter for a look-alike of another alphabet, or hides a mark that shows nothing inside a word, no longer gets past it. See [SMS](#sms).":
    "**Il filtro dello spam legge le parole come appaiono**: un SMS truffa che cambia una lettera con una simile di un altro alfabeto, o nasconde in una parola un segno che non si vede, non lo inganna più. Vedi [SMS](#sms).",
  "**Media, links and files in groups too**: in a group's details, a list of its photos, videos, voice messages, music, files and links, each kind apart under its months, with a calendar, as in a contact's chat. A tap opens or plays; held, each goes to its message. See [Group chats](#groups).":
    "**Media, link e file anche nei gruppi**: nei dettagli di un gruppo, un elenco delle sue foto, video, messaggi vocali, musica, file e link, ogni tipo a parte sotto i suoi mesi, con un calendario, come nella chat di un contatto. Un tocco apre o riproduce; tenuto premuto, ognuno va al suo messaggio. Vedi [Chat di gruppo](#groups).",
  "**A relay restart no longer brings a false notice**: after your relay restarted, a hidden chat or a closed space said New message once more for messages it had told of already. Your relay needs an update for it. See [Hidden chats](#hidden).":
    "**Un riavvio del relay non porta più una notifica falsa**: dopo il riavvio del tuo relay, una chat nascosta o uno spazio chiuso diceva di nuovo Nuovo messaggio per messaggi di cui aveva già avvisato. Il tuo relay deve essere aggiornato per questo. Vedi [Chat nascoste](#hidden).",
  "**Backups to your server through Tor**: on Android, automatic backups sent to your own server now follow the space's choice under Settings → Relay and networks → Tor, as Matrix does, so with Tor the server no longer sees where you are. To a server too says when they go through Tor. See [Backups](#backup).":
    "**Backup sul tuo server tramite Tor**: su Android, i backup automatici inviati al tuo server ora seguono la scelta dello spazio in Impostazioni → Relay e reti → Tor, come Matrix, così con Tor il server non vede più dove sei. Anche su un server dice quando passano per Tor. Vedi [Backup](#backup).",
  "**Restore a backup straight from your server**: Restore from a server, under Backups, lists the backups on your server, newest first, and opens the one you choose with its password, with no download by hand, on a new phone too. See [Backups](#backup).":
    "**Ripristina un backup direttamente dal tuo server**: Ripristina da un server, in Backup, mostra i backup sul tuo server, i più recenti per primi, e apre quello che scegli con la sua password, senza scaricarlo a mano, anche su un telefono nuovo. Vedi [Backup](#backup).",
  "**Backups to your server from a computer and the web app too**: in the desktop app, automatic backups go to your WebDAV server as on Android; in the web app, Send a backup now sends one there, with a server that lets the web app in. Both can restore from it. Not through Tor. See [Backups](#backup).":
    "**Backup sul tuo server anche dal computer e dalla web app**: nell'app per computer i backup automatici vanno al tuo server WebDAV come su Android; nella web app, Invia un backup ora ne invia uno lì, con un server che fa entrare la web app. Entrambe possono ripristinare da lì. Non tramite Tor. Vedi [Backup](#backup).",
  "**Check a contact in person with QR codes**: under Safety number in a chat's details, each phone shows a code; take a photo of the code on the other phone, and they of yours. When it matches, the contact is marked Checked in person. Nothing is sent. See [Chat through a relay](#relay).": "**Verifica un contatto di persona con i codici QR**: in Codice di sicurezza, nei dettagli di una chat, ogni telefono mostra un codice; fotografa il codice sull’altro telefono, e lui il tuo. Quando corrisponde, il contatto viene segnato Verificato di persona. Non viene inviato nulla. Vedi [Chat tramite un relay](#relay).",
  "**Up to three home relays**: under Settings → Relay and networks → Home relay, Add another home relay gives a space up to two more, each with a queue of its own. Your contact link and your messages name them in order, and contacts try each while the ones before cannot be reached. See [Home relay](#home-relay).": "**Fino a tre relay di casa**: in Impostazioni → Relay e reti → Relay di casa, Aggiungi un altro relay di casa dà a uno spazio fino a due in più, ognuno con la sua coda. Il tuo link di contatto e i tuoi messaggi li nominano in ordine, e i contatti provano ciascuno finché i precedenti non si raggiungono. Vedi [Relay di casa](#home-relay).",
  "**Introduce two of your contacts**: in a contact's chat details, Introduce to a contact asks them and another contact of yours, each in your chat with them. Only if both say yes do they become contacts, and neither learns whether the other said no. See [Chat through a relay](#relay).": "**Presenta due dei tuoi contatti**: nei dettagli della chat di un contatto, Presenta a un contatto chiede a lui e a un altro dei tuoi contatti, a ciascuno nella tua chat con lui. Diventano contatti solo se entrambi dicono di sì, e nessuno sa se l’altro ha detto di no. Vedi [Chat tramite un relay](#relay).",
  "**Bluetooth that cannot be followed**: the random number your phone sends out over Bluetooth for phones nearby to find it changed only when Erevos started again; it now changes every nine to twelve minutes, so someone listening cannot follow your phone from place to place by it. Older Erevos phones still find yours. See [Chat with a nearby phone](#nearby).": "**Bluetooth che non si può seguire**: il numero casuale che il tuo telefono trasmette via Bluetooth perché i telefoni vicini lo trovino cambiava solo al riavvio di Erevos; ora cambia ogni nove-dodici minuti, così chi ascolta non può seguire il tuo telefono da un posto all’altro con esso. I telefoni con un Erevos più vecchio trovano ancora il tuo. Vedi [Chat con un telefono vicino](#nearby).",
  "**Hidden chats show at once**: as the PIN opens them, their chats and contacts show at once, to read, while what they were receiving in the background ends; before, that could hold them back a long while, as it may go through Tor. See [Hidden chats](#hidden).": "**Le chat nascoste si vedono subito**: appena il PIN le apre, le loro chat e i loro contatti si vedono subito, per leggerli, mentre termina ciò che ricevevano in background; prima, ciò poteva trattenerle a lungo, perché può passare tramite Tor. Vedi [Chat nascoste](#hidden).",
  "**Your backup password in pieces with friends**: under Settings → Data and devices → Backup pieces, give pieces of it to 3 to 5 contacts; any 2 or 3 of them give it back, one alone shows nothing. Each goes inside the encryption of your chat with them and only their Erevos keeps it; your phone keeps none. See [Backup pieces with friends](#backup-pieces).": "**La password dei tuoi backup in pezzi presso amici**: in Impostazioni → Dati e dispositivi → Pezzi del backup, danne dei pezzi a 3-5 contatti; 2 o 3 qualsiasi la restituiscono, uno solo non mostra nulla. Ognuno viaggia dentro la crittografia della tua chat con loro e solo il loro Erevos lo conserva; il tuo telefono non ne tiene nessuno. Vedi [Pezzi del backup presso amici](#backup-pieces).",
  "**Panic button**: under Settings → Privacy and security → Panic button, wipe everything Erevos keeps here with one tap, on Android and in the web app. On Android, a panic app such as Ripple can do it too, but only the one you say yes to, checked by its signature. See [Panic button](#panic).": "**Pulsante di panico**: in Impostazioni → Privacy e sicurezza → Pulsante di panico, cancella con un tocco tutto ciò che Erevos tiene qui, su Android e nell’app web. Su Android può farlo anche un’app di panico come Ripple, ma solo quella a cui dici di sì, controllata dalla sua firma. Vedi [Pulsante di panico](#panic).",
  "**Erevos to a phone nearby, with no internet**: under Settings → General → Give Erevos to a phone nearby, this phone serves its Erevos over the same Wi-Fi or its hotspot for ten minutes, with a QR code. A phone without Erevos downloads it in the browser; one with an older Erevos takes it under Updates → From a phone nearby, which installs it only when it is Erevos, signed as that one is. See [Erevos to a phone nearby](#give-app).": "**Erevos a un telefono vicino, senza internet**: in Impostazioni → Generali → Dai Erevos a un telefono vicino, questo telefono serve il suo Erevos sulla stessa Wi-Fi o sul suo hotspot per dieci minuti, con un codice QR. Un telefono senza Erevos lo scarica nel browser; uno con un Erevos più vecchio lo prende in Aggiornamenti → Da un telefono vicino, che lo installa solo se è Erevos, firmato come quello. Vedi [Erevos a un telefono vicino](#give-app).",
  "**Hidden chats with phones nearby**: while hidden chats are open, or receive while closed, they reach a contact's phone nearby over Bluetooth, Wi-Fi Aware, Wi-Fi Direct or the same Wi-Fi, with no internet, as your other chats do. The space never learns that a hidden contact is near, and nothing on the air tells their messages from the space's; other phones never carry them, and they never go over LoRa or by SMS. See [Hidden chats](#hidden).":
    "**Chat nascoste con i telefoni vicini**: mentre le chat nascoste sono aperte, o ricevono da chiuse, raggiungono il telefono di un contatto vicino via Bluetooth, Wi-Fi Aware, Wi-Fi Direct o sulla stessa rete Wi-Fi, senza internet, come le tue altre chat. Lo spazio non sa mai che un contatto nascosto è vicino, e niente nell’aria distingue i loro messaggi da quelli dello spazio; altri telefoni non li portano mai, e non passano mai via LoRa né via SMS. Vedi [Chat nascoste](#hidden).",
  "**The same Wi-Fi on Sailfish OS**: Erevos on Sailfish OS finds Erevos phones and computers on the same Wi-Fi or a phone's hotspot and talks with them with no internet, as on a computer. See [On Sailfish OS](#sailfish).":
    "**La stessa rete Wi-Fi su Sailfish OS**: Erevos su Sailfish OS trova telefoni e computer con Erevos sulla stessa rete Wi-Fi o sull’hotspot di un telefono e parla con loro senza internet, come su un computer. Vedi [Su Sailfish OS](#sailfish).",
  "**Downloads stop at 100 MB**: a file, a backup from a server or any other download is read as it comes and stopped as soon as it passes 100 MB, or less where the network's files are smaller, such as 20 MB for Nostr files, so a file server a contact names can no longer fill the phone's memory with an answer without end. A backup on a server comes back up to 100 MB; download a larger one and open it with Restore a backup. See [Backups](#backup).":
    "**I download si fermano a 100 MB**: un file, un backup da un server o qualsiasi altro download viene letto man mano che arriva e fermato appena supera i 100 MB, o meno dove i file della rete sono più piccoli, come 20 MB per i file di Nostr, così un file server indicato da un contatto non può più riempire la memoria del telefono con una risposta senza fine. Un backup su un server torna fino a 100 MB; uno più grande scaricalo e aprilo con Ripristina un backup. Vedi [Backup](#backup).",
  "**Profile pictures on Matrix and XMPP**: contacts and Matrix rooms show their picture in the chat list, and you can set your own on the Matrix and XMPP screens (Choose a photo). Pictures are not encrypted on either network: the server sees them. See [Matrix](#matrix) and [XMPP](#xmpp).":
    "**Foto del profilo su Matrix e XMPP**: i contatti e le stanze Matrix mostrano la loro foto nell’elenco delle chat, e puoi mettere la tua nelle schermate Matrix e XMPP (Scegli una foto). Le foto non sono cifrate su nessuna delle due reti: il server le vede. Vedi [Matrix](#matrix) e [XMPP](#xmpp).",
  "**Run an XMPP group**: a group's admins can set its subject and take people out or bar them, its owner can rename it and make admins, and in a channel the admin sees who is in it and can put them out. See [XMPP](#xmpp).":
    "**Gestire un gruppo XMPP**: gli admin di un gruppo ne impostano l’oggetto e rimuovono o escludono persone, il proprietario lo rinomina e nomina admin, e in un canale l’admin vede chi c’è dentro e può farlo uscire. Vedi [XMPP](#xmpp).",
  "**Check a Matrix device by QR code**: once both sides accept a check, Erevos shows a code for Element (or another Erevos) to photograph, or photographs theirs, as Element does; comparing emoji stays one tap away. See [Matrix](#matrix).":
    "**Verificare un dispositivo Matrix con codice QR**: quando entrambi accettano una verifica, Erevos mostra un codice da far fotografare a Element (o a un altro Erevos), o fotografa il loro, come fa Element; il confronto delle emoji resta a un tocco. Vedi [Matrix](#matrix).",
  "**Sign in to Matrix with single sign-on** (Android): when your Matrix server signs people in on its own page, as matrix.org does, Sign in with single sign-on opens it in the browser and comes back to Erevos. See [Matrix](#matrix).":
    "**Accedere a Matrix con il single sign-on** (Android): quando il tuo server Matrix fa accedere le persone sulla propria pagina, come matrix.org, «Accedi con accesso unico (SSO)» la apre nel browser e torna a Erevos. Vedi [Matrix](#matrix).",
  "**A closed space tells of XMPP messages**: on Android, Say a message came under While this space is closed, on the XMPP screen, has a closed space say \"New message\" when something comes on XMPP while another space is open, never what, from whom or in which chat. Off until you choose it. It needs a relay updated for it and an XMPP server that sends notices to apps that are away; the XMPP server then learns the relay's name, and the relay when messages come. See [XMPP](#xmpp).":
    "**Uno spazio chiuso avvisa dei messaggi XMPP**: su Android, «Avvisa dei nuovi messaggi» in «Mentre questo spazio è chiuso», nella schermata di XMPP, lascia che uno spazio chiuso dica «New message» quando arriva qualcosa su XMPP mentre è aperto un altro spazio, mai cosa, da chi o in quale chat. Spento finché non lo scegli. Serve un relay aggiornato per questo e un server XMPP che mandi avvisi alle app inattive; il server XMPP conosce allora il nome del relay, e il relay quando arrivano messaggi. Vedi [XMPP](#xmpp).",
  "**Linking a computer is clearer**: on a computer, Settings → Data and devices → Linked devices now starts with Link to my phone, with LPHL's relay filled in and Sign in with LPHL under the token, so no token has to be copied from the phone; and it says that the QR code shows once Link to my phone is tapped. See [Linked devices](#devices).":
    "**Collegare un computer è più chiaro**: su un computer, Impostazioni → Dati e dispositivi → Dispositivi collegati ora comincia con «Collega al mio telefono», con il relay di LPHL già inserito e «Accedi con LPHL» sotto il token, così non serve copiare nessun token dal telefono; e dice che il codice QR compare quando si tocca «Collega al mio telefono». Vedi [Dispositivi collegati](#devices).",
  "**Delete me from everywhere**: Settings → Privacy and security → Delete me from everywhere deletes what the servers keep for the open space (its queues on the relays with the messages in them, what a relay holds for you to send later, files waiting there, invites nobody used), asks the Nostr relays through Tor to forget the keys your chats read on, and stops the space until you tap Start again. Your phone keeps everything. You can also sign out of Matrix and XMPP and delete the Nostr account made here. See [Delete me from everywhere](#forget).": "**Cancellami da ovunque**: Impostazioni → Privacy e sicurezza → Cancellami da ovunque cancella ciò che i server conservano per lo spazio aperto (le sue code sui relay con i messaggi dentro, ciò che un relay tiene per inviarlo dopo, i file che vi aspettano, gli inviti che nessuno ha usato), chiede via Tor ai relay Nostr di dimenticare le chiavi su cui leggono le tue chat, e ferma lo spazio finché non tocchi Riavvia. Il tuo telefono conserva tutto. Puoi anche uscire da Matrix e XMPP e cancellare l'account Nostr creato qui. Vedi [Cancellami da ovunque](#forget).",
  "**Every relay queue on one list**: the queues a space keeps on the relays are gathered in one place, and the checks fail if a new kind of queue is made without being added there, so Delete me from everywhere cannot leave one behind.": "**Ogni coda del relay in un elenco**: le code che uno spazio tiene sui relay sono riunite in un solo posto, e i controlli falliscono se si crea un nuovo tipo di coda senza aggiungerlo lì, così Cancellami da ovunque non ne lascia nessuna.",
  "**Matrix, XMPP and Nostr on a linked computer**: linking a computer can bring this space's Matrix and XMPP accounts and the key of its Nostr chats over too, each signed in there as a new device of its own; for a computer linked already, tap Send the accounts under it on the phone. A Matrix server seldom lets the phone sign the computer in: the computer then asks for the Matrix password once, and the account's keys come from the phone, so no Security Key or check by emoji is needed. See [Linked devices](#devices).":
    "**Matrix, XMPP e Nostr su un computer collegato**: collegando un computer si possono portare anche gli account Matrix e XMPP di questo spazio e la chiave delle sue chat Nostr, ciascuno con l’accesso eseguito lì come nuovo dispositivo a sé; per un computer già collegato, tocca «Invia gli account» sotto di esso sul telefono. Un server Matrix di rado lascia che il telefono faccia accedere il computer: il computer chiede allora una volta la password di Matrix, e le chiavi dell’account arrivano dal telefono, quindi non servono né la chiave di sicurezza né la verifica con le emoji. Vedi [Dispositivi collegati](#devices).",
  "**Only the SMS**: with Erevos locked, the SMS icon, the widget's SMS button and the notice of a new SMS ask for the password, then open only the SMS. Anything else, and the orange padlock **Unlock everything**, asks for it again, then opens all of Erevos. See [Password lock](#lock).":
    "**Solo gli SMS**: con Erevos bloccato, l’icona SMS, il pulsante SMS del widget e la notifica di un nuovo SMS chiedono la password e poi aprono solo gli SMS. Tutto il resto, compreso il lucchetto arancione **Sblocca tutto**, la chiede di nuovo e poi apre tutto Erevos. Vedi [Blocco con password](#lock).",
  "**Nostr chats with a key brought from another app get their messages again**: Erevos reads where that app said your messages arrive, as that app does, instead of its own three relays, fetches the messages kept there and in older lists of the key, and reads a relay again when it stops sending. Before, such a key could show its chats with no past messages and get no new ones. See [Chats with other Nostr apps](#nostr-chats).":
    "**Le chat Nostr con una chiave portata da un’altra app tornano a ricevere i loro messaggi**: Erevos legge dove quell’app ha detto che arrivano i tuoi messaggi, come fa quell’app, invece dei suoi tre relay, recupera i messaggi tenuti lì e nelle liste precedenti della chiave, e rilegge un relay quando smette di inviare. Prima, una chiave così poteva mostrare le sue chat senza messaggi passati e non riceverne di nuovi. Vedi [Chat con altre app Nostr](#nostr-chats).",
  "**Backups keep what closed chats need**: a backup now also holds what lets hidden chats ring a call and say a message came while they are closed, and a closed space say one came. So after a restore, on another phone too, **Ring calls when closed**, **Say when a message comes** and **Also while another space is open** go on as they were. See [Backups](#backup).":
    "**I backup tengono ciò che serve alle chat chiuse**: un backup ora tiene anche ciò che permette alle chat nascoste di far squillare una chiamata e di avvisare che è arrivato un messaggio mentre sono chiuse, e a uno spazio chiuso di avvisare che ne è arrivato uno. Così, dopo un ripristino, anche su un altro telefono, **Fai squillare le chiamate quando sono chiuse**, **Avvisa quando arriva un messaggio** e **Anche mentre è aperto un altro spazio** continuano come prima. Vedi [Backup](#backup).",
  "**Open another space from the search**: type another space's password in **Search chats** on the home screen and press Enter: the open space closes, nothing of it stays, and the other opens, as with **Lock now** and its password. It takes as long whatever is typed, and a wrong password, or the open space's own, is just a search. See [Second password](#second).":
    "**Aprire un altro spazio dalla ricerca**: scrivi la password di un altro spazio in **Cerca nelle chat** nella schermata principale e premi Invio: lo spazio aperto si chiude, senza che ne resti nulla, e si apre l’altro, come con **Blocca ora** e la sua password. Ci mette lo stesso tempo qualunque cosa scrivi, e una password sbagliata, o quella dello spazio aperto, è solo una ricerca. Vedi [Seconda password](#second).",
  "**A dot for unread messages elsewhere, if you want it**: hidden chats with **Receive while closed** can show a small dot on the magnifier of **Search chats** while they have a message unread (their switch **Dot for unread messages**), and a space set to say a message came while another is open can show one on the padlock at the top of the other spaces' chats (**Dot in the other spaces**). Never how many, nor where; off unless you turn it on. See [Hidden chats](#hidden).":
    "**Un punto per i non letti altrove, se lo vuoi**: le chat nascoste con **Ricevere da chiuse** possono mostrare un piccolo punto sulla lente di **Cerca nelle chat** finché hanno un messaggio non letto (il loro interruttore **Punto per i non letti**), e uno spazio che avvisa che è arrivato un messaggio mentre ne è aperto un altro può mostrarne uno sul lucchetto sopra le chat degli altri spazi (**Punto negli altri spazi**). Mai quanti, né dove; spento a meno che non lo accendi. Vedi [Chat nascoste](#hidden).",
  "**Joining takes only the invite**: on a phone with no relay yet, **New chat** shows one way in, **I have an invite**. Signing in with LPHL, **Start without a relay** and the relay's settings are under **For advanced users**, for whoever looks for them. And an invite to your relay gives the relay only a name of random letters and digits for the phone it lets in: the name you type stays on your phone, where your list of invites shows it. See [Chat through a relay](#relay).":
    "**Per entrare basta l’invito**: su un telefono ancora senza relay, **Nuova chat** mostra un modo per entrare, **Ho un invito**. L’accesso con LPHL, **Inizia senza relay** e le impostazioni del relay sono in **Per utenti esperti**, per chi li cerca. E un invito al tuo relay dà al relay solo un nome di lettere e cifre a caso per il telefono che fa entrare: il nome che scrivi resta sul tuo telefono, dove lo mostra la tua lista degli inviti. Vedi [Chat tramite un relay](#relay).",
  "**Invited phones stay**: on a relay of this version, a phone you invited keeps its access even once yours goes, and so do the phones it invited; taking back an invite cuts off that one phone alone. See [Chat through a relay](#relay).":
    "**I telefoni invitati restano**: su un relay di questa versione, un telefono che hai invitato tiene il suo accesso anche quando il tuo se ne va, e così anche i telefoni che ha invitato; ritirare un invito esclude solo quel telefono. Vedi [Chat tramite un relay](#relay).",
  "**Backups bring the phone back as it was**: a backup now holds the photos, files and voice messages too, in files of their own beside it, each sealed and bound to its backup; and the panic password, the settings that go with you, the Phone's quick replies and the calls it turns away, the SMS for later and automatic backups with their server, but not their folder. An SMS for later whose time passed before the restore waits for you to send it or delete it. What stays with each phone, as the fingerprint, the folders and what Android allows, never comes back: after a restore, Android's permissions open for the modules that are on. See [Backups](#backup).":
    "**I backup riportano il telefono com’era**: un backup ora contiene anche le foto, i file e i messaggi vocali, in file a parte accanto a lui, ognuno sigillato e legato al suo backup; e la password di panico, le impostazioni che ti seguono, le risposte rapide del Telefono e le chiamate che rifiuta, gli SMS per più tardi e i backup automatici con il loro server, ma non la loro cartella. Un SMS per più tardi la cui ora è passata prima del ripristino aspetta che tu lo invii o lo elimini. Quello che resta a ogni telefono, come l’impronta, le cartelle e quello che Android consente, non torna mai: dopo un ripristino si aprono le autorizzazioni di Android per i moduli attivi. Vedi [Backup](#backup).",
  "**A newer backup asks for a newer Erevos**: a backup made by a newer Erevos than yours is refused, with nothing changed, and Erevos asks you to update to the latest version first. An Erevos from before 6.0.0 does not open backups from 6.0.0 on: update it, then restore. See [Backups](#backup).":
    "**Un backup più recente chiede un Erevos più recente**: un backup fatto da un Erevos più recente del tuo viene rifiutato, senza cambiare nulla, ed Erevos ti chiede di aggiornarlo prima all’ultima versione. Un Erevos precedente alla 6.0.0 non apre i backup dalla 6.0.0 in poi: aggiornalo, poi ripristina. Vedi [Backup](#backup).",
  "**Shared into the Collection with no plain copy**: a photo or file another app shares with Erevos is encrypted as it comes in, before **Send to** opens, so on its way into the Collection it never lies unencrypted on the phone. It can be up to 4 GB there, and a large one shows how far it is encrypted, with **Cancel**; a chat still takes 100 MB at most. See [Collection](#collection).": "**Condivisione nella Raccolta senza copia in chiaro**: una foto o un file che un'altra app condivide con Erevos viene cifrato appena arriva, prima che si apra **Invia a**, così nel suo percorso verso la Raccolta non resta mai non cifrato sul telefono. Lì può arrivare a 4 GB; una chat accetta ancora al massimo 100 MB. Per uno grande si vede a che punto è la cifratura, con **Annulla**. Vedi [Raccolta](#collection).",
  "**See a file come from the WebDAV server**: a file of the Collection that is not on this device, as after a backup restored on a new phone, shows how much of it has come from the server, and **Cancel** stops it; what came stays, and the next time only the rest comes. Music, videos, PDFs and **Open with another app** fetch it first too, instead of failing. See [Collection](#collection).": "**Guarda un file arrivare dal server WebDAV**: un file della Raccolta che non è su questo dispositivo, come dopo un backup ripristinato su un nuovo telefono, mostra quanto ne è già arrivato dal server, e **Annulla** lo ferma; ciò che è arrivato resta, e la volta successiva arriva solo il resto. Musica, video, PDF e **Apri con un'altra app** lo recuperano anche loro prima, invece di fallire. Vedi [Raccolta](#collection).",
  "**Backups skip what is on the WebDAV server after a restart too**: that a Collection's copies on its server are complete is kept with it, so a backup made after Erevos starts again still leaves its pieces out, as long as no file was added or deleted since. **The connection works.** now shows in the colour of success, not of a warning. See [Collection](#collection).": "**I backup tralasciano ciò che è sul server WebDAV anche dopo un riavvio**: il fatto che le copie di una Raccolta sul suo server siano complete viene conservato con essa, così un backup fatto dopo il riavvio di Erevos continua a lasciarne fuori i pezzi, finché da allora non è stato aggiunto né eliminato alcun file. **La connessione funziona.** ora appare nel colore del successo, non di un avviso. Vedi [Raccolta](#collection).",
  "**Notes from another app**: an app on the phone, as Fasouli for a payment that is coming, can ask to keep a note with its reminder in Chat with myself. Erevos asks you first, in the space you open. See [Getting started](#start).":
    "**Note da un’altra app**: un’app del telefono, come Fasouli per un pagamento in arrivo, può chiedere di tenere una nota con il suo promemoria in Chat con me stesso. Erevos ti chiede prima, nello spazio che apri. Vedi [Per iniziare](#start).",
  "**Payment requests**: another app, as Fasouli, can ask Erevos to send one to a contact: an amount and what it is for, as a card. They tap **Paid** once they paid, and **Mark in Fasouli** then marks it collected there. Erevos moves no money. See [Chat through a relay](#relay).":
    "**Richieste di pagamento**: un’altra app, come Fasouli, può chiedere a Erevos di inviarne una a un contatto: un importo e per cosa, come scheda. Il contatto tocca **Pagato** quando ha pagato, e **Segna in Fasouli** la segna incassata lì. Erevos non sposta denaro. Vedi [Chat tramite un relay](#relay).",
  "**Panic tells Fasouli too**: on Android, under Settings → Privacy and security → Panic button → **Tell other apps**, choose the apps Erevos tells as it wipes, as a panic app does: Fasouli then locks itself. Each asks you first. See [Panic button](#panic).":
    "**Il panico avvisa anche Fasouli**: su Android, in Impostazioni → Privacy e sicurezza → Pulsante di panico → **Avvisa altre app**, scegli le app che Erevos avvisa quando cancella, come un’app di panico: Fasouli allora si blocca. Ognuna ti chiede prima. Vedi [Pulsante di panico](#panic).",
  "**The Collection in the browser and on Sailfish OS**: the web app, on an iPhone's home screen too, and Erevos on Sailfish OS have the Collection now. A file is encrypted a piece at a time as it is read, and if the browser runs out of room nothing of it is kept. Photos, text, music and videos up to 256 MB open in memory only; a PDF is saved to be read elsewhere. See [Collection](#collection).":
    "**La Raccolta nel browser e su Sailfish OS**: l’app web, anche nella schermata iniziale di un iPhone, ed Erevos su Sailfish OS hanno ora la Raccolta. Un file è cifrato un pezzo alla volta mentre viene letto, e se il browser resta senza spazio non ne resta nulla. Foto, testi, musica e video fino a 256 MB si aprono solo in memoria; un PDF si salva per leggerlo altrove. Vedi [Raccolta](#collection).",
  "**Large files saved from the Collection on Sailfish OS**: **Save to phone** writes a file of any size to Downloads a piece at a time, as the desktop app now does too, and when the disk has no room left Erevos says so and leaves nothing half-written. See [Collection](#collection).":
    "**File grandi salvati dalla Raccolta su Sailfish OS**: **Salva sul telefono** scrive in Downloads un file di qualsiasi dimensione un pezzo alla volta, come ora fa anche l’app desktop, e quando il disco non ha più spazio Erevos lo dice e non lascia nulla scritto a metà. Vedi [Raccolta](#collection).",
  "**Sign in with Nextcloud**: a Collection's server and the backups' server can now be your Nextcloud, as LPHL's, the one Fasouli syncs with, without typing a password: tap **Sign in with Nextcloud**, sign in in the browser and grant access. Erevos gets an app password of its own and its own folder there, Erevos/Collection or Erevos/Backups. See [Collection](#collection).":
    "**Accedi con Nextcloud**: il server di una Raccolta e quello dei backup ora possono essere il tuo Nextcloud, come quello di LPHL, quello con cui si sincronizza Fasouli, senza scrivere una password: tocca **Accedi con Nextcloud**, accedi nel browser e concedi l’accesso. Erevos riceve una password per app tutta sua e una sua cartella lì, Erevos/Collection o Erevos/Backups. Vedi [Raccolta](#collection).",
  "**Web app and Sailfish OS fixes from the review**: in the web app, each space that turns notifications on gets a push address of its own, from a service worker of its own, so a relay is never given another space's address and it never ties two spaces together; the browser's settings then list one service worker for each such space. A check for a new release that was slow to answer no longer brings back the release just replaced. On Sailfish OS, another app on the phone can no longer make Erevos hold on to memory, nor give orders to the helper that waits at the relay while Erevos is out of sight. See [On an iPhone](#iphone).":
    "**Correzioni dalla revisione nell’app web e su Sailfish OS**: nell’app web, ogni spazio che attiva le notifiche riceve un proprio indirizzo push, da un proprio service worker, quindi un relay non riceve mai l’indirizzo di un altro spazio e questo non lega mai due spazi; le impostazioni del browser elencano allora un service worker per ognuno di quegli spazi. Una ricerca di nuova versione lenta a rispondere non riporta più la versione appena sostituita. Su Sailfish OS, un’altra app del telefono non può più far trattenere memoria a Erevos, né dare ordini all’aiutante che aspetta al relay mentre Erevos non è sullo schermo. Vedi [Su un iPhone](#iphone).",
  "**Photos of the Collection one after the other**: in a photo, the arrows (on a phone too, while the bars show) or a swipe go to the next or the one before, and **Slideshow** shows them by themselves, one every 4 seconds, till a tap. On a computer, in a browser and on Sailfish OS a photo opens again instead of staying at **Opening the photo…**. See [Collection](#collection).": "**Le foto della Raccolta una dopo l’altra**: in una foto, le frecce (anche sul telefono, finché si vedono le barre) o uno scorrimento portano alla successiva o alla precedente, e **Presentazione** le mostra da sola, una ogni 4 secondi, fino a un tocco. Sul computer, in un browser e su Sailfish OS una foto si apre di nuovo invece di restare su **Apertura della foto…**. Vedi [Raccolta](#collection).",
  "**Reminders that come again**: a note Fasouli keeps for a scheduled payment now reminds you each time it is due, every month or as the payment repeats, and shows how often. Once you see it, it moves to its next time. See [Getting started](#start).":
    "**Promemoria che tornano**: una nota che Fasouli tiene per un pagamento programmato ora ti avvisa ogni volta che scade, ogni mese o come si ripete il pagamento, e mostra ogni quanto. Appena la vedi, passa alla volta successiva. Vedi [Getting started](#start).",
  "**Who is online on Matrix and XMPP**: under a contact's name it says, as their server does, **Online**, **Away** or **Do not disturb**, with the words they set, or when they were last online, and their picture in the chat list has a green dot. On Matrix, Erevos no longer says you are online unless you turn on **Say when I am online** on the Matrix screen. See [Matrix](#matrix).":
    "**Chi è online su Matrix e XMPP**: sotto il nome di un contatto compare, come dice il suo server, **Online**, **Assente** o **Non disturbare**, con le parole che ha messo, o quando era online l’ultima volta, e la sua foto nell’elenco delle chat ha un punto verde. Su Matrix, Erevos non dice più che sei online, a meno che attivi **Dire quando sono online** nella schermata Matrix. Vedi [Matrix](#matrix).",
  "**Link a computer with one tap**: on the computer, **Linked devices** now shows a small code at once. Scan it with the phone and tap **Link**: the phone gives the computer what it needs through Nostr, end-to-end encrypted, and nothing has to be typed or compared. If Nostr cannot be reached, **Link another way** keeps the old way. See [Linked devices](#devices).":
    "**Collega un computer con un tocco**: sul computer, **Dispositivi collegati** mostra ora subito un piccolo codice. Inquadralo con il telefono e tocca **Collega**: il telefono dà al computer ciò che gli serve tramite Nostr, cifrato end-to-end, e non c’è nulla da scrivere o confrontare. Se Nostr non è raggiungibile, **Collega in un altro modo** mantiene il modo di prima. Vedi [Dispositivi collegati](#devices).",
  '**Choose the name others see**: under Settings → Privacy and security → **My name**, give this space a name that your contacts and your private groups see instead of a code, always encrypted. Hidden chats have a name of their own, in their settings, empty at first. See [Chat through a relay](#relay).':
    '**Scegli il nome che gli altri vedono**: in Impostazioni → Privacy e sicurezza → **Il mio nome**, dai a questo spazio un nome che i tuoi contatti e i tuoi gruppi privati vedono al posto di un codice, sempre cifrato. Le chat nascoste hanno un nome proprio, nelle loro impostazioni, vuoto all’inizio. Vedi [Chat tramite un relay](#relay).',
  "**Folders in Chat with myself**: notes, photos, files and voice messages can now go in folders. The folder button at the top makes one; its tab above the notes then shows only what is in it, and what you write while it is chosen goes into it. Holding a note offers **Move to a folder**; holding a folder's tab renames or deletes it, its notes staying. The folders go to your linked devices with the notes. See [Getting started](#start).":
    "**Cartelle in Chat con me stesso**: note, foto, file e messaggi vocali ora possono stare in cartelle. Il pulsante cartella in alto ne crea una; la sua scheda sopra le note mostra allora solo ciò che contiene, e ciò che scrivi mentre è scelta ci finisce dentro. Tenendo premuta una nota hai **Sposta in una cartella**; tenendo premuta la scheda di una cartella la rinomini o la elimini, e le sue note restano. Le cartelle vanno ai tuoi dispositivi collegati insieme alle note. Vedi [Per iniziare](#start).",
  "**The battery mode And sleep spares more**: each time it wakes the phone to look, about once a minute, the phone now sleeps again within a second or two when nothing came, not after 25 seconds.":
    "**La modalità batteria «E il sonno» risparmia di più**: ogni volta che sveglia il telefono per guardare, circa una volta al minuto, il telefono ora torna a dormire entro uno o due secondi se non è arrivato nulla, non dopo 25 secondi.",
  "**Messages come at once while Erevos shows**: Erevos now waits at your relay with the connection open also while it is on the screen, so a message or a call comes the moment it is sent, not at the next look every 3 seconds, and the phone's radio rests in between.":
    "**I messaggi arrivano subito mentre Erevos è visibile**: ora Erevos attende al tuo relay con la connessione aperta anche mentre è sullo schermo, così un messaggio o una chiamata arriva nel momento in cui viene inviato, non al prossimo controllo ogni 3 secondi, e la radio del telefono riposa nel frattempo.",
  "**A new battery mode, And light sleep**: under Settings → Notifications → In the background. The phone may sleep, and what comes to your relay wakes it, so messages and calls still come at once where the network and Android allow it. It is new: if messages come late with it, choose another.":
    "**Una nuova modalità batteria, «E il sonno leggero»**: in Impostazioni → Notifiche → In background. Il telefono può dormire, e ciò che arriva al tuo relay lo sveglia, così messaggi e chiamate arrivano ancora subito dove la rete e Android lo consentono. È nuova: se con essa i messaggi arrivano in ritardo, scegline un’altra.",
  "**Chats are saved faster**: a message that comes, is read or is deleted is saved by looking only at its own chat, which shows most with many chats or after a large import. The chat screen is no longer drawn again every 5 seconds.":
    "**Le chat si salvano più in fretta**: un messaggio che arriva, viene letto o viene eliminato è salvato guardando solo la sua chat, cosa che si nota di più con molte chat o dopo una grande importazione. La schermata della chat non viene più ridisegnata ogni 5 secondi.",
  "**Large imports write less**: the note of the files an import is still writing is kept in small parts, not written whole for every file.":
    "**Le grandi importazioni scrivono meno**: la nota dei file che un’importazione sta ancora scrivendo è tenuta in piccole parti, non scritta per intero per ogni file.",
  "**A text no longer waits for slow Nostr relays**: with Nostr on, a text waited for a Nostr relay to say it took it, up to 20 seconds when none answered, before it went through the relay. Now, when none says so within 4 seconds, it goes through the relay as well at once.":
    "**Un messaggio non aspetta più i relay Nostr lenti**: con Nostr attivo, un messaggio aspettava che un relay Nostr dicesse di averlo preso, fino a 20 secondi quando nessuno rispondeva, prima di passare dal relay. Ora, se nessuno lo dice entro 4 secondi, passa subito anche dal relay.",
  "**Voice messages in Opus**: on Android 10 and later, in the web app and on a computer, voice messages are recorded as Ogg/Opus, as Telegram and Element send them: as clear as before at half the size, about 240 KB a minute. Every Erevos plays them, Safari on an older iPhone too. See [Chat through a relay](#relay).":
    "**Messaggi vocali in Opus**: su Android 10 e successivi, nell’app web e su un computer, i messaggi vocali si registrano in Ogg/Opus, come li inviano Telegram e Element: chiari come prima a metà dimensione, circa 240 KB al minuto. Ogni Erevos li riproduce, anche Safari su un iPhone più vecchio. Vedi [Chat tramite un relay](#relay).",
  "**Mark all as read**: the ⋮ menu of the chats has it for the part of the list you are on, all messages, SMS, Erevos, Matrix, XMPP or Nostr, and the Matrix, XMPP and Nostr screens have it for their chats. It asks first, then reads each chat as opening it would: those who wrote are told as then. See [Getting started](#start).":
    "**Segna tutto come letto**: il menu ⋮ delle chat lo ha per la parte dell’elenco in cui ti trovi, tutti i messaggi, SMS, Erevos, Matrix, XMPP o Nostr, e le schermate di Matrix, XMPP e Nostr lo hanno per le proprie chat. Chiede prima, poi legge ogni chat come farebbe aprirla: chi ha scritto viene avvisato come allora. Vedi [Per iniziare](#start).",
  "**Answer with video, or voice only**: an incoming call, Erevos, group, XMPP or Matrix, now offers both. You can add video to an Erevos voice call while it goes on, and Flip on a computer moves to your next camera. See [Chat through a relay](#relay).":
    "**Rispondere con video o solo con la voce**: una chiamata in arrivo, di Erevos, di gruppo, XMPP o Matrix, offre ora entrambe le cose. Puoi aggiungere il video a una chiamata vocale di Erevos mentre è in corso, e Gira su un computer passa alla tua fotocamera successiva. Vedi [Chat tramite un relay](#relay).",
  "**Voice messages, places, contact cards and pins in SMS**: in an SMS conversation, hold the microphone to send a voice message by MMS. **+** also sends where you are, as an SMS with a map link any phone opens, and a contact from your phone as a contact card. Voice messages, contact cards and map links you receive show as such, to play, save or open. Hold a message down to **Pin for me**, kept only on this phone, or **Select** several to copy, forward or delete them together. See [SMS](#sms).":
    "**Messaggi vocali, luoghi, schede contatto e messaggi fissati negli SMS**: in una conversazione SMS, tieni premuto il microfono per inviare un messaggio vocale come MMS. **+** invia anche dove ti trovi, come SMS con un link di mappa che ogni telefono apre, e un contatto del tuo telefono come scheda contatto. I messaggi vocali, le schede contatto e i link di mappa che ricevi si vedono come tali, da riprodurre, salvare o aprire. Tieni premuto un messaggio per **Fissa solo per me**, tenuto solo su questo telefono, o **Seleziona** più messaggi per copiarli, inoltrarli o eliminarli insieme. Vedi [SMS](#sms).",
  "**More in XMPP chats**: voice messages from other XMPP apps now play in the chat and show how long they are; **Sticker** sends your own photo stickers as photos, encrypted as the chat is; groups show who is **owner** or **admin**, and the owner can set the group's **Description**; **Forward** sends one or several messages to another XMPP chat; tapping a quoted reply goes to the message; **Pin for me** keeps a message at the top on this phone only; and **Select** chooses several messages to copy, forward or delete. See [XMPP](#xmpp).":
    "**Di più nelle chat XMPP**: i messaggi vocali di altre app XMPP ora si riproducono nella chat e mostrano la loro durata; **Sticker** invia i tuoi sticker fatti da foto come foto, crittografate come la chat; i gruppi mostrano chi è **proprietario** o **admin**, e il proprietario può impostare la **Descrizione** del gruppo; **Inoltra** invia uno o più messaggi a un’altra chat XMPP; toccare una risposta citata va al messaggio; **Fissa solo per me** tiene un messaggio in cima solo su questo telefono; e **Seleziona** sceglie più messaggi da copiare, inoltrare o eliminare. Vedi [XMPP](#xmpp).",
  "**More in Nostr chats**: tap a reaction to add it or take yours back, pin messages for yourself, select several to copy, forward or delete, send your own photo stickers, and see, vote on and make polls in the Public feed. See [Chats with other Nostr apps](#nostr-chats).":
    "**Di più nelle chat Nostr**: tocca una reazione per aggiungerla o ritirare la tua, fissa messaggi per te, scegline più di uno da copiare, inoltrare o eliminare, invia i tuoi sticker fatti da foto, e guarda, vota e crea sondaggi nel feed pubblico. Vedi [Chat con altre app Nostr](#nostr-chats).",
  "**Matrix groups and stickers**: in a Matrix group, **Members** shows who is in it and who is an admin or moderator, and lets admins rename it, set its subject, make admins, and take people out or bar them. Stickers sent from Element and other Matrix apps now show, and your own stickers made from photos can be sent. **New chat** can find people by name, and **Select** in a message's menu chooses several messages to copy, forward or delete. See [Matrix](#matrix).":
    "**Gruppi e sticker su Matrix**: in un gruppo Matrix, **Membri** mostra chi c’è e chi è admin o moderatore, e lascia che gli admin lo rinominino, ne impostino l’oggetto, nominino altri admin, e rimuovano o escludano persone. Gli sticker inviati da Element e da altre app Matrix ora si vedono, e si possono inviare i tuoi sticker fatti da foto. **Nuova chat** può trovare persone per nome, e **Seleziona** nel menu di un messaggio sceglie più messaggi da copiare, inoltrare o eliminare. Vedi [Matrix](#matrix).",
  "**More in your chats and groups**: choose several messages to copy, forward or delete at once; end your polls; reply in threads in groups; give a group a description; and send a contact from your phone as a card. See [Chat through a relay](#relay) and [Group chats](#groups).":
    "**Di più nelle tue chat e nei tuoi gruppi**: scegli più messaggi da copiare, inoltrare o eliminare in una volta; termina i tuoi sondaggi; rispondi nei thread nei gruppi; dai una descrizione a un gruppo; e invia un contatto del tuo telefono come scheda. Vedi [Chat tramite un relay](#relay) e [Chat di gruppo](#groups).",
  "**Ticks**: a text the other phone had, and read, before it showed as sent here (through a slow Nostr relay) now shows as read, not with one tick. Ticks from a contact on another relay no longer stop, and a text that reaches a phone while Erevos is in the background there gets its second tick at that phone's next check.":
    "**Spunte**: un testo che l’altro telefono aveva già e aveva letto prima che qui risultasse inviato (tramite un relay Nostr lento) ora risulta letto, non con una sola spunta. Le spunte di un contatto su un altro relay non si fermano più, e un testo che arriva a un telefono mentre lì Erevos è in background riceve la seconda spunta al successivo controllo di quel telefono.",
  "**Stickers on other networks**: a built-in sticker sent on Matrix, XMPP, Nostr or by MMS arrives as its picture, made on your device, its words in your language. See [Chat through a relay](#relay).":
    "**Sticker su altre reti**: uno sticker integrato inviato su Matrix, XMPP, Nostr o via MMS arriva come la sua immagine, fatta sul tuo dispositivo, con le parole nella tua lingua. Vedi [Chat tramite un relay](#relay).",
  "**One button for all your services**: under the search on the home screen, one button says which service shows, with the messages not read and any service not connected now. Tap it for a window with every service as a card, each with its own number and a dot for its connection; **Add** turns more on, and holding a card moves it or hides it. With no search, the chats with messages not read come first, under **Unread**, then the rest under **Recent**. See [Getting started](#start).":
    "**Un pulsante per tutti i tuoi servizi**: sotto la ricerca della schermata principale, un pulsante dice quale servizio si vede, con i messaggi non letti e ogni servizio che ora non è connesso. Toccalo per una finestra con ogni servizio come scheda, ognuna con il suo numero e un punto per la sua connessione; **Aggiungi** ne attiva altri, e tenere premuta una scheda la sposta o la nasconde. Senza ricerca vengono prima le chat con messaggi non letti, sotto **Non letti**, poi le altre sotto **Recenti**. Vedi [Per iniziare](#start).",
  "**Share an imported chat with the other person**: a Telegram, WhatsApp or Viber chat that goes on with an Erevos contact can now go to them too, from the chat's **Details** or **Settings** → **Data and devices** → **Imported chats**: every message, photo, video, voice message and file, end-to-end encrypted, to them alone, whatever its size. Their Erevos keeps the messages at once and shows them ahead of the new messages, the sides swapped; the files follow in rounds through your relay while both phones run Erevos, each up to 4 GB, as large as an import now keeps. See [Imported chats](#import).":
    "**Condividi una chat importata con l'altra persona**: una chat di Telegram, WhatsApp o Viber che continua con un contatto Erevos ora può andare anche a lui, dai **Dettagli** della chat o da **Impostazioni** → **Dati e dispositivi** → **Chat importate**: ogni messaggio, foto, video, messaggio vocale e file, crittografato end-to-end, solo a lui, di qualunque dimensione. Il suo Erevos tiene subito i messaggi e li mostra prima dei nuovi messaggi, con i lati scambiati; i file seguono a turni attraverso il tuo relay finché Erevos è attivo su entrambi i telefoni, ciascuno fino a 4 GB, grande quanto ora ne tiene un'importazione. Vedi [Chat importate](#import).",
  "**Tor for your XMPP account, and per chat**: on Android, the XMPP screen, and the one before signing in, chooses **Off** (the default), **As the space** or **Always through Tor** for the account: its connection, the look for its server and its files, never straight when it must not. **Through Tor** under any XMPP chat or group, off by default, sends the whole account only through Tor while on, as one connection carries all its chats. Calls do not go through Tor. Before you send while the account does not go through Tor, before a call and before a file from another server, Erevos says once that your internet address can be seen, and how not to. See [XMPP](#xmpp).":
    "**Tor per il tuo account XMPP, e per chat**: su Android, la schermata XMPP, e quella prima dell’accesso, sceglie per l’account **Disattivato** (il predefinito), **Come lo spazio** o **Sempre tramite Tor**: la sua connessione, la ricerca del suo server e i suoi file, mai diretti quando non deve. **Tramite Tor** sotto ogni chat o gruppo XMPP, disattivato di default, fa passare tutto l’account solo tramite Tor finché è attivo, perché una connessione porta tutte le sue chat. Le chiamate non passano tramite Tor. Prima che tu invii finché l’account non passa tramite Tor, prima di una chiamata e prima di un file da un altro server, Erevos dice una volta che il tuo indirizzo internet può essere visto, e come evitarlo. Vedi [XMPP](#xmpp).",
  "**Tor for Messenger and Signal, and per chat**: in Erevos+, the Messenger and Signal screens, and the ones before signing in, choose **Off** (the default), **As the space** or **Always through Tor** for the account. With it, everything of the account goes through Tor, its pictures and files too, and Messenger's sign-in page and Signal's registering, captcha and linking as well: never straight when it must not. **Through Tor** under any of their chats, off by default, sends the whole account only through Tor while on, as each has one connection. Calls do not go through Tor.":
    "**Tor per Messenger e Signal, anche per chat**: in Erevos+, le schermate di Messenger e Signal, anche prima dell’accesso, scelgono per l’account **Disattivato** (predefinito), **Come lo spazio** o **Sempre tramite Tor**. Così tutto l’account passa da Tor, anche le sue foto e i suoi file, e anche la pagina di accesso di Messenger e la registrazione, il captcha e il collegamento di Signal: mai diretto quando non deve. **Tramite Tor** in ciascuna delle loro chat, disattivato per impostazione predefinita, manda tutto l’account solo tramite Tor finché è attivo, perché ognuno ha una sola connessione. Le chiamate non passano da Tor.",
  "**Telegram: Tor as every account, and per chat**: on Android, **Tor for this Telegram account**, in Telegram's settings and before signing in, has **Off** (the default), **As the space** and **Always through Tor**, as every account of another network. With Always, or while the space sends Everything through Tor, Telegram is reached only through Tor, signing in too, and never straight, not even when Tor cannot connect. **Through Tor** in a Telegram chat's info sends that chat only through Tor, and with it the whole account, which has one connection. Calls do not go through Tor. See [Telegram (ErevosGram)](#telegram).":
    "**Telegram: Tor come per ogni account, e per chat**: su Android, **Tor per questo account Telegram**, nelle impostazioni di Telegram e prima di accedere, ha **Disattivato** (all'inizio), **Come lo spazio** e **Sempre tramite Tor**, come ogni account di un'altra rete. Con Sempre, o finché lo spazio manda Tutto tramite Tor, Telegram si raggiunge solo tramite Tor, anche all'accesso, e mai direttamente, nemmeno quando Tor non riesce a connettersi. **Tramite Tor** nelle informazioni di una chat Telegram fa passare quella chat solo da Tor, e con essa tutto l'account, che ha una sola connessione. Le chiamate non passano da Tor. Vedi [Telegram (ErevosGram)](#telegram).",
  "**Nostr: Tor as every account, and per chat**: on Android, the **Nostr chats** screen, before a key is made or brought too, has **Off** (the default, also for keys from before), **As the space** and **Always through Tor** for the account: its relays, look-ups and file servers, never straight when it must not (Always, or the space's Everything). **Through Tor** at the foot of a Nostr chat, off by default, sends that chat alone only through Tor, on circuits of its own, whatever the account says; what comes to you follows the account. See [Chats with other Nostr apps](#nostr-chats).":
    "**Nostr: Tor come per ogni account, e per chat**: su Android, la schermata **Chat Nostr**, anche prima di creare o portare una chiave, ha **Disattivato** (il predefinito, anche per le chiavi di prima), **Come lo spazio** e **Sempre tramite Tor** per l’account: i suoi relay, le ricerche e i server di file, mai diretto quando non deve (Sempre, o il Tutto dello spazio). **Tramite Tor** in fondo a una chat Nostr, disattivato di default, invia solo quella chat esclusivamente tramite Tor, su circuiti propri, qualunque cosa dica l’account; ciò che arriva a te segue l’account. Vedi [Chat con altre app Nostr](#nostr-chats).",
  "**Telegram warns before your internet address can be seen**: once in each Telegram chat, before the first message, file, sticker, voice message, poll or forward while the account does not go through Tor, with **Through Tor** for that chat to fix it, **Guide** or **Go on**; before every Telegram call, made or answered, as calls never go through Tor; and before joining a group or channel by its link. See [Who sees your internet address](#ip).":
    "**Telegram avvisa prima che il tuo indirizzo internet si possa vedere**: una volta in ogni chat Telegram, prima del primo messaggio, file, sticker, messaggio vocale, sondaggio o inoltro finché l'account non passa da Tor, con **Tramite Tor** per quella chat come rimedio, **Guida** o **Vai avanti**; prima di ogni chiamata Telegram, fatta o ricevuta, perché le chiamate non passano mai da Tor; e prima di entrare in un gruppo o canale dal suo link. Vedi [Chi vede il tuo indirizzo internet](#ip).",
  "**Erevos or Erevos+, and betas, in Updates**: on Android, **Updates** now chooses the next update: **Erevos** or **Erevos+**, moving from one to the other with everything kept, and **Beta versions**, to join the betas, which come out first for trying, or leave them. See [Erevos or Erevos+, and betas](#updates).": "**Erevos o Erevos+, e beta, in Aggiornamenti**: su Android, **Aggiornamenti** sceglie ora il prossimo aggiornamento: **Erevos** o **Erevos+**, passando dall’uno all’altro senza perdere nulla, e **Versioni beta**, per partecipare alle beta, che escono prima per provare, o uscirne. Vedi [Erevos o Erevos+, e beta](#updates).",
  "**Matrix, XMPP and Nostr chats are in Erevos+**: Erevos now has its own chats, the Phone, SMS and the Collection, and Erevos+ has Matrix, XMPP and the chats with other Nostr apps besides. An account you had on them stays on the phone, encrypted, and Erevos says so once; choose **Erevos+** in **Updates** to have it again. Erevos's own messages still go through Nostr relays when no relay of yours takes them. See [Erevos or Erevos+, and betas](#updates).": "**Le chat Matrix, XMPP e Nostr sono in Erevos+**: Erevos ha ora le sue chat, il Telefono, gli SMS e la Raccolta, ed Erevos+ ha in più Matrix, XMPP e le chat con altre app Nostr. Un account che avevi lì resta sul telefono, cifrato, ed Erevos lo dice una volta; scegli **Erevos+** in **Aggiornamenti** per riaverlo. I messaggi di Erevos passano ancora dai relay Nostr quando nessun tuo relay li prende. Vedi [Erevos o Erevos+, e beta](#updates).",
  "**Radio and TV through Tor**: the Collection's settings on Android have **Play through Tor**, off unless you turn it on. On, stations and channels play only through Tor, so they do not see your IP address; TV may stall for a moment. Off, Erevos says before the first one plays that its server sees your IP address, with a button that turns it on. Before, they always played straight. See [Collection](#collection).": "**Radio e TV tramite Tor**: le impostazioni della Raccolta su Android hanno **Riproduci tramite Tor**, disattivato finché non lo attivi. Attivo, le stazioni e i canali si riproducono solo tramite Tor, quindi non vedono il tuo indirizzo IP; la TV può bloccarsi per un momento. Disattivato, Erevos dice prima che parta il primo che il suo server vede il tuo indirizzo IP, con un pulsante che lo attiva. Prima andavano sempre in modo diretto. Vedi [Raccolta](#collection).",
  "**A chat no longer freezes before a message sent for later shows**: a message your contact sends with **Send later** can come before its time, and shows only then. Until then its chat was marked read again and again without end, so it could stop answering: **⋮** opened nothing and **Back** did not leave it until Erevos was closed. Now such a message is read once it shows. See [Chat through a relay](#relay).": "**Una chat non si blocca più prima che compaia un messaggio inviato per più tardi**: un messaggio che il tuo contatto invia con **Invia più tardi** può arrivare prima della sua ora, e compare solo allora. Fino ad allora la sua chat veniva segnata come letta ancora e ancora, senza fine, così poteva smettere di rispondere: **⋮** non apriva nulla e **Indietro** non ne usciva finché Erevos non veniva chiuso. Ora un messaggio così viene letto appena compare. Vedi [Chat tramite un relay](#relay).",
  "**Choose the part Erevos opens on**: under **All services**, hold any card, **All messages** too, and choose **Opens first**. Erevos's icon in the launcher, and Erevos started with nothing else to open, then open on it; with none chosen, or the chosen one hidden, on **All messages**. Before, the icon always opened the Erevos chats. The widget's buttons still open their own. See [Getting started](#start).": "**Scegli dove si apre Erevos**: in **Tutti i servizi**, tieni premuta una scheda qualsiasi, anche **Tutti**, e scegli **Si apre per prima**. L’icona di Erevos nel launcher, ed Erevos avviato senza nient’altro da aprire, si aprono allora lì; senza scelta, o se quella scelta è nascosta, su **Tutti**. Prima, l’icona apriva sempre le chat di Erevos. I pulsanti del widget aprono ancora i loro. Vedi [Per iniziare](#start).",
  "**Asked before strangers reach this phone**: an Erevos invite that comes by SMS is answered by itself only from a number in your contacts or one you have written to; from any other, Erevos asks first, as the sender of an SMS can be made up. A contact's invite to a place on their relay now says first that their relay sees your IP address, and is taken only if you go on. See [Who sees your internet address](#ip).": "**Si chiede prima che degli sconosciuti raggiungano questo telefono**: un invito Erevos che arriva per SMS riceve risposta da solo soltanto da un numero tra i tuoi contatti o da uno a cui hai scritto; da ogni altro, Erevos chiede prima, perché il mittente di un SMS può essere inventato. L’invito di un contatto a un posto sul suo relay ora dice prima che il suo relay vede il tuo indirizzo IP, e viene accettato solo se vai avanti. Vedi [Chi vede il tuo indirizzo internet](#ip).",
  "**Notices in your language**: Android's own notices and screens, new versions, reminders, birthdays, calls, SMS codes and the contact picker, now speak German, Spanish, French, Italian, Portuguese and Serbo-Croatian too, not only Greek and English. Older Greek subtitles, not saved as UTF-8, now show as Greek on the computer. See [Collection](#collection).": "**Avvisi nella tua lingua**: gli avvisi e le schermate di Android stesso, le nuove versioni, i promemoria, i compleanni, le chiamate, i codici SMS e il selettore dei contatti ora parlano anche tedesco, spagnolo, francese, italiano, portoghese e serbo-croato, non solo greco e inglese. I vecchi sottotitoli greci, non salvati in UTF-8, ora si vedono come greco sul computer. Vedi [Raccolta](#collection).",
  "**Video calls on the computer, and the calculator after a wipe**: a video call started or answered on the computer now opens its camera. With the calculator in place of Erevos's icon, once Erevos is wiped by the panic password or **Clear storage**, the calculator opens Erevos as new and gives Erevos's icon back, where before no code opened it any more. See [Appearance](#appearance).": "**Videochiamate sul computer, e la calcolatrice dopo una cancellazione**: una videochiamata avviata o accettata sul computer ora apre la sua fotocamera. Con la calcolatrice al posto dell’icona di Erevos, una volta cancellato Erevos con la password di panico o con **Cancella spazio di archiviazione**, la calcolatrice apre Erevos come nuovo e restituisce l’icona di Erevos, dove prima nessun codice lo apriva più. Vedi [Aspetto](#appearance).",
  "**Last seen starts off**: in a new space, **Last seen** is now off until you turn it on, so no contact sees when you last had Erevos open, and you see no one's either. A space you already have keeps it as it was. See [Chat through a relay](#relay).": "**Ultimo accesso parte disattivato**: in un nuovo spazio, **Ultimo accesso** ora è disattivato finché non lo attivi, così nessun contatto vede quando hai avuto Erevos aperto l’ultima volta, e tu non vedi quello di nessuno. Uno spazio che hai già lo tiene com’era. Vedi [Chat tramite un relay](#relay).",
  "**A chat with a big file no longer closes Erevos**: on Android, opening a chat that held a large file, or one shared in many pieces, could close Erevos at once. Now it opens. See [Chat through a relay](#relay).": "**Una chat con un file grande non chiude più Erevos**: su Android, aprire una chat con un file grande, o condiviso in molti pezzi, poteva chiudere subito Erevos. Ora si apre. Vedi [Chat tramite un relay](#relay).",
  "**A hidden service stays quiet**: a service you hide in the **Services** window, Messenger, Matrix, SMS or any other, no longer sends notifications or counts on Erevos's icon, as a muted chat. It stays connected and tells again once you show it. Telegram, whose folders can stand on home of their own, keeps telling. See [Getting started](#start).": "**Un servizio nascosto resta in silenzio**: un servizio che nascondi nella finestra **Servizi**, Messenger, Matrix, SMS o un altro, non invia più notifiche né conta nel numero sull’icona di Erevos, come una chat silenziata. Resta connesso e avvisa di nuovo appena lo mostri. Telegram, le cui cartelle possono stare nella home come servizi a sé, continua ad avvisare. Vedi [Getting started](#start).",
  "**Screenshots in hidden chats too, if you want**: hidden chats now follow **Screenshots** in **Privacy and security**: on, as it starts, they stay out of screenshots and the recent apps; turned off, screenshots work in them as in the other chats. Before, hidden chats always kept them out. See [Hidden chats](#hidden).": "**Screenshot anche nelle chat nascoste, se vuoi**: le chat nascoste ora seguono **Screenshot** in **Privacy e sicurezza**: attivo, come all’inizio, restano fuori dagli screenshot e dalle app recenti; disattivato, gli screenshot funzionano anche lì come nelle altre chat. Prima le chat nascoste li bloccavano sempre. Vedi [Chat nascoste](#hidden).",
  "**Messenger signs in on facebook.com, and opens Facebook**: in Erevos+, Messenger now signs in on Facebook's own page. **Open Facebook** on the Messenger screen shows Facebook itself with the same sign-in: its Messenger links come back to Erevos's chats, and other links open in your browser without Facebook's tracking marks and never through Tor, so the site sees your internet address. An account signed in on messenger.com before signs out and in again once to open Facebook.":
    "**Messenger accede su facebook.com e apre Facebook**: in Erevos+, Messenger ora accede sulla pagina di Facebook stessa. **Apri Facebook** nella schermata di Messenger mostra Facebook stesso con lo stesso accesso: i suoi link di Messenger tornano alle chat di Erevos, e gli altri link si aprono nel tuo browser senza i segni di tracciamento di Facebook e mai tramite Tor, quindi il sito vede il tuo indirizzo internet. Un account che ha fatto l’accesso prima su messenger.com esce e rientra una volta per aprire Facebook.",
  "**Messenger, Signal and Session chats send more, and stay read**: in Erevos+, **+** in their chats sends a photo from your photos or the camera, a file or a sticker, and the microphone records a voice message. Your own messages show their words, where before some came empty; tapping a person with no Messenger chat yet opens a new one; and chats you mark read no longer come back unread.":
    "**Le chat di Messenger, Signal e Session inviano di più e restano lette**: in Erevos+, **+** nelle loro chat invia una foto dalle tue foto o dalla fotocamera, un file o uno sticker, e il microfono registra un messaggio vocale. I tuoi messaggi mostrano le loro parole, dove prima alcuni arrivavano vuoti; toccare una persona senza chat di Messenger ne apre una nuova; e le chat che segni come lette non tornano più da leggere.",
  "**Every copy carries its licences**: the Android app, the computer and Sailfish apps and the web app now carry the file NOTICES.txt, with Erevos's licence, AUTHORS.md and every package Erevos is built from, each with its licence text. See [Licence](#licence).": "**Ogni copia porta le sue licenze**: l’app Android, le app per computer e Sailfish e l’app web contengono ora il file NOTICES.txt, con la licenza di Erevos, AUTHORS.md e ogni pacchetto con cui è fatto Erevos, ciascuno con il testo della sua licenza. Vedi [Licenza](#licence).",
  "**A ready list of radio stations**: **Add a station** in the Collection's Radio now adds a country's most listened stations from Radio Browser at once, up to 100, with **Add the stations of this country**; the country is the phone's, and **Change** picks another. See [Collection](#collection).": "**Una lista pronta di stazioni radio**: **Aggiungi una stazione** nella Radio della Raccolta aggiunge ora in una volta le stazioni più ascoltate di un paese da Radio Browser, fino a 100, con **Aggiungi le stazioni di questo paese**; il paese è quello del telefono, e **Cambia** ne sceglie un altro. Vedi [Raccolta](#collection).",
  "**A new look to start with**: Erevos, newly installed, starts in Glass (Panes), Modernist, System, My color in sky blue, the phone's letters and square messages. A look you chose before stays as it was. See [Appearance](#appearance).": "**Un nuovo aspetto per iniziare**: Erevos appena installato parte con Glass (Lastre), Modernist, Sistema, Il mio colore in azzurro, il carattere del telefono e messaggi squadrati. Un aspetto scelto prima resta com’era. Vedi [Aspetto](#appearance).",
  "**Modules names only what Erevos has**: under **Settings** → **General**, **Modules** no longer lists Nostr, Matrix and XMPP, which are in Erevos+.": "**Moduli nomina solo ciò che Erevos ha**: in **Impostazioni** → **Generali**, **Moduli** non nomina più Nostr, Matrix e XMPP, che sono in Erevos+.",
  "**The guide tells only of what Erevos has**: in Erevos, the user guide no longer speaks of Matrix, XMPP and the chats with other Nostr apps, which are in Erevos+. See [Erevos or Erevos+, and betas](#updates).": "**La guida parla solo di ciò che Erevos ha**: in Erevos, la guida non parla più di Matrix, XMPP e delle chat con altre app Nostr, che sono in Erevos+. Vedi [Erevos o Erevos+, e beta](#updates).",
  "**Meeting someone in one tap**: **New chat** now starts with two big buttons, **Scan their QR code** and **Show your QR code**; one of you scanning the other is enough, and the rest is under them. See [Chat through a relay](#relay).": "**Conoscere qualcuno con un tocco**: **Nuova chat** ora inizia con due grandi pulsanti, **Scansiona il suo codice QR** e **Mostra il tuo codice QR**; basta che uno dei due scansioni l’altro, e il resto è sotto. Vedi [Chat tramite un relay](#relay).",
  "**The panic button, found at once**: it is first, in red, in the **⋯** menu of the home screen, and holding down the lock at the top of the home screen opens it. See [Panic button](#panic).": "**Il pulsante di panico, subito**: è il primo, in rosso, nel menu **⋯** della schermata iniziale, e tenendo premuto il lucchetto in alto nella schermata iniziale si apre. Vedi [Pulsante di panico](#panic).",
  "**New chat looks the same every time**: the two big buttons are always at the top; **How you connect now** shows only while something is missing, and says it in plain words; **Your contact link** and **Invite someone** are rows, with no second QR code button. See [Chat through a relay](#relay).": "**La nuova chat ha sempre lo stesso aspetto**: i due grandi pulsanti sono sempre in alto; **Come ti colleghi ora** compare solo finché manca qualcosa, e lo dice con parole semplici; **Il tuo link di contatto** e **Invita qualcuno** sono righe, senza un secondo pulsante per il codice QR. Vedi [Chat tramite un relay](#relay).",
  "**One scan is all**: where your relay lets your phone invite, **Show your QR code** shows an invite for one person, so a phone new to Erevos joins your relay by itself as it scans it, typing nothing, and you are contacts at once; for someone else, tap **New QR code**. And with a relay, its queue is made by itself: **Create my relay queue** is there only to try again, should that fail. See [Chat through a relay](#relay).": "**Una sola scansione basta**: dove il tuo relay lascia invitare al tuo telefono, **Mostra il tuo codice QR** mostra un invito per una persona, così un telefono nuovo su Erevos entra da solo nel tuo relay scansionandolo, senza digitare nulla, e siete subito contatti; per qualcun altro, tocca **Nuovo codice QR**. E con un relay, la sua coda si crea da sola: **Crea la mia coda sul relay** resta solo per riprovare, se non riesce. Vedi [Chat tramite un relay](#relay).",
  "**Video calls take about half the data**: a video call over the internet goes through the call relay, so that neither side sees the other's address; its picture is now held to 1 Mbps, which on a phone looks much the same. A call on the same network is not held back.": "**Le videochiamate usano circa la metà dei dati**: una videochiamata via internet passa dal relay delle chiamate, così che nessuno dei due veda l’indirizzo dell’altro; la sua immagine ora è limitata a 1 Mbps, che su un telefono sembra quasi uguale. Una chiamata sulla stessa rete non è limitata.",
  "**A stranger's message shows only its words**: a message request, from someone who has only your contact link, shows only what it says until you accept it. Its photos and files wait, not taken, and its links show no preview. See [Chat through a relay](#relay).": "**Il messaggio di uno sconosciuto mostra solo le sue parole**: una richiesta di messaggio, da qualcuno che ha solo il tuo link di contatto, mostra solo ciò che dice finché non la accetti. Foto e file aspettano senza essere scaricati, e i link non mostrano anteprima. Vedi [Chat tramite un relay](#relay).",
  "**Photos sent as files say nothing of where they were taken**: a photo sent with **File** (JPEG, PNG, GIF or WebP) goes without where and when it was taken and the phone, as a photo does; a GIF sent as a photo keeps moving, now without its hidden notes.": "**Le foto inviate come file non dicono dove sono state scattate**: una foto inviata con **File** (JPEG, PNG, GIF o WebP) parte senza luogo, ora e telefono, come una foto; una GIF inviata come foto continua a muoversi, ora senza le sue note nascoste.",
  "**A word of care over a stranger's first messages**: if a message request asks for a code, a PIN, a password or money, promises easy money, or its name looks like one of your contacts', **Be careful** says so above it. Erevos looks for this on your phone only, and blocks nothing. See [Chat through a relay](#relay).": "**Un avviso sui primi messaggi di uno sconosciuto**: se una richiesta di messaggio chiede un codice, un PIN, una password o soldi, promette soldi facili, o il nome somiglia a quello di un tuo contatto, **Attenzione** lo dice sopra. Erevos lo cerca solo sul tuo telefono, e non blocca nulla. Vedi [Chat tramite un relay](#relay).",
  "**Tor finds its own way through**: under **Bridges**, **Automatic** tries Tor straight, then the obfs4 bridges, then Snowflake, then your own, until one connects, and remembers for 30 days the one that worked on Wi-Fi and on mobile data. **My network is watched** makes it never try straight, and **Check my connection** says whether Tor connects, and how, never your address. See [Through Tor](#tor).": "**Tor trova da solo la strada**: in **Bridge**, **Automatico** prova Tor diretto, poi i bridge obfs4, poi Snowflake, poi i tuoi, finché uno si connette, e ricorda per 30 giorni quello che ha funzionato su Wi-Fi e su dati mobili. **La mia rete è sorvegliata** fa sì che non provi mai diretto, e **Controlla la mia connessione** dice se Tor si connette, e come, mai il tuo indirizzo. Vedi [Tramite Tor](#tor).",
  "**The bar at the top stays**: on the home screen, the bar with Erevos and its buttons no longer scrolls away with the list, and in SMS chats, as in those of the other networks, the name of the chat, its calls and who is online stay at the top while the messages scroll, as in Erevos's own chats.": "**La barra in alto resta ferma**: nella schermata iniziale, la barra con Erevos e i suoi pulsanti non scorre più via con la lista, e nelle chat SMS, come in quelle delle altre reti, il nome della chat, le sue chiamate e chi è online restano in alto mentre i messaggi scorrono, come nelle chat proprie di Erevos.",
  "**A simpler field in Matrix and XMPP chats**: under it there is only **+**, for photos, files and the rest, and the microphone; the chat's settings are under **⋯** at the top.": "**Un campo più semplice nelle chat Matrix e XMPP**: sotto ci sono solo **+**, per foto, file e il resto, e il microfono; le impostazioni della chat sono in alto, sotto **⋯**.",
  "**Adding a contact with 8 digits**: **Pair with a code** on **New chat** lets one phone show a code of 8 digits and the other type it, said aloud or read off the screen, and you are each other's contacts, with no QR code or link to pass. The code never leaves the phones, and whoever guesses gets 3 tries. See [Chat through a relay](#relay).": "**Aggiungere un contatto con 8 cifre**: **Abbina con un codice** in **Nuova chat** fa mostrare a un telefono un codice di 8 cifre e all’altro digitarlo, detto ad alta voce o letto dallo schermo, e siete l’uno il contatto dell’altro, senza codice QR né link da passare. Il codice non lascia mai i telefoni, e chi tira a indovinare ha 3 tentativi. Vedi [Chat tramite un relay](#relay).",
  "**A voice not your own**: in a contact's chat details, **Change my voice** sends your voice messages in that chat **Deeper** or **Higher**, as long as you spoke. The change is made on your phone before the message goes, so your own voice never leaves it. On Android 10 and later, and in browsers that make Opus themselves. See [Chat through a relay](#relay).": "**Una voce non tua**: nei dettagli della chat con un contatto, **Cambia la mia voce** invia i tuoi messaggi vocali in quella chat **Più grave** o **Più acuta**, della stessa durata. Il cambio avviene sul telefono prima che il messaggio parta, quindi la tua voce non lo lascia mai. Su Android 10 e successivi, e nei browser che creano Opus da sé. Vedi [Chat tramite un relay](#relay).",
  "**A word of care under a short password**: setting the password of a space or the PIN of hidden chats, Erevos now says when it is short: someone who breaks into the phone's own security could guess it on computers of their own. A phrase of 4 or 5 words is far safer. It still takes a short one. See [Password lock](#lock).": "**Un avviso sotto una password breve**: impostando la password di uno spazio o il PIN delle chat nascoste, Erevos ora dice quando è breve: chi viola la sicurezza del telefono stesso potrebbe indovinarla su computer propri. Una frase di 4 o 5 parole è molto più sicura. Una breve la accetta comunque. Vedi [Blocco con password](#lock).",
  "**Groups that end**: a public group can now be a burner group, for one event. Under **It ends**, choose after a day, 3 days or 7 days, and when its time is up every member's Erevos deletes it, with its messages, photos and files, and its link stops working. See [public groups](#public-groups).": "**Gruppi che finiscono**: un gruppo pubblico ora può essere usa e getta, per un’occasione. In **Finisce** scegli dopo un giorno, 3 giorni o 7 giorni, e quando il suo tempo finisce l’Erevos di ogni membro lo elimina, con i suoi messaggi, foto e file, e il suo link smette di funzionare. Vedi [Gruppi pubblici](#public-groups).",
  "**A photo to see once**: under **+** in a chat or a group, **Photo to see once** sends a photo that never shows in the chat, and **Camera, to see once** one you take then. They see it once, on its own, kept out of screenshots where the phone allows, and as it closes it is deleted from their phone. It cannot be forwarded or saved. See [Chat through a relay](#relay).": "**Una foto da vedere una volta**: sotto **+** in una chat o in un gruppo, **Foto da vedere una volta** invia una foto che non appare mai in chat, e **Fotocamera, da vedere una volta** una che scatti sul momento. La vedono una volta, da sola, senza screenshot dove il telefono lo consente, e quando si chiude viene eliminata dal loro telefono. Non si può inoltrare né salvare. Vedi [Chat tramite un relay](#relay).",
  "**Threads in a contact's chat too**: hold a message and choose **Reply in thread**, as in a group. The thread shows alone and what you send there answers it; **n answers in the thread** under a message opens it. See [Chat through a relay](#relay).": "**Thread anche nella chat con un contatto**: tieni premuto un messaggio e scegli **Rispondi nel thread**, come in un gruppo. Il thread si vede da solo e quello che invii lì gli risponde; **n risposte nel thread** sotto un messaggio lo apre. Vedi [Chat tramite un relay](#relay).",
  "**A voice message in words**: hold a voice message and choose **In words**, and your phone writes out what was said, in about a hundred languages, Greek among them. The first time it downloads a speech model of 268 MB, once you say so; then everything is done on your phone, and neither the sound nor its words leave it. On Android. See [Chat through a relay](#relay).": "**Un messaggio vocale in parole**: tieni premuto un messaggio vocale e scegli **In parole**, e il telefono scrive ciò che è stato detto, in circa cento lingue, tra cui il greco. La prima volta scarica un modello vocale di 268 MB, quando lo dici tu; poi tutto avviene sul tuo telefono, e né il suono né le sue parole lo lasciano. Su Android. Vedi [Chat tramite un relay](#relay).",
  "**Translate a message**: hold a message and choose **Translate**, and your phone translates it into your language, between Greek, English, German, Spanish, French and Italian. The first time for a language it downloads its translation models, of 60 to 95 MB each, once you say so; then everything is done on your phone, and neither the message nor its translation leave it. On Android. See [Chat through a relay](#relay).": "**Tradurre un messaggio**: tieni premuto un messaggio e scegli **Traduci**, e il telefono lo traduce nella tua lingua, tra greco, inglese, tedesco, spagnolo, francese e italiano. La prima volta per una lingua scarica i suoi modelli di traduzione, da 60 a 95 MB ciascuno, quando lo dici; poi tutto avviene sul telefono, e né il messaggio né la sua traduzione lo lasciano. Su Android. Vedi [Chat tramite un relay](#relay).",
  "**Phones nearby carry for each other from the start**: **Carry messages for others**, under **Nearby, with no internet** on **New chat**, is now on until you turn it off, so a message that cannot reach its relay finds more phones to take it there. What this phone carries is sealed: it cannot read it, nor tell who it is from or for. See [Chat with a nearby phone](#nearby).": "**I telefoni vicini trasportano l’uno per l’altro fin dall’inizio**: **Trasporta messaggi per altri**, sotto **Vicino, senza internet** in **Nuova chat**, ora è attivo finché non lo disattivi, così un messaggio che non raggiunge il suo relay trova più telefoni che ce lo portano. Ciò che questo telefono trasporta è cifrato: non può leggerlo, né sapere da chi viene o per chi è. Vedi [Chat con un telefono vicino](#nearby).",
  "**Last seen is when they closed Erevos**: with **Say when I open and close Erevos** on, closing Erevos, or its hidden chats, now tells those you told while it was open when it closed, so their **last seen** is that time, not when they last heard from you. And you show online only while the chats they talk to you in are open: not while your hidden chats are open instead. See [Chat through a relay](#relay).": "**L’ultimo accesso è quando hanno chiuso Erevos**: con **Dire quando apro e chiudo Erevos** attivo, chiudere Erevos, o le sue chat nascoste, ora dice a chi è stato avvisato mentre era aperto quando si è chiuso, così il suo **Ultimo accesso** è quell’ora, non l’ultima volta che ha avuto tue notizie. E appari online solo finché sono aperte le chat in cui ti parlano: non mentre al loro posto sono aperte le tue chat nascoste. Vedi [Chat tramite un relay](#relay).",
  "**Sign in at another relay**: under **Sign in with LPHL** on New chat, **Sign in at another relay…** takes another relay's address, and the card signs in there with the accounts that relay takes; one that takes none says so, and its operator can give you an invite. See [Chat through a relay](#relay).": "**Accedi a un altro relay**: sotto **Accedi con LPHL** in Nuova chat, **Accedi a un altro relay…** prende l’indirizzo di un altro relay, e la scheda accede lì con gli account che quel relay accetta; uno che non ne accetta nessuno lo dice, e chi lo gestisce può darti un invito. Vedi [Chat tramite un relay](#relay).",
  "**Post-quantum, all the way**: between two phones on this Erevos, every message of a chat is now also locked with a fresh ML-KEM key, a new one every few dozen messages, not only at the start. So someone who records your messages today and has a quantum computer one day still cannot read them. By itself, with nothing to turn on; not in groups.": "**Post-quantistico dall’inizio alla fine**: tra due telefoni con questo Erevos, ogni messaggio di una chat è ora cifrato anche con una nuova chiave ML-KEM, che cambia ogni poche decine di messaggi, non solo all’inizio. Così chi registra oggi i tuoi messaggi e un giorno avrà un computer quantistico non potrà comunque leggerli. Da solo, niente da attivare; non nei gruppi.",
  "**The Collection asks for your password**: where the space has a password, the Collection asks for it each time it opens, and again after Erevos was away more than 30 seconds; a fingerprint or face works too. See [Collection](#collection).": "**La Raccolta chiede la tua password**: dove lo spazio ha una password, la Raccolta la chiede ogni volta che si apre, e di nuovo quando Erevos è rimasto lasciato per più di 30 secondi; vanno anche impronta o volto. Vedi [Collection](#collection).",
  "**Messenger in its case**: in Erevos+, Messenger can now be used in its case instead of by Erevos: Meta's own Messenger page, as on a computer, closed in by Erevos with the same sign-in. Only Meta's sites load in it, links out open in your browser without Facebook's tracking marks, nothing of the sign-in stays in it once closed, and calls work in it. Choose it on the Messenger screen under **How Messenger is used here**; its chats are then not in Erevos's lists and Erevos does not notify of them. Through Tor, if Messenger goes through Tor, and then without calls.":
    "**Messenger nella sua custodia**: in Erevos+ Messenger ora può essere usato nella sua custodia invece che da Erevos: la pagina Messenger di Meta stessa, come su un computer, chiusa dentro Erevos con lo stesso accesso. Vi si caricano solo i siti di Meta, i link verso l'esterno si aprono nel tuo browser senza i segni di tracciamento di Facebook, niente dell'accesso vi resta una volta chiusa, e le chiamate funzionano al suo interno. Sceglilo nella schermata di Messenger in **Come si usa Messenger qui**; le sue chat allora non sono negli elenchi di Erevos ed Erevos non ne avvisa. Tramite Tor, se Messenger passa per Tor, e allora senza chiamate.",
  "**Messenger chats you read stay read**: a Messenger chat you marked read right after Erevos+ started, while Messenger was still connecting, no longer comes back as unread; a chat whose last message is yours, sent from Messenger's own app or the web, is read; and encrypted chats you read in Messenger's app or on the web are read here too.":
    "**Le chat di Messenger lette restano lette**: una chat di Messenger segnata come letta subito dopo l'avvio di Erevos+, mentre Messenger si stava ancora collegando, non torna più non letta; una chat il cui ultimo messaggio è tuo, inviato dall'app di Messenger o dal web, è letta; e le chat cifrate lette nell'app di Messenger o sul web sono lette anche qui.",
  "**Messenger in its case fits the phone, and Facebook's feed is a tap away**: in Erevos+, Messenger in its case is now laid out at the phone's width, so it reads without zooming in, and shows under Erevos's own bar, in its colours, with **←** back to Erevos and **Facebook** to see Facebook's feed in the same page. Facebook also has a card of its own in the **Services** window, beside Messenger. See [Messenger](#messenger).":
    "**Messenger nella sua custodia sta nel telefono, e il feed di Facebook è a un tocco**: in Erevos+, Messenger nella sua custodia è ora disposto alla larghezza del telefono, così si legge senza ingrandire, e si mostra sotto la barra di Erevos, con i suoi colori, con **←** per tornare a Erevos e **Facebook** per vedere il feed di Facebook nella stessa pagina. Facebook ha anche una sua scheda nella finestra **Servizi**, accanto a Messenger. Vedi [Messenger](#messenger).",
  "**Messenger in its case asks for the PIN once**: in Erevos+, what Meta's page keeps now stays in the case between openings, apart from every other page, so Meta knows your phone again and no longer asks for the PIN of your encrypted chats each time you open it. It goes when you sign out of Messenger, or when another account opens the case. See [Messenger](#messenger).":
    "**Messenger nella sua custodia chiede il PIN una volta sola**: in Erevos+, ciò che la pagina di Meta conserva ora resta nella custodia da un’apertura all’altra, separato da ogni altra pagina, così Meta riconosce il tuo telefono e non chiede più il PIN delle tue chat cifrate ogni volta che la apri. Se ne va quando esci da Messenger o quando un altro account apre la custodia. Vedi [Messenger](#messenger).",
  "**Messenger in its case wears your whole look**: in Erevos+, Meta's own Messenger page in its case now takes your look: its colours, dark or light as Erevos is, the shape of your bubbles (round, square or a line), your text size, your style's letters, and what lies behind your screens (a wallpaper, Neon's grid, Paper's lines and the others), and it changes with your look even while it is open. A photo of your own stays in Erevos: there the page shows a soft gradient instead. Where Meta changes its page, parts of it may keep Meta's look. See [Messenger](#messenger).":
    "**Messenger nella sua custodia veste tutto il tuo aspetto**: in Erevos+, la pagina di Messenger di Meta nella sua custodia ora prende il tuo aspetto: i suoi colori, scura o chiara come Erevos, la forma delle tue bolle (rotonde, quadrate o una linea), la dimensione del testo, le lettere del tuo stile e ciò che sta dietro le tue schermate (uno sfondo, la griglia di Neon, le righe di Paper e gli altri), e cambia con il tuo aspetto anche mentre è aperta. Una tua foto resta in Erevos: lì la pagina mostra invece una sfumatura morbida. Dove Meta cambia la sua pagina, alcune parti possono mantenere l’aspetto di Meta. Vedi [Messenger](#messenger).",
  "**Messenger in its case tells you of new messages**: in Erevos+, when you use Messenger in its case, Erevos now tells you of its new messages as it does of other chats, even if you never opened the case. A chat with messages not read shows on home until it is read, and tapping it opens it in the case; while the case is open, Erevos tells of nothing, as the page shows it. See [Messenger](#messenger).":
    "**Messenger nella sua custodia ti avvisa dei nuovi messaggi**: in Erevos+, quando usi Messenger nella sua custodia, Erevos ora ti avvisa dei suoi nuovi messaggi come delle altre chat, anche se non hai mai aperto la custodia. Una chat con messaggi non letti compare nella schermata iniziale finché non viene letta, e toccandola si apre nella custodia; mentre la custodia è aperta, Erevos non avvisa, perché la pagina li mostra già. Vedi [Messenger](#messenger).",
};
